 const following=!!(!bardOwnsMusic()&&MUSIC.on&&MUSIC.user>0&&MUSIC.cur&&M_PIECES[MUSIC.cur]);
 const map=following?MUSIC.cur:M_PIECES[MUSIC.want]?MUSIC.want:'britannia',piece=M_PIECES[map],slot=30/piece.bpm;
