  s=p.bardMusic={key,map:clock.map,stance:p.stance,following:clock.following,origin,slot:clock.slot,nextSlot:Math.max(0,Math.ceil((now+.025-origin)/clock.slot)),lastEvent:now,intensity:0,accent:0,finale:false,ending:false,lastPlan:null,played:0,skipped:0};
