function bardLeadMix(active){if(MUSIC.leadBus&&AC)MUSIC.leadBus.gain.setTargetAtTime(active?.08:1,AC.currentTime,active?.035:.18);}
function stopBardMusic(){
 if(G&&G.p&&G.p.bardMusic&&G.p.bardMusic.arrangementVoice&&AC){const s=G.p.bardMusic;G.p.bardTrackOffsets=G.p.bardTrackOffsets||{};G.p.bardTrackOffsets[s.trackId]=(s.arrangementOffset+Math.max(0,AC.currentTime-s.arrangementAt))%s.arrangementDuration;}
 bardLeadMix(false);
 clearTimeout(BARD_CONDUCTOR.timer);BARD_CONDUCTOR.timer=null;
 if(AC)for(const v of BARD_CONDUCTOR.voices)bardDampVoice(v,AC.currentTime);
 if(G&&G.p)G.p.bardMusic=null;
}
function bardPlan(s,slot){
 const song=s.map==='sonic'?bardSoloSong(s,slot):null,P=song||M_PIECES[s.map],bar=Math.floor((slot-(song?s.songStartSlot:0))/P.slots)%P.chords.length,beat=slot%P.slots,name=P.chords[bar],ch=M_CHORD[name],row=song?song.melody[bar]:BARD_SCORES[s.map][bar],melody=row[beat];
 const strong=beat%2===0,finisher=s.map!=='sonic'&&s.finale,accent=s.map!=='sonic'&&(finisher||strong&&s.accent>0),peace=s.stance==='b_peace';
 let notes=melody?[melody]:[],style='pluck',gate=peace?2:1;
 if(melody){let space=1;while(beat+space<P.slots&&!row[beat+space])space++;gate=space*s.slot>.75?3:space*s.slot>.4?2:1;}
 // Keep the written rests. Busy combat can add one beat-aligned chord, not a
 // separate melody for every skill or echo. Rank never creates extra lead notes.
 if(accent){notes=[ch[0],ch[1],ch[3],...notes];style=peace?'gentle':'strum';gate=2;s.accent=0;s.finale=false;}
 else if(s.map!=='sonic'&&melody&&beat===0&&s.intensity>1.3){notes=[ch[1],...notes];style=peace?'gentle':'pluck';}
 notes=[...new Set(notes)].sort((a,b)=>a-b);
 s.intensity=Math.max(0,s.intensity-.35);
 return {slot,bar,beat,melody:melody||null,notes,style,gate,finisher,volume:(peace?.72:.84)*(finisher?1.15:1),harmony:name,when:s.origin+slot*s.slot,rest:!notes.length};
}
function bardEmit(s,plan){
 s.lastPlan=plan;if(plan.rest||!bardAudible())return false;
 // Prepare first. New attacks cannot steal this voice or cut it before the next note exists.
 const buffer=bardPhraseBuffer(plan),source=AC.createBufferSource(),gain=AC.createGain(),at=Math.max(AC.currentTime,plan.when);
 source.buffer=buffer;gain.gain.value=.66*plan.volume;source.connect(gain);gain.connect(bardBus());
 for(const v of BARD_CONDUCTOR.voices)if(v.role!=='strum'&&!v.luteEnding)bardDampVoice(v,at);
 const voice={source,gain,kind:plan.finisher?'finale':'bard',when:at,luteNotes:plan.notes};BARD_CONDUCTOR.voices.add(voice);
 source.onended=()=>{source.disconnect();gain.disconnect();BARD_CONDUCTOR.voices.delete(voice);};source.start(at);s.played++;return true;
}
function bardQueueStrum(s,cue){
 const timing=bardAttackTiming(G.p),step=s.slot/2,now=AC.currentTime;
 const index=Math.max(0,Math.ceil((now+.025-s.origin)/(step*timing.strumStride))*timing.strumStride);
 if(s.lastStrumIndex!==undefined&&index<=s.lastStrumIndex)return;
 if(!s.strums)s.strums=new Map();
 // Coalesce simultaneous skills/projectiles into one accent, never a note burst.
 const previous=s.strums.get(index),power=cue.id==='finale'?1.35:['chord','chorus','hymn'].includes(cue.id)?1.1:.85;
 s.strums.set(index,{power:Math.max(previous?previous.power:0,power)});
 if(s.strums.size>3)s.strums.delete(s.strums.keys().next().value);
}
function bardEmitStrum(s,index,power){
 if(!bardAudible())return false;
 const song=BARD_SONGS[s.soloSongIndex||0],bar=((Math.floor((index/2-(s.songStartSlot||0))/8)%8)+8)%8,ch=M_CHORD[song.chords[bar]],notes=[ch[0],ch[1],ch[3]];
 const buffer=lutePhraseBuffer(notes,'gentle',1),source=AC.createBufferSource(),gain=AC.createGain(),at=Math.max(AC.currentTime,s.origin+index*s.slot/2);
 source.buffer=buffer;gain.gain.value=.23*power;source.connect(gain);gain.connect(bardBus());
 // Strum tails can replace one another, but never shorten the lead melody.
 for(const v of BARD_CONDUCTOR.voices)if(v.role==='strum'&&!v.luteEnding)bardDampVoice(v,at);
 const voice={source,gain,role:'strum',kind:'bard',when:at,luteNotes:notes};BARD_CONDUCTOR.voices.add(voice);
 source.onended=()=>{source.disconnect();gain.disconnect();BARD_CONDUCTOR.voices.delete(voice);};source.start(at);s.strumsPlayed=(s.strumsPlayed||0)+1;return true;
}
function bardFlushStrums(s,now){
 if(!s.strums)return;
 for(const [index,event] of s.strums){const at=s.origin+index*s.slot/2;
  if(at<now-.025){s.strums.delete(index);continue;}
  if(at<now+.10){bardEmitStrum(s,index,event.power);s.lastStrumIndex=index;s.strums.delete(index);}
 }
}
function bardMusicTick(){
 BARD_CONDUCTOR.timer=null;
 if(!bardAudible()){stopBardMusic();return;}
 const p=G.p,s=p.bardMusic;if(!s)return;
 const clock=bardClock();if(s.key!==bardTransportKey(clock,p)||s.following!==clock.following||clock.following&&Math.abs(s.origin-clock.origin)>.015){stopBardMusic();return;}
 const now=AC.currentTime;
 if(bardTwoRoutesSelected()){bardTwoRoutesTick(p,s);BARD_CONDUCTOR.timer=setTimeout(bardMusicTick,25);return;}
 if(s.ending){if(now>=s.endAt){p.bardMusic=null;bardLeadMix(false);return;}}
 else{
  // A stalled/background tab skips missed beats instead of firing a backlog.
  const earliest=Math.max(0,Math.ceil((now+.012-s.origin)/s.slot));
  if(s.origin+s.nextSlot*s.slot<now-.025){s.skipped+=Math.max(0,earliest-s.nextSlot);s.nextSlot=earliest;}
  while(s.origin+s.nextSlot*s.slot<now+.10){
   const slot=s.nextSlot++,when=s.origin+slot*s.slot;
   if(!bardSoloSelected()&&now-s.lastEvent>Math.max(1.6,s.slot*4)&&slot%2===0){
    const P=M_PIECES[s.map],name=P.chords[Math.floor(slot/P.slots)%P.chords.length],ch=M_CHORD[name];
    bardEmit(s,{slot,when,notes:[ch[0]+12],style:'gentle',gate:2,volume:.55,finisher:false,rest:false,harmony:name,cadence:true});s.ending=true;s.endAt=when+.7;break;
   }
   bardEmit(s,bardPlan(s,slot));
  }
 }
 if(s.map==='sonic')bardFlushStrums(s,now);
 BARD_CONDUCTOR.timer=setTimeout(bardMusicTick,25);
}
function bardCue(id,rank){return {id,rank,repeats:0};}
function bardPlay(cue){
 if(!G||G.state!=='play'||G.p.cls!=='bard')return false;bardStrum(G.p);
 const repeat=cue.repeats++;if(!bardAudible())return false;
 const s=bardMusicState(G.p);s.lastEvent=AC.currentTime;bardLeadMix(true);
 if(bardTwoRoutesSelected()){if(BARD_CONDUCTOR.timer===null)bardMusicTick();return true;}
 s.intensity=Math.min(4,s.intensity+(repeat?.12:.55));
 if(s.map==='sonic'){if(!repeat)bardQueueStrum(s,cue);}
 else{
  if(!repeat&&['peace','discord','hymn','massprovo','chord','chorus','finale','rally'].includes(cue.id))s.accent=1;
  if(!repeat&&cue.id==='finale')s.finale=true;
 }
 // Immediate, unpitched finger/string contact preserves the attack response.
 // The tuneful part is scheduled independently on the musical clock.
 if(!repeat)sfx('sonichit',{force:true,volume:.45});
 if(BARD_CONDUCTOR.timer===null)bardMusicTick();return true;
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopBardMusic();});

function installSfxControls(){for(const target of [document.querySelector('#pgSettings .settingsPanel'),document.querySelector('#pause .gump')]){if(!target)continue;const row=document.createElement('p');row.className='sfxcontrols';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=SFX.on;check.setAttribute('aria-label','Enable sound effects');label.append(check,document.createTextNode(' Sound effects '));const slider=document.createElement('input');slider.type='range';slider.min=0;slider.max=100;slider.step=5;slider.value=Math.round(SFX.user*100);slider.setAttribute('aria-label','Sound effects volume');const value=document.createElement('span');value.textContent=slider.value+'%';const test=document.createElement('button');test.type='button';test.className='btn';test.textContent='Preview sound';test.style.cssText='font-size:14px;padding:2px 8px;';const sync=()=>{for(const el of document.querySelectorAll('.sfxcontrols')){el.querySelector('input[type=checkbox]').checked=SFX.on;el.querySelector('input[type=range]').value=Math.round(SFX.user*100);el.querySelector('span').textContent=Math.round(SFX.user*100)+'%';}sfxApply();saveAudio();};check.addEventListener('change',()=>{SFX.on=check.checked;sync();});slider.addEventListener('input',()=>{SFX.user=slider.value/100;sync();});test.addEventListener('click',()=>{unlockSfx();setTimeout(()=>sfx('heavy',{force:true}),30);});row.append(label,slider,value,test);target.appendChild(row);}}
// ============================================================ music: a small procedural consort (lute, recorder, tabor) in old modes
const MUSIC={want:null,cur:null,bus:null,next:0,step:0,timer:null,vol:1,on:true,user:.75};
try{const a=JSON.parse(localStorage.getItem('bsm_audio'));if(a){if(typeof a.sfxUser==='number')SFX.user=Math.max(0,Math.min(1,a.sfxUser));if(typeof a.sfxOn==='boolean')SFX.on=a.sfxOn;if(typeof a.on==='boolean')MUSIC.on=a.on;if(typeof a.user==='number')MUSIC.user=Math.min(1,Math.max(0,a.user));}}catch(e){}
function saveAudio(){try{localStorage.setItem('bsm_audio',JSON.stringify({on:MUSIC.on,user:MUSIC.user,sfxUser:SFX.user,sfxOn:SFX.on}));}catch(e){}}
function musicApplyUser(){if(MUSIC.bus)MUSIC.bus.gain.setTargetAtTime(.4*MUSIC.user*(muted?0:1),AC.currentTime,.05);mapTrackSync();}
function musicSetOn(on){MUSIC.on=on;saveAudio();if(!on)mapTrackStop();if(!on){clearTimeout(MUSIC.timer);MUSIC.cur=null;if(AC)mDrone({});}else musicKick();}
function musicSetUser(v){MUSIC.user=v;saveAudio();if(AC)musicApplyUser();}
// Recorded map music streams through its own clean bus, without the consort's EQ/delay.
const MAP_TRACKS={britannia:{src:'assets/music/sinious-groove.mp3',title:'Sinious Groove',gain:.5}};
const MAP_AUDIO={element:null,node:null,gain:null,id:null,pending:false,blocked:false,target:null,error:null};
function mapTrackAllowed(){return !!(AC&&MAP_TRACKS[MUSIC.cur]&&MUSIC.want===MUSIC.cur&&MUSIC.on&&!muted&&MUSIC.user>0&&!document.hidden&&!bardOwnsMusic()&&!(G&&(G.state==='pause'||G.classBoss||G.graveWar||G.tavernDuel)));}
function mapTrackStop(reset=false){const a=MAP_AUDIO.element;if(a){a.pause();if(reset){try{a.currentTime=0;}catch(e){}MAP_AUDIO.id=null;}}}
function mapTrackSync(fromGesture=false){
 if(fromGesture)MAP_AUDIO.blocked=false;
 if(MUSIC.output&&AC){const silent=!!MAP_TRACKS[MUSIC.cur]||bardOwnsMusic();if(MUSIC.mapOutputSilent!==silent){MUSIC.mapOutputSilent=silent;MUSIC.output.gain.cancelScheduledValues(AC.currentTime);MUSIC.output.gain.setTargetAtTime(silent?0:1,AC.currentTime,.035);}}
 if(!mapTrackAllowed()){mapTrackStop();return;}
 const track=MAP_TRACKS[MUSIC.cur];
 if(!MAP_AUDIO.element){
  const a=new Audio();a.preload='auto';a.loop=true;a.setAttribute('playsinline','');
  const node=AC.createMediaElementSource(a),gain=AC.createGain();gain.gain.value=0;node.connect(gain);gain.connect(AC.destination);
  MAP_AUDIO.element=a;MAP_AUDIO.node=node;MAP_AUDIO.gain=gain;
  a.addEventListener('error',()=>{MAP_AUDIO.error=a.error?a.error.code:'unknown';});
 }
 const a=MAP_AUDIO.element;
 if(MAP_AUDIO.id!==MUSIC.cur){a.pause();MAP_AUDIO.id=MUSIC.cur;MAP_AUDIO.error=null;MAP_AUDIO.blocked=false;a.src=track.src;MAP_AUDIO.target=null;}
 const volume=track.gain*MUSIC.user*MUSIC.vol;
 if(MAP_AUDIO.target!==volume){MAP_AUDIO.target=volume;MAP_AUDIO.gain.gain.setTargetAtTime(volume,AC.currentTime,.06);}
 if(a.paused&&!MAP_AUDIO.pending&&!MAP_AUDIO.blocked&&!MAP_AUDIO.error){
  MAP_AUDIO.pending=true;const id=MAP_AUDIO.id;
  a.play().then(()=>{if(id===MAP_AUDIO.id&&!mapTrackAllowed())a.pause();}).catch(error=>{if(error.name==='NotAllowedError')MAP_AUDIO.blocked=true;else if(error.name!=='AbortError')MAP_AUDIO.error=error.name;}).finally(()=>{MAP_AUDIO.pending=false;});
 }
}
document.addEventListener('visibilitychange',()=>mapTrackSync());

