const M_CHORD={Em:[40,47,52,55],B:[47,54,59,63],Dm:[50,57,62,65],C:[48,55,60,64],A:[45,52,57,61],F:[53,60,65,69],Am:[45,52,57,60],Bb:[46,53,58,62],E:[40,47,52,56],G:[43,50,55,59]};
const mHz=n=>440*Math.pow(2,(n-69)/12);
function musicBus(){if(MUSIC.bus)return MUSIC.bus;const g=AC.createGain();g.gain.value=.4*MUSIC.user;const lp=AC.createBiquadFilter();lp.type='lowpass';lp.frequency.value=2600;const dl=AC.createDelay(1);dl.delayTime.value=.27;const fb=AC.createGain();fb.gain.value=.28;const dlp=AC.createBiquadFilter();dlp.type='lowpass';dlp.frequency.value=1500;const wet=AC.createGain();wet.gain.value=.35;
 const output=AC.createGain();output.gain.value=bardOwnsMusic()?0:1;output.connect(AC.destination);g.connect(lp);lp.connect(output);lp.connect(dl);dl.connect(dlp);dlp.connect(fb);fb.connect(dl);dlp.connect(wet);wet.connect(output);MUSIC.output=output;MUSIC.bus=g;return g;}
function mPluck(freq,t,vol,dur){const b=musicBus();const o=AC.createOscillator(),o2=AC.createOscillator(),f=AC.createBiquadFilter(),g=AC.createGain();o.type='triangle';o2.type='sawtooth';o.frequency.value=freq;o2.frequency.value=freq*1.003;f.type='lowpass';f.frequency.setValueAtTime(freq*6,t);f.frequency.exponentialRampToValueAtTime(freq*1.5,t+dur*.8);const g2=AC.createGain();g2.gain.value=.25;o.connect(f);o2.connect(g2);g2.connect(f);f.connect(g);g.connect(b);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.start(t);o2.start(t);o.stop(t+dur+.02);o2.stop(t+dur+.02);}
function musicLeadBus(){if(!MUSIC.leadBus){const b=AC.createGain();b.gain.value=bardMusicActive(AC.currentTime)?.08:1;b.connect(musicBus());MUSIC.leadBus=b;}return MUSIC.leadBus;}
function mRecorder(freq,t,dur,vol){const b=musicLeadBus();const o=AC.createOscillator(),o2=AC.createOscillator(),g=AC.createGain(),lfo=AC.createOscillator(),lg=AC.createGain();o.type='sine';o2.type='triangle';o.frequency.value=freq;o2.frequency.value=freq*2.001;const g2=AC.createGain();g2.gain.value=.12;lfo.frequency.value=5.2;lg.gain.value=freq*.006;lfo.connect(lg);lg.connect(o.frequency);lg.connect(o2.frequency);o.connect(g);o2.connect(g2);g2.connect(g);g.connect(b);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.05);g.gain.setValueAtTime(vol,t+Math.max(.06,dur-.09));g.gain.exponentialRampToValueAtTime(.0001,t+dur);lfo.start(t);o.start(t);o2.start(t);o.stop(t+dur+.02);o2.stop(t+dur+.02);lfo.stop(t+dur+.02);}
function mTabor(t,vol){const b=musicBus();const o=AC.createOscillator(),g=AC.createGain();o.type='sine';o.frequency.setValueAtTime(95,t);o.frequency.exponentialRampToValueAtTime(42,t+.12);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+.16);o.connect(g);g.connect(b);o.start(t);o.stop(t+.18);
 const n=AC.createBufferSource(),buf=AC.createBuffer(1,2200,AC.sampleRate),d=buf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);n.buffer=buf;const ng=AC.createGain(),nf=AC.createBiquadFilter();nf.type='bandpass';nf.frequency.value=1800;ng.gain.value=vol*.35;n.connect(nf);nf.connect(ng);ng.connect(b);n.start(t);}
function mBell(freq,t,vol){if(typeof onBellToll==='function')onBellToll(t-AC.currentTime);const b=musicBus();for(const [r,a,d] of [[1,1,4.5],[2.76,.45,2.8],[5.4,.22,1.6],[.5,.35,5]]){const o=AC.createOscillator(),g=AC.createGain();o.type='sine';o.frequency.value=freq*r;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol*a,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(b);o.start(t);o.stop(t+d+.05);}}
function mDrone(piece){if(MUSIC.drone){try{MUSIC.drone.g.gain.setTargetAtTime(.0001,AC.currentTime,.5);MUSIC.drone.o.stop(AC.currentTime+2);MUSIC.drone.o2.stop(AC.currentTime+2);}catch(e){}MUSIC.drone=null;}if(!piece.drone)return;const o=AC.createOscillator(),o2=AC.createOscillator(),g=AC.createGain();o.type='sine';o2.type='triangle';o.frequency.value=mHz(piece.drone);o2.frequency.value=mHz(piece.drone+12)*1.002;const g2=AC.createGain();g2.gain.value=.3;o.connect(g);o2.connect(g2);g2.connect(g);g.connect(musicBus());g.gain.setValueAtTime(.0001,AC.currentTime);g.gain.exponentialRampToValueAtTime(.09,AC.currentTime+3);o.start();o2.start();MUSIC.drone={o,o2,g};}
function musicTick(){if(!AC||!MUSIC.cur||muted||!MUSIC.on)return;if(MAP_TRACKS[MUSIC.cur]){mapTrackSync();MUSIC.timer=setTimeout(musicTick,200);return;}const P=M_PIECES[MUSIC.cur];const slotDur=60/P.bpm*(P.slots===6?.5:.5);const bars=P.chords.length;
 while(MUSIC.next<AC.currentTime+.4){const t=MUSIC.next,bar=Math.floor(MUSIC.step/P.slots)%bars,sl=MUSIC.step%P.slots;const ch=M_CHORD[P.chords[bar]];const v=MUSIC.vol,bardLead=bardMusicActive(t);if(bardOwnsMusic()){MUSIC.step++;MUSIC.next+=slotDur;continue;}
  mPluck(mHz(ch[P.arp[sl]]+(sl===0?0:0)),t,P.luteVol*v*(bardLead?.48:1)*(sl===0?1.15:.85)*(.9+Math.random()*.2),slotDur*(sl===0?3.2:1.9));
  const m=P.melody[bar][sl];if(m){let len=1;for(let k=sl+1;k<P.slots&&!P.melody[bar][k];k++)len++;mRecorder(mHz(m),t+.01,slotDur*len*.98,P.recorderVol*v*(.9+Math.random()*.2));}
  if(P.tabor[sl])mTabor(t,.5*P.tabor[sl]*v);
  if(P.bell){const bn=P.bell[(bar*P.slots+sl)%P.bell.length];if(bn)mBell(mHz(bn),t,.12*v);}
  MUSIC.step++;MUSIC.next+=slotDur;}
 MUSIC.timer=setTimeout(musicTick,110);}
function music(id){MUSIC.want=id;if(MAP_AUDIO.id&&MAP_AUDIO.id!==id)mapTrackStop(true);if(muted||!AC||!MUSIC.on){mapTrackSync();return;}if(id===MUSIC.cur){mapTrackSync();return;}clearTimeout(MUSIC.timer);MUSIC.cur=id;MUSIC.step=0;MUSIC.next=AC.currentTime+.15;if(id){if(!M_PIECES[id])id=MUSIC.cur='deceit';mDrone(MAP_TRACKS[id]?{}:M_PIECES[id]);mapTrackSync();musicTick();}else{mapTrackStop(true);mDrone({});}}
function musicVol(v){MUSIC.vol=v;mapTrackSync();}
function musicKick(){if(muted||!MUSIC.on)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();if(MUSIC.want&&MUSIC.cur!==MUSIC.want)music(MUSIC.want);mapTrackSync(true);}catch(e){}}
