function comicFlat(map,opacity=1){return new T.MeshBasicMaterial({map:comicEffectTexture(map),transparent:true,opacity,depthWrite:false,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});}
function decorateSleepField(z){
 const g=z.mesh;for(const m of g.children.slice()){g.remove(m);m.material.dispose();}
 g.userData.legacyOwned=true;z.legacyArt=true;z.legacyT=z.t;z.comicSleep=true;
 const base=new T.Mesh(elementalGroundGeometry(z.x,z.z,z.r),comicFlat('sleep',.8));base.userData.legacyOwnGeo=true;base.userData.spin=0;g.add(base);
 for(let i=0;i<4;i++){const m=legacyMesh(g,legacyArt().plane,'#efdbb7',.8,legacyArt().note);m.userData.sleepNote=i;m.userData.spin=0;}
}
function animateSleepField(z){const age=z.legacyT-z.t,fade=Math.min(1,Math.max(0,age)/.3,z.t/.65),A=legacyArt();z.mesh.children[0].material.opacity=fade*.85;
 for(let i=1;i<z.mesh.children.length;i++){const m=z.mesh.children[i],a=(i-1)/4*TAU+age*.12,d=A.dummy;d.position.set(Math.cos(a)*z.r*.83,4+Math.sin(age*1.8+i)*2,Math.sin(a)*z.r*.83);d.quaternion.copy(camera.quaternion);d.scale.set(6.5,6.5,1);d.updateMatrix();m.matrixAutoUpdate=false;m.matrix.copy(d.matrix).premultiply(A.inverseZone.makeScale(1/z.r,1,1/z.r));m.material.opacity=fade*.8;}}
function comicAffixFX(kind,e){
 const g=new T.Group(),scale=e.r/7,h=ascBodyHeight(e)/scale;g.name='comic-affix-'+kind;
 const m=new T.Sprite(new T.SpriteMaterial({map:comicEffectTexture(kind),transparent:true,depthWrite:false,opacity:.95}));m.scale.set(26/scale,26/scale,1);m.position.y=h+8/scale;g.add(m);
 // A small ground accent anchors the modifier without dressing the model in cubes.
 const arcGeo=new T.RingGeometry(.88,1,40,1,.18,Math.PI*.72).rotateX(-Math.PI/2),mat=new T.MeshBasicMaterial({color:AFFIX[kind].col,transparent:true,opacity:.55,depthWrite:false,side:T.DoubleSide});
 for(let i=0;i<2;i++){const a=new T.Mesh(arcGeo,mat);a.scale.setScalar(10);a.position.y=.65;a.rotation.y=i*Math.PI;g.add(a);}
 g.userData.anim=t=>{m.position.y=h+(8+Math.sin(t*1.8+e.wob)*.6)/scale;m.material.opacity=kind==='phasing'&&e.phased?.4:.95;mat.opacity=kind==='phasing'&&e.phased?.18:.5;};
 g.userData.dispose=()=>{arcGeo.dispose();mat.dispose();m.material.dispose();};return g;
}
function renderComicPulse(f,k){
 const heal=f.type==='v2_mend',r=f.r||80,fade=Math.pow(1-k,1.2);
 if(!f.mesh){const g=actionGroup(f);f.strokes=[];for(let i=0;i<4;i++){const dark=actionRibbon(g,20,heal?'#254c43':'#583025',.8),light=actionRibbon(g,20,heal?'#a8efb1':'#efbb77',.8);f.strokes.push([dark,light]);}f.motes=[];for(let i=0;i<6;i++){const m=new T.Sprite(new T.SpriteMaterial({map:comicEffectTexture(heal?'mend':'totem'),color:heal?'#b4f5ba':'#ffd6a0',transparent:true,depthWrite:false}));m.userData.legacyOwnGeo=false;g.add(m);f.motes.push(m);}}
 f.mesh.position.set(f.x,gAt(f.x,f.z)+1,f.z);
 for(let j=0;j<4;j++){const pts=[],rr=r*(.2+.8*Math.min(1,k*1.35-j*.035));for(let i=0;i<=20;i++){const a=j*TAU/4+i/20*1.2;pts.push(new T.Vector3(Math.cos(a)*rr,3+Math.sin(i/20*Math.PI)*4,Math.sin(a)*rr));}for(let l=0;l<2;l++){const m=f.strokes[j][l];writeRibbon(m,pts,l?.65:1.3,COMIC_EFFECTS.up);m.position.y=l*.12;m.material.opacity=fade*(l?.9:.6);}}
 for(let i=0;i<6;i++){const a=i*TAU/6,rr=r*(heal?.75-.4*k:.3+.55*k),m=f.motes[i];m.position.set(Math.cos(a)*rr,5+k*15,Math.sin(a)*rr);m.scale.setScalar(8+2*Math.sin(k*Math.PI));m.material.opacity=fade*.7;}
}
function renderComicEarth(f,k){
 if(!f.mesh){const g=actionGroup(f);f.crack=new T.Mesh(elementalGroundGeometry(f.x,f.z,f.r),comicFlat('cracks'));f.crack.userData.legacyOwnGeo=true;f.crack.scale.set(f.r,1,f.r);g.add(f.crack);f.clouds=[];for(let i=0;i<7;i++){const m=new T.Sprite(new T.SpriteMaterial({map:comicEffectTexture('dust'),transparent:true,opacity:.8,depthWrite:false}));g.add(m);f.clouds.push(m);}}
 f.mesh.position.set(f.x,gAt(f.x,f.z)+.75,f.z);f.crack.material.opacity=Math.min(1,k*12)*(1-k)*.9;
 for(let i=0;i<7;i++){const a=i*TAU/7,rr=f.r*(.2+.7*(1-Math.pow(1-k,2))),m=f.clouds[i];m.position.set(Math.cos(a)*rr,2+Math.sin(k*Math.PI)*7,Math.sin(a)*rr);m.scale.set(f.r*(.35+k*.3),f.r*(.18+k*.12),1);m.material.opacity=Math.pow(1-k,1.6)*.75;}
}
function renderComicShieldHeave(f,k){
 if(!f.mesh){const g=actionGroup(f);f.strokes=[];for(let i=0;i<3;i++)f.strokes.push([actionRibbon(g,16,'#304458',.8),actionRibbon(g,16,'#f6e8bf',.9)]);}
 f.mesh.position.set(f.x,gAt(f.x,f.z)+1,f.z);f.mesh.rotation.y=-f.a;
 for(let j=0;j<3;j++){const pts=[],front=12+k*30-j*3;for(let i=0;i<=16;i++){const u=i/16*2-1;pts.push(new T.Vector3(front+(1-u*u)*6,5+j*4, u*22*(.7+k*.3)));}for(let l=0;l<2;l++){const m=f.strokes[j][l];writeRibbon(m,pts,l?.7:1.5,new T.Vector3(0,1,1));m.position.y=l*.12;m.material.opacity=(1-k)*(l?.9:.7)*(f.strong?1:.65);}}
}
function renderComicShieldBash(f,k){
 if(!f.mesh){const g=actionGroup(f);f.strokes=[];for(let i=0;i<6;i++){const back=actionRibbon(g,12,'#314354',.8),front=actionRibbon(g,12,'#eddfbc',.85);f.strokes.push([back,front]);}}
 f.mesh.position.set(f.x,gAt(f.x,f.z)+.7,f.z);
 // Shield Bash hits in a radius: six separated pressure strokes show that footprint.
 for(let j=0;j<6;j++){const pts=[],r=f.r*(.16+.84*(1-Math.pow(1-k,2)));for(let i=0;i<=12;i++){const a=j*TAU/6+i/12*.75;pts.push(new T.Vector3(Math.cos(a)*r,4+Math.sin(i/12*Math.PI)*3,Math.sin(a)*r));}for(let l=0;l<2;l++){const m=f.strokes[j][l];writeRibbon(m,pts,l?.65:1.3,COMIC_EFFECTS.up);m.position.y=l*.18;m.material.opacity=(1-k)*(l?.85:.6);}}
}

const ASC_ART={};
function ascArt(){if(ASC_ART.box)return ASC_ART;const a=ASC_ART;a.box=new T.BoxGeometry(1,1,1);a.gem=new T.OctahedronGeometry(1,0);a.ring=new T.TorusGeometry(1,.12,4,12);a.fang=new T.ConeGeometry(1,1,4);a.shield=legacyArt().shield;a.groundRing=new T.RingGeometry(.985,1,48).rotateX(-Math.PI/2);return a;}
function ascBodyHeight(e){if(e.ascVisualH===undefined){e.mesh.updateMatrixWorld(true);const box=new T.Box3().setFromObject(e.mesh);e.ascVisualH=Math.max(e.h*e.sc,box.max.y-e.mesh.position.y);}return e.ascVisualH;}
function makeAffixFX(kind,e){return comicAffixFX(kind,e);}
const ASC_SUPPORT={art:null,m:new T.Matrix4(),p:new T.Vector3(),s:new T.Vector3(),q:new T.Quaternion()};
function ascSupportArt(){if(ASC_SUPPORT.art)return ASC_SUPPORT.art;const cap=IS_TOUCH||IS_MOBILE?64:128,g=new T.Group(),geo=new T.BufferGeometry(),pos=new Float32Array(cap*12*6*3),colors=new Float32Array(pos.length);geo.setAttribute('position',new T.BufferAttribute(pos,3));geo.setAttribute('color',new T.BufferAttribute(colors,3));geo.setDrawRange(0,0);const lines=new T.Mesh(geo,new T.MeshBasicMaterial({vertexColors:true,transparent:true,opacity:.75,depthWrite:false,side:T.DoubleSide}));lines.frustumCulled=false;g.add(lines);
 const marks=new T.InstancedMesh(ascArt().shield,new T.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.7,side:T.DoubleSide,depthWrite:false}),cap);marks.frustumCulled=false;marks.setColorAt(0,new T.Color());marks.count=0;g.add(marks);const h=new T.BoxGeometry(1,.28,.1),v=new T.BoxGeometry(.28,1,.1),plus=T.BufferGeometryUtils.mergeBufferGeometries([h,v]);h.dispose();v.dispose();const heals=new T.InstancedMesh(plus,marks.material,cap),rage=new T.InstancedMesh(new T.ConeGeometry(.5,1,3),marks.material,cap);for(const m of [heals,rage]){m.setColorAt(0,new T.Color());m.count=0;m.frustumCulled=false;g.add(m);}scene.add(g);return ASC_SUPPORT.art={g,lines,pos,colors,marks,heals,rage,n:0,cap,col:new T.Color()};}
function clearAscensionSupport(){const a=ASC_SUPPORT.art;if(a){a.lines.geometry.setDrawRange(0,0);for(const m of [a.marks,a.heals,a.rage])m.count=0;}}
function renderAscensionSupport(){const a=ascSupportArt(),s=ASC_SUPPORT;clearAscensionSupport();a.n=0;
 const marker=(e,col,type)=>{const m=type?a[type]:a.marks;if(m.count>=a.cap)return;const i=m.count++;s.p.set(e.x,e.mesh.position.y+ascBodyHeight(e)+6,e.z);s.s.set(5,6,1);s.q.copy(camera.quaternion);s.m.compose(s.p,s.q,s.s);m.setMatrixAt(i,s.m);m.setColorAt(i,a.col.set(col).convertSRGBToLinear());};
 const link=(e,o,col,broken)=>{if(!e||!o||e.dead||o.dead||!skillVfxVisible(o.x,o.z))return;a.col.set(col);const y=e.mesh.position.y+e.h*e.sc*.65,oy=o.mesh.position.y+o.h*o.sc*.65;
  if(broken)return;const dx=o.x-e.x,dz=o.z-e.z,len=Math.hypot(dx,dz)||1,nx=-dz/len,nz=dx/len,width=.6;
  for(let i=0;i<12;i++){if(a.n+18>a.pos.length)return;const point=k=>[e.x+dx*k,y+(oy-y)*k+Math.sin(k*Math.PI)*5,e.z+dz*k],p=point(i/12),q=point((i+1)/12),pulse=.55+.45*Math.pow(Math.max(0,Math.cos(i/12*TAU-G.t*3)),4);
   for(const [v,side]of [[p,-1],[p,1],[q,1],[p,-1],[q,1],[q,-1]]){a.pos[a.n]=v[0]+nx*width*side;a.colors[a.n++]=a.col.r*pulse;a.pos[a.n]=v[1];a.colors[a.n++]=a.col.g*pulse;a.pos[a.n]=v[2]+nz*width*side;a.colors[a.n++]=a.col.b*pulse;}
  }
 };
 for(const e of G.enemies){if(e.dead||!e.mesh.visible||!skillVfxVisible(e.x,e.z))continue;
  if(e.bond&&!e.bond.dead){const active=bondActive(e);if(G.enemies.indexOf(e)<G.enemies.indexOf(e.bond))link(e,e.bond,active?'#be91da':'#7f737e',!active);if(active)marker(e,'#be91da');}
  if(e.tether&&e.tetherT>0&&!e.tether.dead){link(e.tether,e,'#80bed4');marker(e,'#80bed4');}
  if(e.healUntil>G.t&&e.healSource&&!e.healSource.dead){link(e.healSource,e,'#77d493');marker(e,'#77d493','heals');}
  if(e.rage>0&&(e.rageVisualUntil>G.t||e.rageSrc&&!e.rageSrc.dead)){marker(e,'#df8d4f','rage');if(e.rageSrc&&!e.rageSrc.dead)link(e.rageSrc,e,'#ce854f');}
 }
 a.lines.geometry.setDrawRange(0,a.n/3);a.lines.geometry.attributes.position.needsUpdate=true;a.lines.geometry.attributes.color.needsUpdate=true;for(const m of [a.marks,a.heals,a.rage]){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;}
}

// Each cloned enemy owns a GPU bone texture. Release it only when its model leaves play.
function disposeEnemyRig(e){if(e.mesh&&e.mesh.userData.soulArt){const A=e.mesh.userData.soulArt;if(!A.disposed){A.disposed=true;for(const m of A.owned)m.dispose();for(const g of A.geos)g.dispose();}}releaseScorchedCorpse(e);affixDispose(e);if(!e.mesh)return;e.mesh.traverse(o=>{if(o.isSkinnedMesh&&o.skeleton&&o.skeleton.boneTexture){o.skeleton.boneTexture.dispose();o.skeleton.boneTexture=null;}});}

