 e.halWounds=wounds;e.halBleedDps=wounds.reduce((n,w)=>n+w.dps,0);e.halBleedUntil=Math.max(...wounds.map(w=>w.until));e.halBleedTick=e.halBleedTick===undefined?.5:e.halBleedTick;
