function halHit(e,damage,stagger,a,heavy=true,wounding=heavy){if(e.dead||e.phased)return;const p=G.p,broken=e.halBrokenUntil>G.t;let d=damage*halPower(p);if(broken&&heavy)d*=1.5+(p.rm.halBrokenDmg||0);e.halHeavyHit=heavy&&broken?{a,power:d}:null;e.halWoundingHit=wounding;try{hitEnemy(e,d*(e.boss?HAL.bossHit:1),0,0);}finally{e.halHeavyHit=null;e.halWoundingHit=false;}halBlood(e.x,e.z,a,Math.max(6,e.r),Math.max(5,e.h*e.sc*.5),heavy&&broken);if(e.dead)return;if(wounding)applyHalBleed(e,d*(heavy?.45:.25),a,heavy&&broken);if(broken&&heavy){e.halBrokenUntil=0;G.halPunishes=(G.halPunishes||0)+1;}else halBreak(e,stagger);if(!halResists(e)){e.kx+=Math.cos(a)*28;e.kz+=Math.sin(a)*28;}}
function startHalSwing(l){const p=G.p;if(p.stance!=='hal'||p.halAttack||p.halCharge)return false;p.halAttack={kind:'cut',born:G.t,l,a:p.aim,hit:false};p.halSwingIndex=(p.halSwingIndex||0)+1;p.atkT=p.atkDur=HAL.recovery;G.halSwings=(G.halSwings||0)+1;return true;}
function halHookReleased(p=G.p){const at=p.halAttack;return p.stance==='hal'&&!!at&&at.kind==='hook'&&G.t-at.born>=HAL.hookReturn;}
function halSlamProtected(p=G.p){const at=p.halAttack;return p.stance==='hal'&&!p.dying&&!!at&&at.kind==='hook'&&at.empowered&&G.t>=at.born&&G.t-at.born<HAL.slamEnd;}
function startHookHew(l,cp){const p=G.p;if(p.stance!=='hal'||p.halCharge||p.dash>0||p.halAttack&&p.halAttack.kind==='hook')return false;if(p.halAttack&&p.halAttack.kind==='cut'&&!p.halAttack.hit&&p.weapons.thrust)p.weapons.thrust.t=.35;
 const a=cp?Math.atan2(cp.z-p.z,cp.x-p.x):p.aim;p.aim=a;p.halAttack={kind:'hook',born:G.t,l,a,x:p.x,z:p.z,hit:false,caught:false,targets:[],empowered:(p.halBlood||0)>=100};p.atkT=p.atkDur=p.halAttack.empowered?HAL.slamEnd:HAL.hookEnd;if(p.halAttack.empowered)p.hitT=0;halFx('hook',{attack:p.halAttack,x:p.x,z:p.z,a,r:halHookRange(l),w:halHookWidth(l),dur:HAL.hookEnd});G.halHooks=(G.halHooks||0)+1;return true;}
function halWave(x,z,a,power,signature=false){
 const p=G.p;halFx('wave',{x,z,a,r:(signature?100:145)*p.area,w:(signature?22:34)*p.area,dur:.65,signature,power,hit:new Set(),treeHit:new Set(),contactK:0});
}
// Shared with the visible curved blade wake, including its easing and widening.
function halWaveShape(f,k){k=clamp(k,0,1);return {travel:f.r*(1-Math.pow(1-k,1.4)),radius:f.w*(.65+k*.5)};}
function updateHalWave(f){
 if(!f.hit)return;const k=clamp(f.t/f.dur,0,1),from=f.contactK||0;if(k<=from)return;
 const start=halWaveShape(f,from),end=halWaveShape(f,k),cx=Math.cos(f.a),cz=Math.sin(f.a);
 // Sweep the arc in small spatial steps so a slow frame cannot skip a target.
 const steps=Math.max(1,Math.ceil((end.travel-start.travel+end.radius-start.radius)/3)),samples=[];
 for(let i=0;i<=steps;i++){const shape=halWaveShape(f,from+(k-from)*i/steps);samples.push([shape.travel-shape.radius*.63,shape.radius]);}
 const touches=(x,z,r)=>{const dx=x-f.x,dz=z-f.z,d=dx*cx+dz*cz,side=-dx*cz+dz*cx,margin=r+2;
  if(d<start.travel-start.radius*.28-margin||d>end.travel+end.radius*.37+margin||Math.abs(side)>end.radius*Math.sin(1.2)+margin)return false;
  for(const [center,radius] of samples){const angle=clamp(Math.atan2(side,d-center),-1.2,1.2);if(Math.hypot(d-center-Math.cos(angle)*radius,side-Math.sin(angle)*radius)<=margin)return true;}return false;
 };
 f.contactK=k;
 for(const e of G.enemies.slice()){if(e.dead||e.phased||f.hit.has(e)||!touches(e.x,e.z,e.r))continue;f.hit.add(e);halHit(e,f.power,f.signature?35:45,f.a,false,!f.signature);}
 const mid=(start.travel+end.travel)/2;
 nearbyBreakables(f.x+cx*mid,f.z+cz*mid,(end.travel-start.travel)/2+end.radius+8,t=>{if(f.treeHit.has(t)||!touches(t.x,t.z,6))return;f.treeHit.add(t);treeHit(t,f.a);});
}
function resolveHalCut(at){const p=G.p,r=halRange(),wide=2.25+(p.ranks.sweep||0)*.12,base=(88+at.l*21)*p.dmg*(1+(p.rm.halDamage||0));at.a=p.aim;const a=at.a;for(const e of G.enemies.slice()){if(e.dead||e.phased)continue;const dx=e.x-p.x,dz=e.z-p.z,d=Math.hypot(dx,dz);if(d>r+e.r||Math.abs(angDiff(Math.atan2(dz,dx),a))>wide/2+Math.min(.3,e.r/Math.max(1,d)))continue;const outer=d>=r*.45;halHit(e,base*(outer?1:.55),outer?38+(p.ranks.sweep||0)*7:15,a,true);if(!e.dead&&!halResists(e)){e.kx=Math.cos(a)*(outer?42:140);e.kz=Math.sin(a)*(outer?42:140);applyEnemyStun(e,outer?.22:.12);}}
 hitTrees(p.x,p.z,r,a,wide);halFx('cut',{x:p.x,z:p.z,a,r,w:wide,dur:.42});const x=p.x+Math.cos(a)*r*.68,z=p.z+Math.sin(a)*r*.68;halImpact(x,z,a,r*.3,false);if(p.halUnstoppableUntil>G.t)halWave(x,z,a,base*(.4+(p.ranks.phalanx||1)*.08));G.halCuts=(G.halCuts||0)+1;}
