 if(!f.mesh){f.mesh=halGhostWeapon(.78);f.archerOwnMaterials=true;scene.add(f.mesh);}
 const age=G.t-at.born,raise=T.MathUtils.smoothstep(age,HAL.hookReturn-.12,HAL.slamImpact-.24),drop=T.MathUtils.smoothstep(age,HAL.slamImpact-.22,HAL.slamImpact),fade=1-T.MathUtils.smoothstep(age,HAL.slamImpact+.07,HAL.slamImpact+.35),r=halRange(),visualArea=clamp(G.p.area,.85,1.25),scale=1.12*visualArea,baseY=gAt(at.x,at.z);
