function launchDemoSalvo(f){let pool=G.enemies.filter(e=>!e.dead&&!e.phased&&Math.hypot(e.x-f.x,e.z-f.z)<=220*G.p.area);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}for(let i=0;i<f.count;i++){const showcase=!pool.length&&i===0?f.showcase:null,target=showcase||(pool.length?pool[i%pool.length]:null),a=i*TAU/f.count;demoFx('rocket',{x:f.x,z:f.z,tx:target?target.x:f.x+Math.cos(a)*55,tz:target?target.z:f.z+Math.sin(a)*55,target,visualScale:demoRocketScale(),showcase:!!showcase,dur:.9+i*.045,delay:i*.075,sy:gAt(f.x,f.z)+13,r:f.r,dmg:f.dmg,col:DEMO_COLORS[i%6],lane:a});}G.demoSalvos=(G.demoSalvos||0)+1;}
function launchSkyBurial(e,power){if(e.boss||e.blob||e.deathStyle==='skyburial'||G.fx.filter(f=>f.type==='demofx'&&f.kind==='sky').length>=3)return false;e.deathStyle='skyburial';e.skyBorn=G.t;e.skyScale=e.mesh.scale.clone();e.skyQ=e.mesh.quaternion.clone();e.skyArms=['upperarml','upperarmr'].map(n=>{const bone=e.mesh.getObjectByName(n);return bone?{bone,q:bone.quaternion.clone()}:null;}).filter(Boolean);e.ct=Math.max(e.ct,3);demoFx('sky',{x:e.x,z:e.z,y:gAt(e.x,e.z),dur:1.28,corpse:e,dmg:power*.5,r:40*G.p.area,col:DEMO_COLORS[(G.demoSkyKills||0)%6]});G.demoSkyKills=(G.demoSkyKills||0)+1;return true;}
function demoFireworkHit(f){if(f.bigOne){bigOneBurst(f);return;}if(!f.manual&&!f.showcase&&G.enemies.some(e=>!e.dead&&!e.phased&&Math.hypot(e.x-f.tx,e.z-f.tz)<f.r*(1+(G.p.rm.boomR||0))+e.r))gainDemoPowder(ROMAN.hitGain);if(f.showcase&&f.target&&G.corpses.includes(f.target)){launchSkyBurial(f.target,f.dmg);G.demoRocketHits=(G.demoRocketHits||0)+1;return;}demoBloom(f.tx,f.tz,gAt(f.tx,f.tz)+12,f.r*1.3,f.col);demoBurst(f.tx,f.tz,f.r,f.col,12);explode(f.tx,f.tz,f.r,f.dmg,{demoVfx:true,demoRocket:f.dmg,frag:1,noGround:true});G.demoRocketHits=(G.demoRocketHits||0)+1;}
// Sweep the flight path, including its height, so a lob can hit an enemy
