 if(['lob','rocket','sky'].includes(f.kind)){const pos=demoFlight(f);f.trail-=dt;if(f.trail<=0){f.trail=.045;emit(pos.x,pos.y,pos.z,2,{col:f.col||'#ffd075',spd:5,vy:-8,life:.6,size:f.kind==='sky'?3.4:f.kind==='rocket'?2:1.4,grav:12});}}
 if(f.t<f.dur||f.done)return;f.done=true;
