 p.brawlAttack={key:'P',kind:'flurry',motion:'flurry',start:G.t,dur,gap,pace,contacts:Array.from({length:8},(_,i)=>gap*(i+.5)),nextContact:0,aim,lunge:0};
 p.brawlLabel='KNUCKLE BARRAGE';G.texts.push({x:p.x,z:p.z,y:28,s:'KNUCKLE BARRAGE!',col:'#ffd27a',t:.65,t0:.65,big:1});return true;
