 if(a.finish)damage*=({beatdown:2.35,roundhouse:1.85,uppercut:2.15,boot:2.15}[a.kind])+(p.ranks.encore||0)*.18+(p.rm.finisherPower||0)+(p.setB==='jester'?.2:0);
