 const f={type:'brawlerstrike',t:0,dur:(a.kind==='roundhouse'?.54:a.kind==='beatdown'?.22:a.finish?.36:kick?.32:.27)*(a.pace||1),x:p.x,z:p.z,aim:a.aim,kind:a.kind,key:a.key,finish:a.finish,last,index,airTarget:a.airTarget,damage,range,area:p.area,hit:new Set(),lastU:0,cap:a.kind==='roundhouse'?18:a.finish?10:kick?7:5,radius:(kick?12:10)*p.area};
