 for(let j=1;j<=steps;j++){
  const v=f.lastU+(u-f.lastU)*j/steps,prev=brawlerStrikePoint(f,f.lastU+(u-f.lastU)*(j-1)/steps),q=brawlerStrikePoint(f,v);
  if(f.hit.size>=f.cap)break;
  for(const e of G.enemies.slice()){
   if(e.dead||e.phased||e.tavern||f.hit.has(e)||(f.targetOnly&&e!==f.targetOnly))continue;
   const ax=f.kind==='roundhouse'?f.x:prev.x,az=f.kind==='roundhouse'?f.z:prev.z;
   if(f.kind==='flurry'){let contact=false;for(let lane=0;lane<5;lane++){const a=brawlerStrikePoint(f,f.lastU+(u-f.lastU)*(j-1)/steps,lane),b=brawlerStrikePoint(f,v,lane);if(brawlerSegmentDistance(e.x,e.z,a.x,a.z,b.x,b.z)<=f.radius+e.r){contact=true;break;}}if(!contact)continue;}else if(brawlerSegmentDistance(e.x,e.z,ax,az,q.x,q.z)>f.radius+e.r)continue;
   primeBrawlerBarrage(f);
   if(f.kind==='boot'&&!f.shoveDone)dropkickShove(f,e.x,e.z);f.hit.add(e);if(f.kind==='airpunch'&&e===f.airTarget){e.brawlLiftAt=G.t-.25;applyEnemyStun(e,.9);}const angle=f.kind==='roundhouse'?Math.atan2(e.z-f.z,e.x-f.x):q.a;
   const kb=(f.kind==='flurry'?(f.last?200:45)*(e.def.elite||e.affix==='juggernaut'||e.hunter?.35:1):f.kind==='boot'?(f.shoved&&f.shoved.has(e)?0:230):f.kind==='beatdown'?(f.last?120:8):f.kind==='uppercut'?35:f.finish?85:f.key==='K'?55:16)*(e.boss?.1:1);
   SFX.area++;try{hitEnemy(e,f.damage*(e.boss&&f.finish?.75:1)*(e.beerUntil>G.t?1.15:1),Math.cos(angle)*kb,Math.sin(angle)*kb,false);}finally{SFX.area--;}
   brawlerImpact(e.x,e.z,Math.min(15,e.h*e.sc*.55),f.finish);
   if(f.kind==='flurry'){e.brawlFlurryHitAt=G.t;e.brawlFlurrySide=f.index%2?1:-1;}
   if(!e.dead&&!e.boss&&!e.def.elite){applyEnemyStun(e,f.kind==='roundhouse'?1.1:f.kind==='beatdown'?.35:f.finish?.45:.10);if(f.kind==='uppercut'){e.brawlLiftAt=G.t;e.brawlAirUsed=false;e.brawlKnockdownAt=undefined;applyEnemyStun(e,1.15);}if(f.kind==='roundhouse'||f.kind==='spike'){e.brawlLiftAt=undefined;e.brawlKnockdownAt=G.t;applyEnemyStun(e,1.1);}if(f.kind==='boot')e.slow=Math.max(e.slow||0,2);}
   if(f.kind==='spike'&&e===f.airTarget&&!f.slamDone){f.slamDone=true;brawlerImpact(e.x,e.z,3,true);for(const other of G.enemies.slice())if(other!==e&&!other.dead&&!other.tavern&&Math.hypot(other.x-e.x,other.z-e.z)<35*f.area+other.r){SFX.area++;try{hitEnemy(other,f.damage*.4,0,0,false);}finally{SFX.area--;}if(!other.boss&&!other.def.elite){other.brawlKnockdownAt=G.t;applyEnemyStun(other,1.1);}}}if(f.hit.size===1){sfx(f.finish&&f.last?'brawlheavy':'brawlhit',{force:true});if(f.finish){G.shake=Math.max(G.shake,2.5);G.hitstop=Math.max(G.hitstop,.035);p.brawlGuardUntil=G.t+1.25;}}
   p.brawlLastHits=f.hit.size;if(f.hit.size>=f.cap)break;
  }
 }
