function tickTavernDuel(dt){
 const d=G&&G.tavernDuel;if(!d||d.paused||d.assets.pending||d.assets.error)return;
 dt=Math.min(dt,.035);if(d.hitstop>0){d.hitstop=Math.max(0,d.hitstop-dt);return;}d.t+=dt;d.shake=Math.max(0,d.shake-dt*13);
 if(d.phase==='intro'&&d.t>=d.phaseUntil){d.phase='fight';pbSay(d,'MAKE SOME TROUBLE!',.65);}
 if((d.phase==='win'||d.phase==='lose')&&d.t>=d.phaseUntil){if(d.test){d.phase='result';d.paused=true;}else{finishTavernDuel(d.phase);return;}}
 const p=d.pf;for(const f of [p,d.bf,...d.goons])pbPhysics(d,f,dt);
 if(d.phase==='fight'){
  const dx=(d.held.d?1:0)-(d.held.a?1:0),dz=(d.held.s?1:0)-(d.held.w?1:0),len=Math.hypot(dx,dz)||1,jump=!!d.held[' '];
  p.walk=0;if(p.stun<=0&&p.down<=0&&!p.carried&&!p.dead){
   if(jump&&!d.jumpHeld&&p.y===0&&!p.attack&&!p.held){p.y=.1;p.vy=185;pbSound('brawlswing');}
   if(!p.attack||p.y>0&&!p.launched){const speed=p.held?70:d.held.ctrl?38:d.held.shift?145:96;p.x+=dx/len*speed*dt;p.z+=dz/len*speed*.67*dt;p.walk=Math.abs(dx)+Math.abs(dz);if(dx)p.face=dx<0?-1:1;}
   if(!p.attack&&!p.walk&&!p.held){const target=pbEnemies(d).filter(e=>Math.abs(e.z-p.z)<20).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];if(target&&Math.abs(target.x-p.x)<70)p.face=target.x>=p.x?1:-1;}
   if(!p.attack&&d.queued&&d.queued.until>=d.t){const key=d.queued.key;d.queued=null;pbPlayerMove(d,key);}
  }d.jumpHeld=jump;p.x=clamp(p.x,26,454);p.z=clamp(p.z,168,238);
  if(p.held&&p.held.fighter&&d.t>p.carryUntil&&!p.attack)pbBegin(d,p,'throw');
  pbTickBossRise(d);
  for(const e of pbEnemies(d))pbEnemyAI(d,e,dt);
  for(const f of [p,...pbEnemies(d)])pbAttackTick(d,f,dt);
  // Grounded bodies occupy floor space; jumping and knockdowns can pass through.
  for(const e of pbEnemies(d)){const delta=e.x-p.x;if(!p.down&&!e.down&&p.y<10&&e.y<10&&Math.abs(e.z-p.z)<10&&Math.abs(delta)<20){const push=(20-Math.abs(delta))*.5,sgn=delta>=0?1:-1;p.x-=sgn*push;e.x+=sgn*push;}}
 }
 for(const h of d.hazards){
  if(h.kind==='meteor'){
   if(d.phase==='fight'&&!h.struck&&d.t>=h.at){h.struck=true;pbBurst(d,h.x,h.z,0,'meteor');d.shake=Math.max(d.shake,2);pbSound('fireblast');if(Math.hypot((p.x-h.x)/1.25,p.z-h.z)<h.r)pbDamage(d,p,d.pf.maxhp*.09,{x:h.x-1,face:1},{kind:'meteor',down:true});}
  }else if(d.phase==='fight'&&d.t>=h.at&&d.t<h.end&&p.y<13&&Math.hypot((p.x-h.x)/1.25,p.z-h.z)<h.r)pbDamage(d,p,d.pf.maxhp*.055,{x:h.x-1,face:1},{kind:'hellfire',down:false});
 }d.hazards=d.hazards.filter(h=>d.t<h.end);
 for(let i=d.shots.length-1;i>=0;i--){const s=d.shots[i];s.life-=dt;s.x+=s.vx*dt;if(s.kind!=='hellfire')s.vy-=170*dt;s.y+=s.vy*dt;s.spin+=dt*10;
  if(s.fighter){s.fighter.x=s.x;s.fighter.z=s.z;s.fighter.y=Math.max(0,s.y);}
  if(d.phase==='fight')for(const e of s.enemy?[p]:pbEnemies(d)){
   if(e===s.fighter||s.hit.has(e)||Math.abs(e.x-s.x)>23||Math.abs(e.z-s.z)>18||Math.abs(e.y+18-s.y)>30)continue;
   const from={x:s.x-Math.sign(s.vx)*20,face:Math.sign(s.vx)},m={kind:'projectile',down:true};
   if(pbDamage(d,e,s.enemy?d.pf.maxhp*.075:pbPower(d,'P')*(s.fighter?4.2:s.kind==='barrel'?4:3.1),from,m,true)){s.hit.add(e);if(!s.fighter){s.life=0;break;}}
  }
  if(s.y<=0||s.life<=0||s.x<9||s.x>471){
   if(s.fighter){const f=s.fighter;f.flyingProp=false;f.y=0;f.x=clamp(s.x,26,454);f.down=1;f.stun=0;f.vx=0;if(!f.dead&&d.phase==='fight')pbDamage(d,f,pbPower(d,'P')*1.5,{x:f.x-Math.sign(s.vx)*20,face:Math.sign(s.vx)},{kind:'projectile',down:false},true);f.y=0;f.vy=0;f.launched=false;if(f===d.bf&&!f.dead){f.down=.18;f.noGrabUntil=d.t+1.2;}}
   pbBurst(d,clamp(s.x,15,465),s.z,5,s.kind==='hellfire'?'fire':s.kind==='enemy'?'dust':'wood');d.shots.splice(i,1);
  }
 }
 for(const f of d.fx)f.t+=dt;d.fx=d.fx.filter(f=>f.t<f.life);
}

