function finishTavernDuel(result='leave',quiet=false){
 const d=G&&G.tavernDuel;if(!d)return;const p=G.p;restoreBrawlerPose(p);$('tavernDuelUI').hidden=true;p.mesh.visible=d.savedVisible[0];d.boss.mesh.visible=d.savedVisible[1];
 pbExitBalance(d,result,quiet);G.tavernDuel=null;G.state='play';for(const k in keys)keys[k]=false;G.dt=0;last=performance.now();p.brawlAttack=p.brawlQueued=null;
 const committed=d.boss.tavernRequired&&result==='leave'&&!quiet&&!d.test;
 if(!committed){d.boss.tavernRequired=false;releaseTavernGuest(d.boss,false,true);}else d.boss.mesh.visible=false;p.x=d.house.x;p.z=d.house.z+58;keepInBounds(p);p.mesh.visible=true;p.invuln=Math.max(p.invuln,1.5);d.boss.stun=Math.max(d.boss.stun,1.2);d.boss.hitCd=1.5;d.house.duelDoorArmed=false;
 if(quiet)return;if(d.test){showMenu();return;}if(result==='win'&&!d.boss.dead){d.boss.tavernDefeated=true;d.boss.hp=0;killEnemy(d.boss);}else if(result==='lose'){p.hp=0;endRun(false);return;}else banner(committed?'The boss is waiting. Finish the fight inside.':'Back outside. The fight continues.');render();hud();
}
(function installTavernDuelInput(){
 const code=e=>({ArrowLeft:'a',ArrowRight:'d',ArrowUp:'w',ArrowDown:'s',Space:' ',KeyA:'a',KeyD:'d',KeyW:'w',KeyS:'s',ShiftLeft:'shift',ShiftRight:'shift',ControlLeft:'ctrl',ControlRight:'ctrl'}[e.code]);
 addEventListener('keydown',e=>{const d=G&&G.tavernDuel;if(!d)return;e.preventDefault();e.stopImmediatePropagation();if(e.code==='Escape'||e.code==='KeyP'){if(!e.repeat){if(d.phase!=='result')d.paused=!d.paused;d.held={};renderTavernDuel();}return;}const k=code(e);if(k)duelDirection(k,true);if(!e.repeat&&e.code==='KeyJ')duelPlayerAttack('P');if(!e.repeat&&e.code==='KeyK')duelPlayerAttack('K');if(!e.repeat&&e.code==='KeyE')pbGrab(d);},true);
 addEventListener('keyup',e=>{if(!G||!G.tavernDuel)return;e.preventDefault();e.stopImmediatePropagation();const k=code(e);if(k)duelDirection(k,false);},true);
 addEventListener('pointerdown',e=>{const d=G&&G.tavernDuel;if(!d)return;e.preventDefault();e.stopImmediatePropagation();const el=e.target.closest('[data-duel],[data-hold]');if(el){const a=el.dataset.duel;if(a==='pause'||a==='resume'){d.paused=a==='pause';d.held={};renderTavernDuel();}else if(a==='retry'&&d.test){const kind=d.boss.kind;finishTavernDuel('leave',true);startTavernPractice(kind);}else if(a==='leave')finishTavernDuel('leave');else if(a==='grab')pbGrab(d);else if(a)duelPlayerAttack(a);else if(el.dataset.hold){duelDirection(el.dataset.hold,true);el.setPointerCapture(e.pointerId);}return;}if(e.button===0)duelPlayerAttack('P');if(e.button===2)duelPlayerAttack('K');},true);
 addEventListener('pointerup',e=>{if(!G||!G.tavernDuel)return;const el=e.target.closest('[data-hold]');if(el)duelDirection(el.dataset.hold,false);e.preventDefault();e.stopImmediatePropagation();},true);
 addEventListener('contextmenu',e=>{if(G&&G.tavernDuel){e.preventDefault();e.stopImmediatePropagation();}},true);
 addEventListener('pointercancel',()=>{if(G&&G.tavernDuel)G.tavernDuel.held={};},true);
 addEventListener('blur',()=>{if(G&&G.tavernDuel){G.tavernDuel.paused=true;G.tavernDuel.held={};renderTavernDuel();}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&G&&G.tavernDuel){G.tavernDuel.paused=true;G.tavernDuel.held={};renderTavernDuel();}});
})();

