function tickGraveWar(dt){
 const d=G&&G.graveWar;if(!d||d.phase!=='fight'||d.paused||d.assets.pending||d.pb.pending)return;
 dt=Math.min(.05,dt);d.t+=dt;const pace=d.t>=120?1.5:1;d.mana=Math.min(10,d.mana+dt*GW_MANA_REGEN*pace);d.enemyMana=Math.min(10,d.enemyMana+dt*GW_ENEMY_MANA_REGEN*pace);
 if(d.t>=d.nextEnemy)gwEnemyThink(d);
 for(const w of d.warnings)if(!w.done&&d.t>=w.at){w.done=true;gwResolveWarning(d,w);}
 d.warnings=d.warnings.filter(w=>!w.done);d.wards=d.wards.filter(w=>w.until>d.t);d.hexes=d.hexes.filter(w=>w.until>d.t);d.corpses=d.corpses.filter(q=>d.t-q.at<26);
 for(const h of d.hazards){const activeDt=Math.max(0,Math.min(d.t,h.until)-Math.max(d.t-dt,h.start));if(activeDt>0)for(const u of d.units)if(!u.side&&u.hp>0&&u.lane===h.lane&&Math.abs(u.x-h.x)<h.r)gwHurt(d,u,50*d.enemyScale*activeDt);}
 d.hazards=d.hazards.filter(h=>h.until>d.t);
 for(const p of d.portals)if(p.hp>0&&d.t<p.until&&d.t>=p.nextSpawn){p.nextSpawn=d.t+5;p.spawnAt=d.t;for(let i=0;i<2;i++)gwSpawn(d,'thrall',1,p.lane,p.x+i*18);gwFx(d,'hex',p.x,p.y-15,'#bd7bf0',.7,40);}d.portals=d.portals.filter(p=>p.hp>0&&d.t<p.until);
 for(const u of d.units){if(u.hp<=0)continue;const slowed=u.side===1&&d.hexes.some(w=>w.lane===u.lane&&Math.abs(w.x-u.x)<w.r),tempo=slowed?.6:1;u.cd-=dt*tempo;u.moving=false;const dir=u.side?-1:1;
  const enemy=d.units.filter(q=>q.hp>0&&q.side!==u.side&&q.lane===u.lane).sort((a,b)=>Math.abs(a.x-u.x)-Math.abs(b.x-u.x))[0];
  const opposing=1-u.side,portal=!u.side?d.portals.filter(p=>p.hp>0&&p.lane===u.lane).sort((a,b)=>Math.abs(a.x-u.x)-Math.abs(b.x-u.x))[0]:null,structureX=portal?portal.x:d.tower[opposing][u.lane]>0?(u.side?185:775):(u.side?75:885),target=!u.siege&&enemy&&Math.abs(enemy.x-u.x)<Math.abs(structureX-u.x)+30?enemy:null,tx=target?target.x:structureX;u.face=tx>=u.x?1:-1;
  if(Math.abs(tx-u.x)<=u.reach){if(u.cd<=0){u.cd=u.rate;u.attackAt=d.t;if(!(d.soundAt>d.t)){sfx(u.fire?'fire':u.reach>70?'bonespear':u.kind==='brute'||u.kind==='troll'?'brawlheavy':'steelhit',{force:true});d.soundAt=d.t+.15;}const damage=u.dmg*(u.side&&d.rageUntil>d.t&&d.rageLane===u.lane?1.4:1);
   if(u.reach>70){d.shots.push({x:u.x,y:u.y-27,tx,ty:target?target.y-20:[205,345][u.lane]-25,target,portal:target?null:portal,side:opposing,lane:u.lane,damage,splash:u.splash,fire:u.fire,arrow:u.kind==='archer'||u.siege,siege:u.siege,col:u.side?'#ffaa65':'#8bedd5',life:1.5});}
   else if(target){gwHurt(d,target,damage);if(u.splash)for(const other of d.units)if(other!==target&&other.side!==u.side&&other.lane===u.lane&&Math.abs(other.x-target.x)<u.splash)gwHurt(d,other,damage*.55);}
   else if(portal)gwPortalHurt(d,portal,damage);else gwStructureHit(d,opposing,u.lane,damage);
  }}else{let step=u.speed*dt*dir*tempo;const friend=d.units.find(q=>q!==u&&q.side===u.side&&q.lane===u.lane&&q.hp>0&&Math.abs(q.y-u.y)<8&&(q.x-u.x)*dir>0&&(q.x-u.x)*dir<19);if(friend)step=0;u.x=clamp(u.x+step,75,885);u.moving=step!==0;}
 }
 for(let side=0;side<2;side++)for(let lane=0;lane<2;lane++){
  d.towerCd[side][lane]-=dt;if(d.tower[side][lane]<=0||d.towerCd[side][lane]>0)continue;
  const x=side?775:185,near=d.units.filter(u=>u.side!==side&&u.lane===lane&&u.hp>0&&Math.abs(u.x-x)<130).sort((a,b)=>Math.abs(a.x-x)-Math.abs(b.x-x))[0];
  if(near){d.towerCd[side][lane]=1.2;d.shots.push({x,y:[205,345][lane]-38,tx:near.x,ty:near.y-20,target:near,lane,damage:16,splash:0,col:side?'#ffa76e':'#b58df1',life:1.5});}
 }
 for(let side=0;side<2;side++){d.coreCd[side]-=dt;const near=d.units.find(u=>u.side!==side&&u.hp>0&&Math.abs(u.x-(side?885:75))<115);if(near&&d.coreCd[side]<=0){d.coreCd[side]=1.25;gwHurt(d,near,22);gwFx(d,'beam',near.x,near.y-20,side?'#f5ba7c':'#c6a1fb',.3,20);}}
 for(const shot of d.shots){shot.life-=dt;const dx=shot.tx-shot.x,dy=shot.ty-shot.y,dist=Math.hypot(dx,dy),step=330*dt;if(dist<=step){shot.life=0;if(shot.target){if(shot.target.hp>0&&(shot.lane===undefined||shot.target.lane===shot.lane)){gwHurt(d,shot.target,shot.damage);if(shot.splash)for(const u of d.units)if(u!==shot.target&&u.hp>0&&u.side===shot.target.side&&u.lane===shot.target.lane&&Math.abs(u.x-shot.target.x)<shot.splash)gwHurt(d,u,shot.damage*.5);}}else if(shot.portal){gwPortalHurt(d,shot.portal,shot.damage);}else gwStructureHit(d,shot.side,shot.lane,shot.damage);}else{shot.x+=dx/dist*step;shot.y+=dy/dist*step;}}
 d.shots=d.shots.filter(s=>s.life>0);d.units=d.units.filter(u=>u.hp>0);for(const f of d.effects)f.t+=dt;d.effects=d.effects.filter(f=>f.t<f.life);
 if(d.t>=180){d.core[0]=Math.max(0,d.core[0]-dt*8);d.core[1]=Math.max(0,d.core[1]-dt*8);}
 if(d.core[0]<=0||d.core[1]<=0){d.phase=d.core[0]<=0?'lose':'win';d.selected=-1;sfx(d.phase==='win'?'level':'brawlheavy',{force:true});}
}
