function gwDeckUI(d,artReady){return false;}
function gwDeckToggle(d,id){return false;}
function finishGraveWar(result,quiet=false){
 const d=G&&G.graveWar;if(!d)return;G.graveWar=null;G.state='play';$('graveWarUI').hidden=true;for(const k in keys)keys[k]=false;last=performance.now();G.dt=0;
 if(quiet)return;
 if(d.test){showMenu();return;}
 if(result==='win'){G.p.hp=Math.max(1,Math.min(G.p.hp,G.p.maxhp*d.core[0]/d.coreMax[0]));G.p.invuln=Math.max(G.p.invuln,2);d.boss.graveDefeated=true;d.boss.hp=0;killEnemy(d.boss);banner('The '+d.config.name+'’s army is broken!');}
 else{G.p.hp=0;endRun(false);}render();hud();
}
(function installGraveWarInput(){
 const point=e=>{const r=$('graveWarCanvas').getBoundingClientRect();return {x:(e.clientX-r.left)*960/r.width,y:(e.clientY-r.top)*700/r.height};};
 addEventListener('pointermove',e=>{if(G&&G.graveWar)G.graveWar.pointer=point(e);},true);
 addEventListener('pointerdown',e=>{const d=G&&G.graveWar;if(!d)return;e.preventDefault();e.stopImmediatePropagation();const b=e.target.closest('[data-gw]');if(b){const a=b.dataset.gw;if(a==='deck'){gwDeckToggle(d,b.dataset.card);}else if(a==='continue'){if(d.phase==='ready')gwStart(d);else if(d.phase==='win'||d.phase==='lose')finishGraveWar(d.phase);else d.paused=false;}else if(a==='retry'){const kind=d.boss.kind;finishGraveWar('leave',true);startGravePractice(kind);}else if(a==='leave')finishGraveWar('lose');if(G.graveWar)renderGraveWar();return;}
  if(e.button===2){d.selected=-1;return;}const p=point(e);d.pointer=p;if(d.phase!=='fight'||d.paused)return;
  if(p.x>880&&p.y<100){d.paused=true;renderGraveWar();return;}
  const cardSlot=gwCardAt(d,p.x,p.y);if(cardSlot>=0){d.selected=cardSlot;renderGraveWar();return;}
  const placement=gwPlacement(d,p);if(placement)gwPlay(d,d.selected,placement.x,placement.lane);renderGraveWar();
 },true);
 addEventListener('contextmenu',e=>{if(G&&G.graveWar){e.preventDefault();e.stopImmediatePropagation();}},true);
 addEventListener('keydown',e=>{const d=G&&G.graveWar;if(!d)return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(e.code==='Escape'&&d.phase==='fight'){d.paused=!d.paused;renderGraveWar();}else if(/^Digit[1-4]$/.test(e.code)&&d.phase==='fight'&&!d.paused){d.selected=+e.code.slice(-1)-1;renderGraveWar();}},true);
 addEventListener('keyup',e=>{if(G&&G.graveWar){e.preventDefault();e.stopImmediatePropagation();}},true);
 addEventListener('blur',()=>{if(G&&G.graveWar&&G.graveWar.phase==='fight'){G.graveWar.paused=true;renderGraveWar();}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&G&&G.graveWar&&G.graveWar.phase==='fight'){G.graveWar.paused=true;renderGraveWar();}});
})();

