 bsPX(c,20,218,185,17,'#3d3542');bsPX(c,24,215,177,4,'#97846b');bsPX(c,30,236,165,4,'#201e2c');for(let i=0;i<9;i++)bsPX(c,40+i*18,222,7,3,i%2?'#c6b180':'#82a897');
 for(const x of [67,157])for(let y=0;y<57;y+=6){bsPX(c,x,y,2,4,'#917f72');bsPX(c,x+2,y+3,2,3,'#544e58');}
 bsPixelMech(c,112,196,w.draft,.45);
 c.save();c.scale(.5,.5);const cell=45,ox=22.5,oy=25;
 for(let y=1;y<=8;y++)for(let x=0;x<9;x++){const px=ox+x*cell,py=oy+y*cell;if(x===4){bsPixelBone(c,px,py-13,px,py+13,3,'#a78d72');continue;}c.globalAlpha=.6;bsPX(c,px-19,py-19,38,38,'#151d28');c.globalAlpha=1;for(const [dx,dy]of [[-19,-19],[13,-19],[-19,13],[13,13]]){bsPX(c,px+dx,py+dy,6,2,'#6b6261');bsPX(c,px+dx,py+dy,2,6,'#6b6261');}}
