 if(w.selected&&w.hover){const q={id:w.selected,x:w.hover.x,y:w.hover.y,rot:w.rot,rank:(w.draft.find(q=>q.id===w.selected)||{}).rank||1},v=bsValidate([...w.draft.filter(p=>p.id!==q.id),q],w.budget);for(const [x,y]of bsCells(q)){const px=ox+x*cell,py=oy+y*cell;c.globalAlpha=.7;bsPX(c,px-19,py-19,38,38,v.ok?'#81cfb0':'#bf606c');c.globalAlpha=1;}}
 c.restore();c.font='bold 6px monospace';c.textAlign='center';c.fillStyle='#efd3a0';c.fillText(w.selected?'PLACE '+BS_PARTS[w.selected].name.toUpperCase()+' / R ROTATES':'BONE FRAME / PILOT INSIDE',112,246);out.imageSmoothingEnabled=false;out.clearRect(0,0,450,500);out.drawImage(bsBoardPixel,0,0,450,500);
