// End Bone Shaping
function brawlerBase(key,p=G.p){return Math.round(key==='P'?40*Math.pow(1.45,Math.max(0,(p.ranks.provo||1)-1)):52*Math.pow(1.5,Math.max(0,(p.ranks.charm||1)-1)));}
function releaseTavernGuest(e,exhaust=true,force=false){
 if(e.tavernRequired&&!e.dead&&!force)return;
 const v=e.tavern;if(!v)return;const f=v.house,a=v.slot*2.399;
 e.tavern=null;e.beerUntil=0;e.kx=e.kz=0;e.x=f.x+Math.cos(a)*(60+e.r+v.slot%3*7);e.z=f.z-48-e.r-Math.abs(Math.sin(a))*(22+v.slot%3*7);keepInBounds(e);e.mesh.visible=true;
 if(v.scale)e.mesh.scale.copy(v.scale);e.mesh.position.set(e.x,gAt(e.x,e.z),e.z);
 if(exhaust&&!e.dead){e.bardExhaustUntil=G.t+(e.boss?.35:1.5);applyEnemyStun(e,e.boss?.2:1.2);}
}
function tavernCommittedBoss(f){return f.guests.some(e=>e.tavernRequired&&!e.dead&&e.tavern&&e.tavern.house===f);}
function endTavern(f){if(f.closed||tavernCommittedBoss(f))return;f.closed=true;for(const e of f.guests)if(e.tavern&&e.tavern.house===f)releaseTavernGuest(e);}
// The building contains guests; its front approach stays clear for boss entry.
function tavernDoorProtected(p=G.p){
 if(p.stance!=='b_provo')return false;
 return G.fx.some(f=>f.type==='brawlertavern'&&!f.closed&&f.t>=.32&&f.t<f.dur-.4&&Math.abs(p.x-f.x)<25&&p.z-f.z>20&&p.z-f.z<84&&!!tavernDuelBoss(f));
}
function keepEnemiesOutsideTaverns(e){
 if(e.dead||e.tavern)return;
 for(const f of G.fx){
  if(f.type!=='brawlertavern'||f.closed||f.t<.05||f.t>=f.dur-.4)continue;
  const radius=(e.r||6)+5,dx=e.x-f.x,dz=e.z-f.z,hw=43+radius,hd=34+radius;
  if(Math.abs(dx)<hw&&Math.abs(dz)<hd){
   const px=hw-Math.abs(dx),pz=hd-Math.abs(dz);
   if(px<pz){e.x=f.x+(dx<0?-hw:hw);}else e.z=f.z+(dz<0?-hd:hd);
   e.kx=e.kz=0;
  }
  // Side lanes remain traversable, but enemies cannot occupy the boss doorway.
  if(tavernDuelBoss(f)&&Math.abs(e.x-f.x)<28+radius&&e.z-f.z>18-radius&&e.z-f.z<88+radius){e.x=f.x+(e.x<f.x?-1:1)*(43+radius);e.kx=e.kz=0;}
 }
}

function landBrawlerBeer(f){
 const p=G.p,l=f.rank,r=(95+(l-1)*20)*p.area;
 for(const old of G.fx)if(old.type==='brawlertavern'&&!old.closed&&!tavernCommittedBoss(old)){endTavern(old);old.t=Math.max(old.t,old.dur-.35);}
 const house={type:'brawlertavern',t:0,dur:8+(l-1)+(p.rm.beerDuration||0),x:f.tx,z:f.tz,r,rank:l,guests:[],beat:0,arrivalDamage:brawlerBase('P')*(.9+(l-1)*.35)*p.dmg,damage:brawlerBase('P')*.7*(1+(l-1)*.45)*p.dmg*(1+(p.rm.beerPower||0)),closed:false};
 G.fx.push(house);
 for(const e of G.enemies.slice()){
  if(e.dead||e.boss||e.def.boss||e.tavernRequired||e.phased||e.def.pod||Math.hypot(e.x-f.tx,e.z-f.tz)>r+e.r)continue;
  // Bring them inside before damage; the throw must not kill the whole audience before the fight appears.
  const heavy=e.boss||e.def.elite;if(e.tavernImmuneUntil>G.t)continue;
  interruptShowtimeEnemy(e);e.mesh.visible=false;e.tavernRequired=false;const hold=e.tavernRequired?Infinity:e.boss?2.4:house.dur-.4;
  // Captured bosses use the existing doorway hint; no announcement over combat.
  e.tavern={house,slot:house.guests.length,start:G.t,x:e.x,z:e.z,until:G.t+hold,scale:e.mesh.scale.clone()};
  if(heavy)e.tavernImmuneUntil=G.t+hold+8;e.beerUntil=G.t+hold;e.provoT=0;house.guests.push(e);
 }
 emit(f.tx,gAt(f.tx,f.tz)+3,f.tz,40,{col:new T.Color('#c3a177'),col2:new T.Color('#f8dfaa'),spd:r,up:.3,vy:18,life:.6,size:3,grav:40});sfx('beersplash',{x:f.tx,z:f.tz,force:true});
}
function tickTavernGuest(e,dt){
 const v=e.tavern;if(!v)return false;const f=v.house;
 if(f.closed||G.t>=v.until){releaseTavernGuest(e);return false;}
 const k=clamp((G.t-v.start)/.65,0,1),u=k*k*(3-2*k);e.x=v.x+(f.x-v.x)*u;e.z=v.z+(f.z+27-v.z)*u;e.yaw=Math.atan2(f.x-e.x,f.z+27-e.z);e.kx=e.kz=0;e.movingNow=true;
 if(k<1&&e.act)playAnim(e,'Running_A',false,1.5);
 return true;
}
function updateTavern(f){
 if(tavernCommittedBoss(f))f.dur=Math.max(f.dur,f.t+2);
 if(f.t>=f.dur-.4){endTavern(f);return;}if(f.closed)return;
 const alive=f.guests.some(e=>!e.dead&&e.tavern&&e.tavern.house===f);if(!alive&&f.clearAt===undefined){f.clearAt=f.t;f.dur=Math.min(f.dur,f.t+1.25);if(f.guests.length)G.texts.push({x:f.x,z:f.z,y:65,s:'BAR CLEARED!',col:'#f4cf85',t:.9,t0:.9});}
 const beat=Math.max(0,Math.floor(f.t-.2));if(beat<=f.beat)return;const count=beat-f.beat;f.beat=beat;let total=0;
 for(let n=0;n<count;n++)for(const e of f.guests.slice()){
  if(e.dead||!e.tavern||e.tavern.house!==f)continue;
  if(G.t>=e.tavern.until){releaseTavernGuest(e);continue;}
  if(e.boss||e.def.boss)continue;
  const hp=e.hp;G.tavernHit=true;SFX.area++;try{hitEnemy(e,(f.damage+(beat-count+n<3?f.arrivalDamage/3:0)),0,0,true,true);}finally{SFX.area--;G.tavernHit=false;}total+=Math.min(hp,hp-e.hp);
 }
 if(total>0)G.texts.push({x:f.x,z:f.z,y:65,s:'BRAWL '+Math.round(total),col:'#f4cf85',t:.75,t0:.75});if(total>0||f.guests.some(e=>!e.dead&&e.tavern&&e.tavern.house===f))sfx('brawlheavy',{x:f.x,z:f.z});
}
function renderTavernGuest(e){e.mesh.visible=false;}

