 const mat=c=>new T.MeshLambertMaterial({color:new T.Color(c).convertSRGBToLinear()});
 const piece=(geo,c,x,y,z,parent=g)=>{const m=new T.Mesh(geo,mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;};
