 strut([-38,40,27],[0,74,27],3.2,3.5,beam);strut([0,74,27],[38,40,27],3.2,3.5,beam);strut([0,41,27],[0,73,27],3,3,beam);
 strut([-20,43,27],[0,61,27],2.2,2.8,wood);strut([20,43,27],[0,61,27],2.2,2.8,wood);
