 for(let i=0;i<9;i++){const a=(i+.5)*Math.PI/9,m=piece(new T.BoxGeometry(4.1,5,5.5),i%2?'#ada68b':'#929787',Math.cos(a)*12.3,24+Math.sin(a)*12.3,28.5);m.rotation.z=a-Math.PI/2;}
 box(0,2,34,28,2,15,'#a09a86');box(0,1,40,32,1.5,7,'#777b71');
 const pivot=new T.Group();pivot.position.set(-9.7,4,29);g.add(pivot);const doors=[pivot];
