 m.position.y+=Math.abs(Math.sin(phase))*(2.8+energy*2.5)+Math.sin(cheer*Math.PI)*1.8;m.rotation.z=Math.sin(phase)*(.14+energy*.07);m.rotation.y=e.yaw+Math.sin(phase*.5)*(.55+energy*.30);
