 if(e.bardExhaustUntil>G.t){const c=octx;c.save();c.textAlign='center';c.font='bold 9px Arial';c.strokeStyle='#182334';c.lineWidth=3;c.fillStyle='#b8d4e8';c.strokeText('EXHAUSTED',x,y-5);c.fillText('EXHAUSTED',x,y-5);c.restore();return;}
