 for(let i=0;i<2;i++){const phase=(t*.8+i*.5)%1,xx=x+(i?13:-13)+Math.sin(t*5+i)*4,yy=y-12-phase*15;c.globalAlpha=Math.min(1,(1-phase)*3);c.strokeText(i?'♪':'♫',xx,yy);c.fillText(i?'♪':'♫',xx,yy);}c.globalAlpha=1;c.font='bold 9px Arial';const label=bardDancing(e)?(showtimeBoss(e)?'CAPTIVATED':'DANCING'):'ENJOYING';c.strokeText(label,x,y-2);c.fillText(label,x,y-2);c.restore();
