 A.base=trapperMerge(base);const jaw=[];for(let i=0;i<12;i++){const a=-Math.PI/2+(i+.5)/12*Math.PI,x=Math.cos(a)*7,z=Math.sin(a)*7;jaw.push(box([x,1,z],[2.1,1.4,2.2],'#9ba7aa',[0,-a,0]));if(i%2===0)jaw.push({geo:new T.ConeGeometry(1.3,3.4,3),p:[x,3.1,z],c:'#e5e4d7',rot:[0,a,0]});}A.jaw=trapperMerge(jaw);
 const mine=[cyl([0,1,0],[6.5,2,6.5],'#383f43'),cyl([0,2.3,0],[5.8,.7,5.8],'#818d8c'),cyl([0,2.9,0],[2.5,.7,2.5],'#c39e4d')];for(let i=0;i<6;i++){const a=i*TAU/6;mine.push(box([Math.cos(a)*4.7,2.9,Math.sin(a)*4.7],[1,.7,2],'#292f33',[0,-a,0]));}A.mine=trapperMerge(mine);
 A.canister=trapperMerge([cyl([0,3.8,0],[3.6,7,3.6],'#6e8c36'),cyl([0,1.3,0],[3.9,1.4,3.9],'#465252'),cyl([0,6.4,0],[3.9,1,3.9],'#b3b8a7'),box([0,8,0],[5,1,1.4],'#b69a5b'),box([0,8,0],[1.4,1,5],'#b69a5b'),box([3.5,3.8,0],[.8,3,1.5],'#d3df72')]);
 A.beacon=trapperMerge([cyl([0,1,0],[8,2,8],'#3b4549'),cyl([0,3,0],[5,2,5],'#b89b64'),cyl([0,9,0],[1.3,11,1.3],'#75858b'),box([0,15,0],[9,1.4,3],'#c5ac79'),box([-4,11,0],[1.2,7,3],'#4a575d'),box([4,11,0],[1.2,7,3],'#4a575d')]);
 A.rotor=trapperMerge([box([0,0,0],[13,1.1,2],'#d9bd76'),box([0,0,0],[2,1.1,13],'#d9bd76')]);
 const spikes=[];for(let i=0;i<4;i++)spikes.push({geo:new T.ConeGeometry(.8,6,4),p:[0,1.2,0],rot:[i===3?0:1.1,i*TAU/3,0],c:i%2?'#c2cbd0':'#788a92'});A.caltrop=trapperMerge(spikes);
