 A.steelMat=new T.MeshLambertMaterial({vertexColors:true});A.hotMat=new T.MeshLambertMaterial({vertexColors:true,emissive:'#a95b18',emissiveIntensity:.7});A.ledMat=new T.MeshBasicMaterial({color:'#f6b94a'});A.greenMat=new T.MeshBasicMaterial({color:'#badf4e'});A.sphere=new T.IcosahedronGeometry(1,1);A.chip=new T.ConeGeometry(.7,2,3);A.plane=new T.PlaneGeometry(1,1);A.ring=new T.RingGeometry(.94,1,48);A.ring.rotateX(-Math.PI/2);A.tracer=new T.ConeGeometry(.6,8,5);A.tracer.rotateZ(Math.PI/2);A.tracerMat=new T.MeshBasicMaterial({color:'#ed9f48',transparent:true,opacity:.6,depthWrite:false});A.dummy=new T.Object3D();return A;
