 if(f.kind==='beacon'){const arrive=Math.min(1,f.t/.18);g.position.y=gAt(f.x,f.z)+.4+(1-arrive)*15;f.rotor.rotation.y=G.t*8;g.children[0].material.opacity=fade;f.rotor.material.opacity=fade;for(const m of g.children)if(m.userData.wave!==undefined){const q=(f.t*.8+m.userData.wave*.5)%1;m.scale.setScalar(f.r*(.1+.9*q));m.material.opacity=.24*(1-q)*fade;m.position.y=.2;}return;}
