 c.mesh.quaternion.copy(c.trapperDeathQ).premultiply(new T.Quaternion().setFromAxisAngle(c.trapperAxis,.24*hold+flight*4.47));
 if(c.trapperSpine)c.trapperSpine.quaternion.copy(c.trapperSpineQ).premultiply(new T.Quaternion().setFromAxisAngle(c.trapperBendAxis,.5*hold*(1-u)));
 const fade=t>1.2?Math.max(.015,1-(t-1.2)/.35):1;c.mesh.scale.copy(c.trapperDeathScale).multiplyScalar(fade);
