 const [chips,flash]=f.mesh.children,fade=Math.max(0,1-k),t=f.t;
 for(let i=0;i<f.n;i++){
  const a=(i-4)*.43,speed=28+(i%4)*11,s=.35+(i%3)*.14;
  boneStamp(chips,i,Math.cos(a)*speed*t,Math.max(.1,7+(12+i%3*7)*t-50*t*t),Math.sin(a)*speed*t,i+t*12,i*.7+t*8,t*9,s*fade,s*fade,s*fade);
 }
