function boneProjectileMesh(){const A=boneArt(),g=new T.Group();g.userData.boneArt=true;const body=new T.Mesh(A.spear,A.mat);g.add(body);const trail=new T.Mesh(A.trail,A.trailMat);g.add(trail);return g;}
function boneHaloMesh(){const A=boneArt(),m=new T.Mesh(A.halo,A.mat);m.userData.boneHalo=true;return m;}
function boneOwnedMesh(geo,col,opacity=1){return new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:!!geo.attributes.color,color:col||'#ffffff',flatShading:true,transparent:true,opacity,depthWrite:opacity>=1,side:T.DoubleSide}));}
