 const m=f.mesh.children[0],t=f.t,fade=Math.min(1,(1-k)*3),r=f.r||8;
 for(let i=0;i<n;i++){
  const a=i*2.399963,start=f.ground?r*(.35+(i%4)*.17):0,speed=f.type==='bonehit'?12:22+i%5*5;
  const x=Math.cos(a)*(start+speed*t),z=Math.sin(a)*(start+speed*t),y=Math.max(.25,(f.height||4)+(18+i%4*5)*t-60*t*t),s=(f.type==='bonehit'?.25:.35)+(i%3)*.09;
  boneStamp(m,i,x,y,z,a+t*7,a*2+t*3,t*8,s*fade,s*fade,s*fade);
 }m.instanceMatrix.needsUpdate=true;m.material.opacity=fade;
