  boneStamp(spines,i,q.x,h*.52-sink,q.z,0,-a,Math.PI/2-.18,h/26,s,s);
  for(let j=0;j<2;j++)boneStamp(ribs,i*2+j,q.x+Math.cos(a+(j?1:-1)*1.4)*5,-sink,q.z+Math.sin(a+(j?1:-1)*1.4)*5,0,Math.PI-a+(j?.65:-.65),-.35,.65,grow*.8,.65);
