 if(!f.mesh){const g=legacyGroup(f),vertebra=boneInstances(A.vertebra,n),ribs=boneInstances(A.rib,n*2),head=boneOwnedMesh(A.spear),shaft=boneOwnedMesh(A.shaft);g.rotation.y=-f.a;if(f.colossus)g.position.y+=3;g.add(vertebra,ribs,head,shaft);}
 const [spine,ribs,head,shaft]=f.mesh.children,t=f.t,reach=clamp(t/.11,0,1),fade=clamp((f.dur-t)/.24,0,1),len=f.len*reach;
