  const u=(i+.5)/n,x=u*len,width=(.45+Math.sin(u*Math.PI)*.35)*(f.w/10),wave=Math.sin(u*5-t*18)*.5;
  boneStamp(spine,i,x,8+wave,0,0,0,Math.PI/2,len/n*.52,2.4*width,3.4*width);
  for(let j=0;j<2;j++){const side=j?1:-1;boneStamp(ribs,i*2+j,x,8+wave,side*2.4*width,side*Math.PI/2,0,0,.35*width,.37*width,.4*width);}
