function townTick(dt){if(!TOWN.ready||!MAP.town)return;const t=G?G.t:performance.now()/1000;
 if(TOWN.bell){const B=TOWN.bell;if(B.t>0){B.t-=dt;B.pivot.rotation.z=Math.sin(B.t*7)*.45*Math.min(1,B.t/1.5);}else B.pivot.rotation.z*=Math.pow(.02,dt);}
 for(const c of TOWN.chains)c.g.rotation.x=Math.sin(t*.9+c.ph)*.06;
 if(TOWN.mist){TOWN.mist.material.opacity=.28+Math.sin(t*1.3)*.1;TOWN.mistT=(TOWN.mistT||0)-dt;if(TOWN.mistT<=0&&G){TOWN.mistT=.25;const a=rnd(0,TAU),r=rnd(4,18);emit(Math.cos(a)*r,hAt(0,0)+5,Math.sin(a)*r,2,{col:new T.Color('#3fae5a'),col2:new T.Color('#1e5a30'),spd:3,up:1,vy:7,life:1.6,size:2.6,grav:0,spread:2});}}
 if(G&&G.p)for(const c of TOWN.crows){const p=G.p;if(c.fly>0){c.fly-=dt;c.s.position.x+=c.vx*dt;c.s.position.z+=c.vz*dt;c.s.position.y+=c.vy*dt;c.vy-=10*dt;if(c.vy<4)c.vy=4;c.s.material.rotation=Math.sin(t*25)*.5;if(c.fly<=0){c.s.visible=false;c.t=rnd(8,16);}}
  else if(!c.s.visible){c.t-=dt;if(c.t<=0&&Math.hypot(p.x-c.hx,p.z-c.hz)>120){c.s.visible=true;c.s.position.set(c.hx,hAt(c.hx,c.hz)+3,c.hz);c.s.material.rotation=0;}}
  else if(Math.hypot(p.x-c.hx,p.z-c.hz)<55){c.fly=2.2;const a=Math.atan2(c.hz-p.z,c.hx-p.x)+rnd(-.6,.6);c.vx=Math.cos(a)*70;c.vz=Math.sin(a)*70;c.vy=40;}}}
function onBellToll(delay){if(!TOWN.ready||!TOWN.bell||!MAP.town)return;setTimeout(()=>{if(!TOWN.bell)return;TOWN.bell.t=1.6;if(G&&(G&&G.state==='play')){fx('ring',{x:TOWN.bell.x,z:TOWN.bell.z,r:90,dur:1.2,col:'#8a7a40'});}},Math.max(0,delay*1000));}


