function boxesGeo(boxes){const pos=[],nor=[],col=[],idx=[];let vi=0;const C=new T.Color();
 for(const b of boxes){C.set(b.c).convertSRGBToLinear();const x0=b.x-b.w/2,x1=b.x+b.w/2,y0=b.y,y1=b.y+b.h,z0=b.z-b.d/2,z1=b.z+b.d/2;const shade=b.s||1;
  const faces=[[[x1,y0,z1],[x1,y0,z0],[x1,y1,z0],[x1,y1,z1],[1,0,0],.86],[[x0,y0,z0],[x0,y0,z1],[x0,y1,z1],[x0,y1,z0],[-1,0,0],.72],[[x0,y1,z1],[x1,y1,z1],[x1,y1,z0],[x0,y1,z0],[0,1,0],1],[[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1],[0,-1,0],.5],[[x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1],[0,0,1],.92],[[x1,y0,z0],[x0,y0,z0],[x0,y1,z0],[x1,y1,z0],[0,0,-1],.66]];
  for(const f of faces){for(let i=0;i<4;i++){pos.push(...f[i]);nor.push(...f[4]);col.push(C.r*f[5]*shade,C.g*f[5]*shade,C.b*f[5]*shade);}idx.push(vi,vi+1,vi+2,vi,vi+2,vi+3);vi+=4;}}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('normal',new T.Float32BufferAttribute(nor,3));g.setAttribute('color',new T.Float32BufferAttribute(col,3));g.setIndex(idx);return g;}
