const FADE_CACHE=new Map();
function fadeToon(src){if(FADE_CACHE.has(src))return FADE_CACHE.get(src);const m=src.clone();const celPass=src.userData.decorCel?src.onBeforeCompile:null;m.onBeforeCompile=sh=>{if(celPass)celPass(sh);sh.uniforms.uPlayer=FADE_U;sh.uniforms.uCamDir=FADE_D;sh.vertexShader='varying vec3 vWPos;\n'+sh.vertexShader.replace('#include <project_vertex>','#include <project_vertex>\nvec4 wp4=vec4(transformed,1.0);\n#ifdef USE_INSTANCING\nwp4=instanceMatrix*wp4;\n#endif\nvWPos=(modelMatrix*wp4).xyz;');sh.fragmentShader='varying vec3 vWPos;uniform vec3 uPlayer;uniform vec2 uCamDir;\n'+sh.fragmentShader.replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\n'+FADE_GLSL).replace('#include <color_fragment>','#include <color_fragment>\ndiffuseColor.a*=1.0-fadeK;');};m.transparent=true;m.customProgramCacheKey=()=>'fade'+(celPass?'-cel':'');FADE_CACHE.set(src,m);return m;}
