// Britannia uses one flat gameplay plane; other maps retain their existing terrain.
const WATER_Y=-9;
function hAt(x,z){if(MAP.id==='britannia')return 0;if(MAP.dungeon)return 1+vnoise(x*.02+9,z*.02+9)*1.4;if(MAP.town){const bog=Math.hypot(x+580,z-540);const sink=bog<190?Math.min(1,(190-bog)/50)*16:0;const hill=Math.max(0,1-Math.hypot(x,z+720)/170);return 3+vnoise(x*.02+9,z*.02+9)*1.6-sink+hill*hill*10;}const d2=(x*x+z*z)/(260*260);return (vnoise(x*.0019+3,z*.0019+3)-.5)*40+(vnoise(x*.0075+5,z*.0075+5)-.5)*9+5+12*Math.exp(-d2);}
