// dirt roads: a warped noise iso-line, so paths bend and fork instead of following the noise lattice in straight lines
function roadAt(x,z){const wx=x+(vnoise(x*.0031+7,z*.0031+7)-.5)*220+(vnoise(x*.011+31,z*.011+31)-.5)*40,wz=z+(vnoise(x*.0031+77,z*.0031+77)-.5)*220+(vnoise(x*.011+91,z*.011+91)-.5)*40;return Math.abs(vnoise(wx*.0021+100,wz*.0021+100)-.5);}
