function decorCelMat(src){if(!src||src.userData.decorCel)return src;let m=DECOR_CEL.mats.get(src);if(!m){m=monsterCel(src.clone(),'decor');m.userData.decorCel=true;m.customProgramCacheKey=()=>'decor-cel-v1';DECOR_CEL.mats.set(src,m);}return m;}
