function jitterColors(geo,base,amt){const C=new T.Color(base).convertSRGBToLinear();const n=geo.attributes.position.count,cols=[];for(let i=0;i<n;i++){const f=Math.floor(i/3);const k=1+(hash2(f,17)-.5)*amt;cols.push(C.r*k,C.g*k,C.b*k);}geo.setAttribute('color',new T.Float32BufferAttribute(cols,3));return geo;}
