function treePine(){const trunk=jitterColors(new T.CylinderGeometry(1.2,1.8,10,6).translate(0,5,0),'#5a3a1a',.2);const c1=jitterColors(new T.ConeGeometry(9,12,7).translate(0,13,0),'#2e6e2c',.35),c2=jitterColors(new T.ConeGeometry(7,10,7).translate(0,19,0),'#3a8234',.35),c3=jitterColors(new T.ConeGeometry(4.5,8,7).translate(0,25,0),'#479440',.35);return mergeGeos([trunk,c1,c2,c3]);}
