function rockGeo(){return mergeGeos([jitterColors(new T.DodecahedronGeometry(4.5,0).translate(0,2.5,0),'#8a8a7a',.3),jitterColors(new T.DodecahedronGeometry(2.8,0).translate(3,1.8,1.5),'#9a9a8a',.3)]);}
function grassGeo(){return mergeGeos([jitterColors(new T.ConeGeometry(.9,4,3).translate(0,2,0),'#5a6e38',.3),jitterColors(new T.ConeGeometry(.8,3.2,3).translate(1.2,1.6,.6),'#4e6230',.3),jitterColors(new T.ConeGeometry(.8,3.6,3).translate(-1,1.8,-.5),'#66783c',.3)]);}
