 const put=(k,x,z,rot,sc,blockR)=>{if(!lists[k])lists[k]=[];P.set(x,hAt(x,z)-.2,z);Q.setFromAxisAngle(up,rot||0);S.set(sc||1,sc||1,sc||1);M.compose(P,Q,S);lists[k].push(M.clone());if(blockR)DECOR.push({x,z,r:blockR});};
