// Britannia Survivors code-native mesh batch v1
// Requires existing globals: T, MAT, boxesGeo, glowTex

// give a plain THREE geometry a flat vertex color so it can share MAT (vertexColors:true)
function tintGeo(geo, hex) {
  const C = new T.Color(hex).convertSRGBToLinear();
  const n = geo.attributes.position.count, col = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { col[i*3] = C.r; col[i*3+1] = C.g; col[i*3+2] = C.b; }
  geo.setAttribute('color', new T.BufferAttribute(col, 3));
  return geo;
}
