function meshFromBoxes(parts) {
  const m = new T.Mesh(boxesGeo(parts), MAT);
  m.castShadow = true;
  return m;
}

function addGlow(group, color, size, y) {
  const s = new T.Sprite(new T.SpriteMaterial({
    map: glowTex(),
    color,
    transparent: true,
    depthWrite: false,
    blending: T.AdditiveBlending
  }));
  s.scale.setScalar(size);
  s.position.y = y || 0;
  group.add(s);
  return s;
}

function halberdMesh(){return halWeapon();}

function wispMesh() {
  const g = new T.Group();

  const core = new T.Mesh(new T.IcosahedronGeometry(2.2, 0), new T.MeshBasicMaterial({
    color: '#9ad0ff',
    transparent: true,
    opacity: .82,
    depthWrite: false
  }));
  core.position.y = 8;
  g.add(core);

  const ring = new T.Mesh(new T.TorusGeometry(3.2, .12, 6, 18), new T.MeshBasicMaterial({
    color: '#ffe060',
    transparent: true,
    opacity: .75,
    depthWrite: false
  }));
  ring.position.y = 8;
  ring.rotation.x = Math.PI / 2;
  g.add(ring);

  const shards = [];
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2;
    const sh = meshFromBoxes([{x:0,y:0,z:0,w:.55,h:1.7,d:.55,c:i % 2 ? '#f8ffff' : '#7ad0ff'}]);
    sh.position.set(Math.cos(a) * 3.3, 8 + Math.sin(i) * .8, Math.sin(a) * 3.3);
    sh.rotation.z = a;
    g.add(sh);
    shards.push(sh);
  }

  g.userData.core = core;
  g.userData.ring = ring;
  g.userData.spin = [ring].concat(shards);
  g.userData.bob = core;
  addGlow(g, '#9ad0ff', 13, 8);
  return g;
}

