 root.userData.flash=()=>{};root.userData.sc=1;root.userData.atkDur=kind==='drake'?.5:.35;root.userData.parts=parts;root.userData.dispose=()=>{if(root.userData.disposed)return;root.userData.disposed=true;root.traverse(o=>{if(o.userData.spiritOwnGeo)o.geometry.dispose();if(o.userData.spiritOwnMat)o.material.dispose();});};root.userData.anim(0,'idle',0);return root;
