function conjurerBladeMesh(){const A=spiritArt(),g=new T.Group(),s=new T.Shape();s.moveTo(0,5);s.lineTo(1.25,1.4);s.lineTo(.6,-2.8);s.lineTo(-.6,-2.8);s.lineTo(-1.25,1.4);s.closePath();if(!A.blade){A.blade=new T.ShapeGeometry(s);A.blade.rotateX(Math.PI/2);}spiritPiece(g,A.blade,'#bcd8e5',0,0,0,1,1,1,true);const h=spiritPiece(g,A.shaft,'#9a7748',0,0,-4,.45,3,.45);h.rotation.x=Math.PI/2;const guard=spiritPiece(g,A.facet,'#d8be7d',0,0,-2.5,2.1,.45,.45);spiritPiece(g,A.facet,'#8ac8e3',0,.3,-2.5,.4,.4,.4,true);g.userData.conjurerBlade=true;return g;}

function summonDeparture(pet){if(!pet.custom||!pet.mesh.userData.anim||pet.kind==='spider'){scene.remove(pet.mesh);if(pet.risen)disposeEnemyRig(pet);if(pet.temp&&pet.mesh.userData.dispose)pet.mesh.userData.dispose();return;}const m=pet.mesh;m.userData.summonExitDispose=!!pet.temp;fx('summonExit',{x:pet.x,z:pet.z,dur:.6,mesh:m,pet});}
