/*
BRITANNIA SURVIVORS — FOUR ELITE MODELS
Three.js r128 / plain script / T = THREE

Requires existing: T, MAT, boxesGeo(), glowTex()

Factories:
  ironboundKnightMesh()  // ~23 units tall
  plagueGardenerMesh()   // ~21 units tall
  stormChannelerMesh()   // ~23 units tall
  soulLanternMesh()      // ~20 units tall, floating

All face +Z. Ground origin is y=0.
Geometry is cached across instances.
Animation updates allocate no geometry or materials.

Animation:
  animateBritanniaElite(mesh, timeSeconds, state, progress)

state:
  'idle', 'walk', 'windup', 'attack',
  'recover', 'hit', 'death'

progress:
  normalized 0..1 within the current state.
  The game's AI supplies its existing state timing.
  Keep calling 'death' at progress=1 until removed.

Do not run a skeletal mixer on these procedural models.
No damage, cooldowns, projectiles or gameplay are defined here.
*/

const BS_ELITE_GEO = Object.create(null);
const BS_ELITE_GLOW = Object.create(null);

function bsEliteBox(x, y, z, w, h, d, c) {
  return {x:x, y:y, z:z, w:w, h:h, d:d, c:c};
}

function bsEliteRoot(kind) {
  const root = new T.Group();
  root.name = kind;
  const rig = new T.Group();
  root.add(rig);

  root.userData.elite = {
    kind:kind,
    rig:rig,
    parts:[],
    glows:[],
    legs:[],
    orbit:[]
  };
  root.userData.legs = root.userData.elite.legs;
  return root;
}

// Every part has a pivot; box coordinates are local to that pivot.
function bsElitePart(root, name, parent, x, y, z, boxes) {
  const u = root.userData.elite;
  const key = u.kind + ':' + name;
  if (!BS_ELITE_GEO[key]) {
    BS_ELITE_GEO[key] = boxesGeo(boxes);
  }

  const pivot = new T.Group();
  pivot.name = name;
  pivot.position.set(x, y, z);

  const mesh = new T.Mesh(BS_ELITE_GEO[key], MAT);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  pivot.add(mesh);
  parent.add(pivot);

  pivot.userData.restX = x;
  pivot.userData.restY = y;
  pivot.userData.restZ = z;

  u.parts.push(pivot);
  u[name] = pivot;
  root.userData[name] = pivot;
  return pivot;
}

function bsEliteGlow(root, parent, color, x, y, z, size) {
  if (!BS_ELITE_GLOW[color]) {
    BS_ELITE_GLOW[color] = new T.SpriteMaterial({
      map:glowTex(),
      color:color,
      transparent:true,
      opacity:0.65,
      depthWrite:false,
      blending:T.AdditiveBlending
    });
  }

  const sprite = new T.Sprite(BS_ELITE_GLOW[color]);
  sprite.position.set(x, y, z);
  sprite.scale.set(size, size, 1);
  sprite.userData.baseSize = size;
  parent.add(sprite);
  root.userData.elite.glows.push(sprite);
  return sprite;
}


// IRONBOUND KNIGHT:
// Broad plate armor, slit visor, tower shield and heavy warhammer.
function ironboundKnightMesh() {
  const root = bsEliteRoot('ironbound');
  const u = root.userData.elite;
  const B = bsEliteBox;
  const steel = '#687482';
  const edge = '#a7b3bd';
  const dark = '#303a48';
  const gold = '#b0a070';

  bsElitePart(root, 'body', u.rig, 0, 9, 0, [
    B(0,0,0,8,8,5,steel),
    B(0,5,2.7,5,2,0.7,gold),
    B(0,0,2.7,8,1,0.7,dark),
    B(-5,6,0,3,3,6,edge),
    B(5,6,0,3,3,6,edge),
    B(0,-1,-2.8,6,8,0.7,'#563d42')
  ]);

  bsElitePart(root, 'head', u.body, 0, 8, 0, [
    B(0,0,0,5,5,5,steel),
    B(0,2,2.6,4,0.65,0.5,dark),
    B(0,2.1,2.9,2.8,0.3,0.3,'#e8c860'),
    B(0,5,0,0.8,1,4,gold)
  ]);

  for (let i=0; i<2; i++) {
    const leg = bsElitePart(
      root, 'leg'+i, u.rig, i===0 ? -2.5 : 2.5, 9, 0, [
        B(0,-7,0,3,7,3.5,steel),
        B(0,-9,1,3.6,2,5,dark),
        B(0,-4,1.9,3.3,2,0.8,edge)
      ]
    );
    u.legs.push(leg);
  }

  bsElitePart(root, 'shieldArm', u.body, -5, 5, 0, [
    B(0,-5,0,2,5,2,dark),
    B(-0.5,-5,2.5,5,9,1.5,steel),
    B(-0.5,-4.5,3.4,3.8,8,0.4,edge),
    B(-0.5,-2,3.8,0.7,4,0.4,gold),
    B(-0.5,-0.5,3.8,3,0.7,0.4,gold)
  ]);

  bsElitePart(root, 'weaponArm', u.body, 5, 5, 0, [
    B(0,-5,0,2,5,2,dark),
    B(0,-9,1,0.9,12,0.9,'#73533a'),
    B(0,1,1,6,3,3,steel),
    B(-3,1,1,0.8,3,3.5,edge),
    B(3,1,1,0.8,3,3.5,edge)
  ]);

  return root;
}


// PLAGUE GARDENER:
// Hunched hooded creature carrying a spore basket and crooked staff.
function plagueGardenerMesh() {
  const root = bsEliteRoot('gardener');
  const u = root.userData.elite;
  const B = bsEliteBox;
  const cloth = '#435444';
  const bark = '#65513a';
  const rot = '#70e890';

  bsElitePart(root, 'body', u.rig, 0, 7, 0, [
    B(0,0,0,6,8,4,cloth),
    B(0,-3,0,8,4,5,'#303c35'),
    B(0,1,-3.5,7,7,3,bark),
    B(0,2,-5.2,7.5,0.7,0.6,'#99805a'),
    B(-2,7,-3.5,2.5,3,2.5,'#8b9952'),
    B(1,7,-3.8,3,4,3,'#5da365'),
    B(3,6,-3,2,3,2,'#b1ad65')
  ]);

  bsElitePart(root, 'head', u.body, 0, 8, 1, [
    B(0,0,0,5,5,4,cloth),
    B(0,0,2.1,3.4,3.5,0.5,'#202b25'),
    B(-0.9,2,2.5,0.6,0.6,0.3,rot),
    B(0.9,2,2.5,0.6,0.6,0.3,rot),
    B(0,-0.5,2.2,2,1,0.6,'#928c6a')
  ]);

  for (let i=0; i<2; i++) {
    const leg = bsElitePart(
      root, 'leg'+i, u.rig, i===0 ? -1.8 : 1.8, 7, 0, [
        B(0,-6,0,1.8,6,2,'#646c4f'),
        B(0,-7,1,2.2,1,3.5,'#373b2e')
      ]
    );
    u.legs.push(leg);
  }

  bsElitePart(root, 'plantArm', u.body, -3.8, 6, 0, [
    B(0,-5,0,1.8,5,2,cloth),
    B(0,-6,0.8,2,1.5,2,'#909674'),
    B(0,-6,2,2.4,2.4,2.4,rot)
  ]);

  bsElitePart(root, 'staffArm', u.body, 3.8, 6, 0, [
    B(0,-5,0,1.8,5,2,cloth),
    B(0,-12,1.5,0.8,18,0.8,bark),
    B(-1,5,1.5,3,0.8,0.8,bark),
    B(-2,3,1.5,0.8,3,0.8,bark),
    B(-2,2,1.5,1.8,1.8,1.8,rot)
  ]);

  bsEliteGlow(root, u.plantArm, rot, 0,-5,2,5);
  return root;
}


// STORM CHANNELER:
// Floating robed caster, forked crown and three orbiting crystals.
function stormChannelerMesh() {
  const root = bsEliteRoot('channeler');
  const u = root.userData.elite;
  const B = bsEliteBox;
  const blue = '#9ad0ff';
  const gold = '#ffe060';

  bsElitePart(root, 'body', u.rig, 0, 4, 0, [
    B(0,0,0,8,4,6,'#343c60'),
    B(0,4,0,6,8,4,'#46547a'),
    B(0,3,2.2,1,9,0.5,gold),
    B(-4,9,0,3,2,4,'#707d9b'),
    B(4,9,0,3,2,4,'#707d9b')
  ]);

  bsElitePart(root, 'head', u.body, 0, 12, 0, [
    B(0,0,0,4,4,4,'#303b5c'),
    B(0,1,2.1,3,1,0.3,blue),
    B(0,4,0,5,0.8,4,'#c9a24a'),
    B(-2,4.8,0,0.8,2.2,0.8,gold),
    B(2,4.8,0,0.8,2.2,0.8,gold),
    B(0,4.8,-1,0.8,1.4,0.8,gold)
  ]);

  for (let i=0; i<2; i++) {
    bsElitePart(
      root, i===0 ? 'leftArm' : 'rightArm',
      u.body, i===0 ? -4 : 4, 10, 0, [
        B(0,-5,0,2,5,2.5,'#46547a'),
        B(0,-6,0.5,1.7,1,1.7,blue)
      ]
    );
  }

  for (let i=0; i<3; i++) {
    const crystal = bsElitePart(
      root, 'crystal'+i, u.rig, 0,14,0, [
        B(0,-1.5,0,1.6,3,1.6,blue),
        B(0,1.5,0,0.8,1,0.8,gold),
        B(0,-2.5,0,0.8,1,0.8,gold)
      ]
    );
    u.orbit.push(crystal);
    bsEliteGlow(root, crystal, blue, 0,0,0,5);
  }

  return root;
}


// SOUL LANTERN:
