const UPG_BY=Object.fromEntries(UPG.map(u=>[u.id,u]));
// archer arrows carry the element the player trained; static field arcs from shocked foes
function arrowHooks(pr,p){pr.primaryArrow=true;if(p.lightArrows)stormProjectileArt(pr);if(p.iceArrows&&(!p.fireArrows||p.stance==='a_ice'))iceArrow(pr,p.iceArrows);else if(p.fireArrows)igniteArrow(pr,p.fireArrows);pr.onHit=e=>{if(p.fireArrows){status(e,'burn',(5+p.fireArrows*3)*p.dmg,2+p.fireArrows);skillFireImpact(e,pr.fireRank);}if(p.iceArrows){skillIceImpact(e,false);status(e,'chill',0,2+p.iceArrows);e.iceHits=(e.iceHits||0)+1;if(p.iceArrows>=3&&e.iceHits>=3){e.iceHits=0;status(e,'freeze',0,1.2);}}if(p.lightArrows)status(e,'shock',(p.lightArrows>=2?2:1)+(p.rm.shockStarter&&(e.shock||0)<4?1:0),3+p.lightArrows);if(p.static&&e.shock>0)chainFrom(e,pr.dmg*(p.static>=3?.6:.4),p.static,'#9ad0ff');};}
// dexxer knives: ricochet and marks
function knifeHooks(pr,p){if(p.ricochet)pr.bounce=p.ricochet;if(p.markThrow||p.rm.knifeBleed){const prev=pr.onHit;pr.onHit=e=>{if(prev)prev(e);if(p.markThrow)status(e,'mark',0,p.markThrow>=2?6:3);if(p.rm.knifeBleed)status(e,'bleed',3*p.dmg,3);};}}
function momentum(n){const p=G.p;if(!p.momOn)return;p.mom=Math.min(5,(p.mom||0)+n);p.momT=p.momDur||4;if(p.mom===5&&!p.momFull){p.momFull=1;G.texts.push({x:p.x,z:p.z,y:22,t:.6,t0:.6,s:'MOMENTUM',col:'#ffe060',big:1});}}
const CLOCKWORK_SPIDER_BLAST={damage:1.5,radius:1.25};
const TURRET_LIMIT=8;
function turretLimit(p=G&&G.p){return p&&p.stance==='k_clock'&&p.setB==='clockwork'?10:TURRET_LIMIT;}
// Brass Plating adds real deployment output; it does not bank charges.
function clockworkBonusSentry(rank){
 const p=G.p;
 // Check the actual array capacity so a bonus can never evict a live turret.
 if(p.stance!=='k_clock'||!p.rm.sentryExtra||G.sentries.length>=turretLimit())return false;
 const q=clockworkPlacement(null);
 placeSentry(q.x,q.z,(rank>=4?16:14)*p.repair,rank>=2?.35:.5,(8+rank*3)*p.dmg,null);
 itemCount('bonusSentries');return true;
}
function clockworkSpreadPlacement(x,z){
 // Spread the extra coverage without changing aim, range, or shot damage.
 // Test a fixed set of positions so placement consumes no extra random draws.
 const p=G.p,occupied=(a,b)=>G.sentries.some(s=>s.t>0&&Math.hypot(s.x-a,s.z-b)<18);
 if(!occupied(x,z))return {x,z};
 for(const radius of [22,40])for(let i=0;i<8;i++){
  const a=p.aim+Math.PI/2+i*Math.PI/4,q={x:x+Math.cos(a)*radius,z:z+Math.sin(a)*radius};
  keepInBounds(q,8);
  if(hAt(q.x,q.z)>=WATER_Y+2&&!occupied(q.x,q.z))return q;
 }
 return {x,z};
}

// At capacity, refresh the same type or rebalance an overrepresented type.
// A newly learned turret can join the lineup without erasing the last of another type.
function clockworkReplacementIndex(kind){
 const expired=G.sentries.findIndex(s=>s.t<=0);if(expired>=0)return expired;
 const key=s=>s.kind||'sentry',incoming=kind||'sentry',counts={};for(const s of G.sentries)counts[key(s)]=(counts[key(s)]||0)+1;
 const largest=Object.keys(counts).reduce((a,b)=>counts[b]>counts[a]?b:a),target=!(counts[incoming]>0)||counts[largest]>(counts[incoming]||0)+1?largest:incoming;
 let idx=-1;for(let i=0;i<G.sentries.length;i++)if(key(G.sentries[i])===target&&(idx<0||G.sentries[i].t<G.sentries[idx].t))idx=i;
 return Math.max(0,idx);
}
function regroupClockwork(){
 const p=G.p;if(p.stance!=='k_clock')return;
 if(p.mobileBastion){positionMobileBastion();return;}
 const live=G.sentries.filter(s=>s.t>0),n=live.length;
 live.forEach((s,i)=>{const a=i/Math.max(1,n)*TAU;let q;
  for(const r of [34,26,18,10]){q={x:p.x+Math.cos(a)*r,z:p.z+Math.sin(a)*r};keepInBounds(q,8);if(hAt(q.x,q.z)>WATER_Y+2)break;}
  if(hAt(q.x,q.z)<=WATER_Y+2)q={x:p.x,z:p.z};
  s.regroup={fromX:s.x,fromZ:s.z,x:q.x,z:q.z,age:0};s.machineScanAt=0;
 });
 G.clockworkRegroups=(G.clockworkRegroups||0)+1;
}
function tickClockworkRegroup(s,dt){
 if(!s.regroup)return;if(G.p.mobileBastion){delete s.regroup;return;}
 const q=s.regroup;q.age+=dt;const u=Math.min(1,q.age/.65),k=u*u*(3-2*u);
 s.x=q.fromX+(q.x-q.fromX)*k;s.z=q.fromZ+(q.z-q.fromZ)*k;keepInBounds(s,8);
 s.mesh.position.set(s.x,gAt(s.x,s.z),s.z);if(u>=1)delete s.regroup;
}
function reloadClockworkAtCapacity(kind,dmg,rate){
 const p=G.p;if(p.stance!=='k_clock'||G.sentries.length<turretLimit()||G.sentries.some(s=>s.t<=0))return null;
 const same=G.sentries.filter(s=>(s.kind||'sentry')===(kind||'sentry'));
 if(!same.length)return null; // Allow a newly learned role to enter the formation.
 const target=same.reduce((best,s)=>!best||(s.reloadShots||0)<(best.reloadShots||0)||(s.reloadShots||0)===(best.reloadShots||0)&&s.t>best.t?s:best,null);
 target.reloadShots=Math.min(3,(target.reloadShots||0)+3);
 target.dmg=Math.max(target.dmg,dmg);target.rate=Math.min(target.rate,rate*(RM('sentryRate')||1));
 G.clockworkReloads=(G.clockworkReloads||0)+1;itemCount('powerReloads');
 regroupClockwork();sfx('gear',{x:target.x,z:target.z});return target;
}
function placeSentry(x,z,t,rate,dmg,kind){if(G.p.stance==='k_clock')dmg*=.9;const reloaded=reloadClockworkAtCapacity(kind,dmg,rate);if(reloaded)return reloaded;if(G.p.stance==='k_clock'&&(IS_TOUCH||IS_MOBILE)){const q=clockworkPlacement(kind);x=q.x;z=q.z;}if(G.p.stance==='k_clock'&&G.p.rm.sentryExtra){const q=clockworkSpreadPlacement(x,z);x=q.x;z=q.z;}sfx('gear',{x,z});const p=G.p;if(Math.hypot(x-p.x,z-p.z)<8){const a=rnd(0,TAU);x=p.x+Math.cos(a)*13;z=p.z+Math.sin(a)*13;}while(G.sentries.length>=turretLimit()){const index=p.stance==='k_clock'?clockworkReplacementIndex(kind):0,old=G.sentries.splice(index,1)[0];if(old.mesh){disposeClockworkGait(old.mesh);scene.remove(old.mesh);}}const s={x,z,t,t0:t,cd:0,rate:rate*(RM('sentryRate')||1),dmg,kind};s.mesh=sentryMesh(kind);s.mesh.position.set(x,gAt(x,z),z);scene.add(s.mesh);G.sentries.push(s);regroupClockwork();return s;}

// Item synergy: explicit attack identities prevent secondary-trigger recursion.
function itemCount(key,n=1){if(!G)return;const q=G.itemMetrics||(G.itemMetrics={});q[key]=(q[key]||0)+n;}
function itemZoneAt(e,test){return G.zones.some(z=>z.t>0&&!z.hostile&&test(z)&&Math.hypot(e.x-z.x,e.z-z.z)<z.r+e.r*.5);}
function itemDamage(e,damage,ctx){
 const p=G.p,rm=p.rm||{};if(ctx&&ctx.secondary)return damage;
 const pr=ctx&&ctx.pr,kind=pr&&pr.itemCtx?pr.itemCtx.kind:ctx&&ctx.kind,info=pr&&pr.itemCtx||ctx||{};
 let factor=1;
 if(G.dotKind==='rot'&&e.pois>0&&rm.rotPoison){factor*=1+rm.rotPoison;itemCount('rotPoisonHits');}
 if(kind==='requiem'&&rm.requiemDiscord&&mobileSurgeActive(p)&&bardSleepAffected(e)&&e.weak>0){factor*=1+rm.requiemDiscord;itemCount('requiemDiscordHits');}
 if(kind==='echo'&&rm.resonantEcho&&e.reso>=8){factor*=1+rm.resonantEcho;itemCount('resonantEchoHits');}
 if((kind==='ball'||pr&&pr.kind==='ball')&&rm.ballFocus&&e.shock>=8){factor*=1.2;itemCount('chargedBallHits');}
 if(kind==='turret')factor*=info.mult||1;
 if(info.siege&&e.boss)factor*=.75;
 if((kind==='turret'||kind==='bastion')&&rm.spiderMark&&e.spiderMarkUntil>G.t){factor*=1+rm.spiderMark;itemCount(kind==='bastion'?'markedBastionHits':'markedTurretHits');}
 if(kind==='grenade'){
  if(rm.kegGroundGrenade&&itemZoneAt(e,z=>z.itemKegGround)){factor*=1+rm.kegGroundGrenade;itemCount('kegGroundGrenades');}
  if(rm.kegPrimer){e.kegPrimerUntil=G.t+4;itemCount('grenadePrimerHits');}
 }
 if(kind==='enhancedKeg'&&rm.kegPrimer&&e.kegPrimerUntil>G.t){factor*=1+rm.kegPrimer;e.kegPrimerUntil=0;itemCount('primedKegHits');}
 if(kind==='spider'&&rm.spiderMark){e.spiderMarkUntil=G.t+4;itemCount('spiderMarks');}
 if(pr){
  if(pr.trapperOpening&&!e.boss&&!e.def.elite&&!e.hunter&&!e.def.encounterObject){factor*=1.15;itemCount('trapperOpeningHits');}
  if(rm.iceChilled&&p.stance==='a_ice'&&(pr.primaryArrow||pr.kind==='icearrow'||pr.iceRank)&&(e.chill>0||e.frozen>0)){factor*=1+rm.iceChilled;itemCount('chilledArrowHits');}
  if(pr.boneOriginal&&pr.passedCage&&rm.cageSpear){factor*=1+rm.cageSpear;itemCount('cageSpearHits');}
  if(pr.ribShard&&e.bleed>0&&rm.ribBleed){factor*=1+rm.ribBleed;itemCount('bleedingShardHits');}
  if(pr.trapperPellet&&rm.caughtShot&&e.trapperBaitCatch&&e.trapperBaitCatch.until>G.t){factor*=1+rm.caughtShot;itemCount('caughtShotHits');}
  if(pr.primaryArrow){
   if(rm.tempestEarned&&p.ranks.tempest&&e.shock>=(rm.shockCap||8)&&G.t>=(p.itemTempestReady||0)){p.itemTempestReady=G.t+1;if(p.weapons.tempest)p.weapons.tempest.t=Math.max(0,p.weapons.tempest.t-.5);itemCount('tempestRefunds');}
   if(rm.cinderDragon&&p.ranks.dragonshot&&e.burn>0&&G.t>=(p.itemDragonReady||0)&&itemZoneAt(e,z=>z.oilAftermath)){p.itemDragonReady=G.t+1;if(p.weapons.dragonshot)p.weapons.dragonshot.t=Math.max(0,p.weapons.dragonshot.t-.5);itemCount('dragonRefunds');}
  }
 }
 return damage*factor;
}
function itemHitAfter(e,ctx,shattered,bonus){
 if(!shattered)return;const p=G.p;
 if(!p.rm.hoarfrostBurst||!p.ranks.shatter||!(bonus>0))return;
 const r=48*p.area;itemCount('hoarfrostBursts');
 for(const other of G.enemies)if(other!==e&&!other.dead&&Math.hypot(other.x-e.x,other.z-e.z)<r+other.r)hitEnemy(other,bonus*.25,0,0,true,false,false,false,{secondary:true});
 // Reuse the authored ice fracture art, with a bounded effect count.
 if(skillVfxVisible(e.x,e.z)){iceBurst(e.x,e.z,r*.65);sfx('shatter',{x:e.x,z:e.z});}
}
function aimedRibShards(dead){
 const p=G.p,n=4+p.ribShards*2+(p.rm.ribExtra||0),cage=G.zones.find(z=>z.bonePrison&&z.t>0);
 const targets=G.enemies.filter(e=>e!==dead&&!e.dead&&!e.phased&&!e.tavern&&!e.tavernRequired&&Math.hypot(e.x-dead.x,e.z-dead.z)<=180);
 const inside=e=>cage&&Math.hypot(e.x-cage.x,e.z-cage.z)<cage.r+e.r;
 targets.sort((a,b)=>(inside(b)?1:0)-(inside(a)?1:0)||Math.hypot(a.x-dead.x,a.z-dead.z)-Math.hypot(b.x-dead.x,b.z-dead.z));
 if(!targets.length)return;
 const preferred=targets.filter(inside),pool=preferred.length?preferred:targets;
 for(let i=0;i<n;i++){const t=pool[i%pool.length],d=Math.hypot(t.x-dead.x,t.z-dead.z),pr=boneDeathProjectile(shoot(dead.x,dead.z,t.x,t.z,220,(8+p.ribShards*4)*p.dmg,'bone',1,Math.max(.6,(d+24)/220)),dead);pr.ribShard=true;}
 itemCount('aimedRibShards',n);
}
function rearmCaughtTrap(e){
 const catchInfo=e.trapperBaitCatch,tr=catchInfo&&catchInfo.group;
 if(!G.p.rm.trapRearm||!tr||tr.rearmed||catchInfo.until<=G.t||!tr.baited||G.traps.includes(tr))return;
 tr.rearmed=1;tr.arm=.6;tr.baitUntil=G.t+12;delete tr.trapperChainAt;scene.add(tr.mesh);G.traps.push(tr);refreshTurkeyBait();itemCount('shotgunRearms');
 G.texts.push({x:tr.x,z:tr.z,y:9,t:.6,t0:.6,s:'re-armed',col:'#e2bd7b'});
}
function clockworkPlacement(kind){
 const p=G.p,target=machineTarget({x:p.x,z:p.z,kind});if(!target)return {x:p.x+Math.cos(p.aim)*14,z:p.z+Math.sin(p.aim)*14};
 const a=Math.atan2(target.z-p.z,target.x-p.x),d=Math.min(kind==='flame'?35:24,Math.max(12,Math.hypot(target.x-p.x,target.z-p.z)*.25)),out={x:p.x+Math.cos(a)*d,z:p.z+Math.sin(a)*d};keepInBounds(out,8);
 return hAt(out.x,out.z)<WATER_Y+2?{x:p.x,z:p.z}:out;
}
function deployStarterSentry(rank){const p=G.p,q=clockworkPlacement(null);placeSentry(q.x,q.z,(rank>=4?16:14)*p.repair,rank>=2?.35:.5,(8+rank*3)*p.dmg,null);clockworkBonusSentry(rank);itemCount('starterSentries');}
function turretFireInterval(s){const p=G.p;return s.rate/(1+(p.overclockT>0?1:0)+(p.rm.overdrive&&Math.hypot(s.x-p.x,s.z-p.z)<40?1:0));}
function turretAttackContext(s,target){
 const p=G.p;if(s.itemFocus===target)s.itemFocusCount=Math.min(4,(s.itemFocusCount||0)+1);else{s.itemFocus=target;s.itemFocusCount=0;}
 const focus=1+(p.rm.focusFire||0)*(s.itemFocusCount||0),over=1+(p.overclockT>0?(p.rm.gearOverclock||0)*(p.ranks.overclock||0):0);
 if(focus>1)itemCount('focusedTurretAttacks');if(over>1)itemCount('gearedOverclockAttacks');const siege=siegeTurretMultiplier(s);
 const mastery=s.kind==='flame'?(p.ranks.flameturret>=4?1.25:1):s.kind==='bolt'?(p.ranks.boltturret>=4?1.4:1):(p.ranks.sentry>=5?1.4:1);
 const close=p.rm.turretCloseDamage&&Math.hypot(target.x-p.x,target.z-p.z)<=80?1+p.rm.turretCloseDamage:1,reload=s.reloadShots>0?1.3:1;
 if(reload>1){s.reloadShots--;itemCount('powerReloadShots');}if(close>1)itemCount('brassCloseHits');
 return {kind:'turret',originX:s.x,originZ:s.z,mult:focus*over*siege*mastery*close*reload*(p.ranks.repair>=3?1.15:1),siege:siege>1};
}
function tagItemProjectile(pr,ctx){if(pr)pr.itemCtx=ctx;return pr;}
