 'Sharpened Femur':['spear','prison'],'Knuckle Dice':['ribshards'],'Rib Cage':['prison'],'Marrow Ring':['bonemarrow','prison'],'Spine of the Colossus':['lance','prison'],
 'Pitch Quiver':['firearrows','oilslick'],'Ash Gloves':['flamevolley'],'Cinder Band':['firearrows','dragonshot','oilslick'],'Wildfire Oil':['wildfire','oilslick'],"Dragon's Eye":['dragonshot'],
