 tamer:[{stanceId:'t_beast',name:'Beast Lord',icon:'cat',desc:()=>'Panthers, Pack Frenzy, Animal Bond, Pack Tactics. Fast, bleeding, marked prey.'},
        {stanceId:'t_guard',name:'Warden',icon:'bearpet',desc:()=>'Warden\'s Staff, Rally, Great Bear, War Boar, Guard Training, Veterinary, Protective Instinct, Last Guard. +25% pet health, +1 armor. You and the pack fight as one line.'},
        {stanceId:'t_myst',name:'Spirit Caller',icon:'drake',desc:()=>'Drake, Wisp, Frost Hound, Spirit Bond, Elemental Fangs, Call of the Wild. Fire, frost and lightning on four legs.'}],
