const BRIARFORD_TOUCH_DEVICE=navigator.maxTouchPoints>0||window.matchMedia('(pointer:coarse)').matches;
const BRIARFORD_PACING={gap:1.25,projectiles:2,ranged:3,summoner:1,trolls:3};
function mobileBriarfordPacing(){return MAP.id==='britannia'&&BRIARFORD_TOUCH_DEVICE;}
function briarfordAttackReady(e,move){
 if(e.boss)return true;
 const request=e.briarRequest||(e.briarRequest={order:G.briarRequestSerial=(G.briarRequestSerial||0)+1});
 request.move=move;request.seen=G.t;
 if(G.t<(G.briarSpecialAt||0))return false;
 if(G.enemies.some(o=>!o.dead&&o.boss&&(o.mv||o.chg)))return false;
 if(G.enemies.some(o=>!o.dead&&!o.boss&&(o.chg||o.mv&&o.mv.stage!=='recover')))return false;
 const live=G.projs.filter(pr=>pr.enemy&&pr.life>0&&!pr.showtimeOwner?.boss).length;
 const shots=move.id==='fan'?move.n:move.id==='orb'||move.id==='basicshot'?1:0;
 if(shots&&live+shots>BRIARFORD_PACING.projectiles)return false;
 if(move.id==='charge'&&live>0)return false;
 // An older charge request can wait for existing orbs to expire without a
 // stream of newly ready casters taking every opening ahead of it.
 for(const o of G.enemies){const q=o.briarRequest;
  if(o===e||o.dead||o.boss||!q||q.order>=request.order||G.t-q.seen>.6||o.stun>0||o.frozen>0||o.atkT>0||o.mv||o.chg||o.tavern||o.provoT>0)continue;
  if(Math.hypot(o.x-G.p.x,o.z-G.p.z)<=(q.move.range||260))return false;
 }
 return true;
}
function briarfordReserveAttack(e){if(e.boss)return;e.briarRequest=null;G.briarSpecialAt=G.t+BRIARFORD_PACING.gap;}

const GRAVE_PACING={specialGap:2.1,rangedGap:4.5,projectiles:3};
function graveAttackReady(e,move){
 if(mobileBriarfordPacing())return briarfordAttackReady(e,move);
 if(!['deceit','duskmoor'].includes(MAP.id)||e.boss)return true;
 // The Executioner owns a single readable attack window. Bosses always take priority.
 if(G.enemies.some(o=>!o.dead&&o!==e&&o.kind==='graveexecutioner'&&o.mv&&o.mv.stage!=='recover'))return false;
 if(e.kind==='graveexecutioner'&&(G.enemies.some(o=>!o.dead&&o!==e&&(o.boss||o.chg||o.mv&&o.mv.stage!=='recover'))||G.projs.some(pr=>pr.enemy&&pr.life>0)))return false;
 const request=e.graveRequest||(e.graveRequest={order:G.graveRequestSerial=(G.graveRequestSerial||0)+1});request.move=move;request.seen=G.t;
 if(G.t<(G.graveSpecialAt||0))return false;
 // Let the boss telegraph, strike, and recover without a fresh supporting volley.
 if(G.enemies.some(o=>!o.dead&&o.boss&&o.mv))return false;
 let active=0,reserved=0;
 for(const o of G.enemies){if(o.dead||o.boss)continue;
  if(o.chg||o.mv&&o.mv.stage!=='recover')active++;
  if(o.mv&&o.mv.stage==='tele'){const m=o.mv.def;reserved+=m.id==='fan'?m.n:m.id==='orb'?1:0;}
 }
 if(active>=2)return false;
 const live=G.projs.reduce((n,pr)=>n+(pr.enemy&&pr.life>0?1:0),0);
 const fits=m=>{const count=m.id==='fan'?m.n:m.id==='orb'?1:0;return !count||(G.t>=(G.graveRangedAt||0)&&live+reserved+count<=GRAVE_PACING.projectiles);};
 if(!fits(move))return false;
 // Oldest ready request goes first, so a pack of knights cannot monopolize the openings.
 for(const o of G.enemies){const q=o.graveRequest;if(o===e||o.dead||o.boss||!q||q.order>=request.order||G.t-q.seen>.5||o.stun>0||o.frozen>0||o.atkT>0||o.mv||o.chg||o.tavern||o.provoT>0)continue;
  if(o.kind==='graveexecutioner'&&(active>0||live>0||G.enemies.some(b=>!b.dead&&b.boss)))continue;
  if(Math.hypot(o.x-G.p.x,o.z-G.p.z)<=(q.move.range||260)&&fits(q.move))return false;
 }
 return true;
}
function graveReserveAttack(e,move){
 if(mobileBriarfordPacing()){briarfordReserveAttack(e);return;}
 if(!['deceit','duskmoor'].includes(MAP.id)||e.boss)return;
 e.graveRequest=null;G.graveSpecialAt=G.t+GRAVE_PACING.specialGap;
 if(move.id==='fan'||move.id==='orb')G.graveRangedAt=G.t+GRAVE_PACING.rangedGap;
}
