// instanced enemy meshes per kind
let ENEMY_MAX=IS_MOBILE?110:170;const EM={};
// All spawn sources share these live-enemy limits. Bosses retain their scheduled encounters.
const ENEMY_POPULATION={total:90,wave:70,roles:{ranged:6,summoner:2,charger:6,blinker:2,exploder:8},types:{lich:3,archer:4,bonemage:3,necromancer:2,wraith:2,deathshead:2,boneknight:18,mummy:20,gargoyle:20,daemon:18,myconid:18,corpser:8,rotpod:4,bombling:4,shade:6}};
function enemyPopulationRoles(def){const moves=def.moves||[],roles=[];
 if(def.ranged||def.caster||moves.some(m=>['fan','orb','beam','drain','hellfire','storm','meteors','pod','ring'].includes(m.id)))roles.push('ranged');
 if(def.summon||moves.some(m=>m.id==='brood'))roles.push('summoner');
 if(def.charge)roles.push('charger');if(def.blink)roles.push('blinker');if(def.explode)roles.push('exploder');if(def.elite)roles.push('elite');
 return roles;
}
function enemyPopulation(){const counts={total:0,kinds:{},roles:{}};
 for(const e of G.enemies){if(e.dead||e.boss||e.def.encounterObject)continue;counts.total++;counts.kinds[e.kind]=(counts.kinds[e.kind]||0)+1;
  for(const role of enemyPopulationRoles(e.def))counts.roles[role]=(counts.roles[role]||0)+1;
 }return counts;
}
function enemyPopulationLimit(){return Math.min(ENEMY_POPULATION.total,ENEMY_MAX);}
function ascLiveEliteCap(){const limit=Math.min(5,G.eliteCap||3);return G.tier>0&&MAP.id==='duskmoor'?Math.min(limit,G.t<210?3:G.t<420?4:5):limit;}
function enemyCanSpawn(kind,counts=enemyPopulation()){
 const def=kingsGraveEnemyDef(kind);if(!def)return false;if(def.boss||def.encounterObject)return true;
 if(counts.total>=enemyPopulationLimit())return false;
 if(kind==='graveexecutioner'&&(MAP.id!=='deceit'||G.t<270||!G.bossesSpawned.rotting||G.enemies.some(e=>!e.dead&&e.kind==='rotting')||G.t<(G.graveExecutionerAt||0)))return false;
 if(kind==='graveexecutioner'&&(counts.total+16>Math.min(ENEMY_POPULATION.wave,enemyPopulationLimit()-10)||(counts.kinds.graveguard||0)>19))return false;
 const roles=enemyPopulationRoles(def);
 if(MAP.id==='britannia'&&['daemon','myconid'].includes(kind)&&(counts.kinds.daemon||0)+(counts.kinds.myconid||0)>=(G.t<330?8:12))return false;
 if(MAP.id==='duskmoor'&&kind==='ghoul'&&G.t<90&&(counts.kinds.ghoul||0)>=3)return false;
 if(mobileBriarfordPacing()){
  if(kind==='troll'&&(counts.kinds.troll||0)>=BRIARFORD_PACING.trolls)return false;
  for(const role of ['ranged','summoner'])if(roles.includes(role)&&(counts.roles[role]||0)>=BRIARFORD_PACING[role])return false;
 }
 const typeLimit=(MAP.id==='deceit'&&kind==='graveguard'?(G.graveEscortSpawning?34:4):MAP.id==='deceit'&&kind==='ghoul'?6:0)||def.populationLimit||ENEMY_POPULATION.types[kind]||(def.solo?1:def.elite?2:roles.includes('summoner')?2:roles.includes('blinker')?2:roles.includes('ranged')?4:roles.includes('charger')?6:30);
 if((counts.kinds[kind]||0)>=typeLimit)return false;
 for(const role of roles){const cap=role==='elite'?ascLiveEliteCap():ENEMY_POPULATION.roles[role];if((counts.roles[role]||0)>=cap)return false;}
 return true;
}

// Fifteen shield skeletons arrive as one encounter, not as fifteen attack slots.
function graveEscortPositions(leader){
 const a=Math.atan2(G.p.z-leader.z,G.p.x-leader.x),cx=Math.cos(a),cz=Math.sin(a),spots=[];
 const slots=[];
 for(const front of [32,56,80])for(const side of [-56,-28,0,28,56])slots.push([front,side]);
 // Find extra legal spaces around terrain without moving an already spawned enemy.
 for(const front of [8,-16,-40,104,32,56,80])for(const side of [-84,84,-112,112,-56,-28,0,28,56])slots.push([front,side]);
 for(const [front,side] of slots){
  const q={x:leader.x+cx*front-cz*side,z:leader.z+cz*front+cx*side,noAffix:true};
  if(Math.hypot(q.x-G.p.x,q.z-G.p.z)<160||Math.hypot(q.x-leader.x,q.z-leader.z)<22||Math.hypot(q.x,q.z)>870)continue;
  if(keepInBounds(q,8)||hAt(q.x,q.z)<=WATER_Y+2||spots.some(o=>Math.hypot(o.x-q.x,o.z-q.z)<24))continue;
  if(G.enemies.some(e=>!e.dead&&e!==leader&&Math.hypot(e.x-q.x,e.z-q.z)<e.r+11))continue;
  const probe={x:leader.x,z:leader.z},d=Math.hypot(q.x-leader.x,q.z-leader.z);
  if(graveMoveBody(probe,q.x-leader.x,q.z-leader.z,8)<d*.95)continue;
  spots.push(q);if(spots.length===15)break;
 }
 return spots;
}
function spawnExecutionerEscort(leader,arrival){
 if(MAP.id!=='deceit'||!leader||leader.dead||leader.graveEscortCreated&&!arrival)return;
 const slots=arrival?.escortSlots||leader.graveEscortSlots||graveEscortPositions(leader);
 const counts=enemyPopulation(),cap=Math.min(ENEMY_POPULATION.wave,enemyPopulationLimit()-10);
 if(slots.length!==15||counts.total+15>cap||(counts.kinds.graveguard||0)>19)return;
 const previous=G.graveEscortSpawning;G.graveEscortSpawning=true;
 try{
  for(const q of slots){
   const guard=spawnEnemy('graveguard',q);
   if(guard){guard.graveEscort=leader;guard.graveArrivalUntil=G.t+1;guard.stun=Math.max(guard.stun,1);releaseCue('rise',{x:guard.x,z:guard.z,r:14});leader.graveEscortCreated=(leader.graveEscortCreated||0)+1;}
  }
 }finally{G.graveEscortSpawning=previous;}
}
function graveProcessionEntry(){
 if(MAP.id!=='deceit')return null;
 const p=G.p,travel=joy.active?Math.atan2(joy.dy,joy.dx):p.aim;
 for(let i=0;i<12;i++){
  const a=travel+rnd(-.55,.55),r=rnd(245,275),q={x:p.x+Math.cos(a)*r,z:p.z+Math.sin(a)*r,noAffix:true};
  if(Math.hypot(q.x,q.z)>850||hAt(q.x,q.z)<=WATER_Y+2||keepInBounds(q,8))continue;
  const probe={x:p.x,z:p.z};if(graveMoveBody(probe,q.x-p.x,q.z-p.z,8)<r*.9)continue;
  q.escortSlots=graveEscortPositions(q);if(q.escortSlots.length===15)return q;
 }
 return null;
}

function spawnWaveEnemy(pool){
 if(MAP.id==='deceit'&&G.t>=(G.graveArmyAt||0)){
  const leader=G.enemies.find(e=>!e.dead&&e.kind==='graveexecutioner'),c=enemyPopulation();
  if(leader&&c.total+15<=Math.min(ENEMY_POPULATION.wave,enemyPopulationLimit()-10)&&(c.kinds.graveguard||0)<=19){
   const entry=graveProcessionEntry();if(entry){const before=leader.graveEscortCreated||0;spawnExecutionerEscort(leader,entry);if(leader.graveEscortCreated-before===15){G.graveArmyAt=G.t+32;return leader;}}
  }
 }
 const counts=enemyPopulation();if(counts.total>=Math.min(ENEMY_POPULATION.wave,enemyPopulationLimit()-10))return null;
 const eligible=pool.filter(kind=>enemyCanSpawn(kind,counts));if(!eligible.length)return null;
 let kind=pick(eligible);if(ENEMY[kind].elite&&Math.random()<.45){const ordinary=eligible.filter(k=>!ENEMY[k].elite);if(ordinary.length)kind=pick(ordinary);}
 if(kind==='graveexecutioner'){
  const entry=graveProcessionEntry();
  if(!entry){const ordinary=eligible.filter(k=>k!=='graveexecutioner');return ordinary.length?spawnEnemy(pick(ordinary)):null;}
  const e=spawnEnemy(kind,entry);if(e){e.graveEscortSlots=entry.escortSlots;e.graveArrivalUntil=G.t+1;e.stun=Math.max(e.stun,1);releaseCue('rise',{x:e.x,z:e.z,r:18});spawnExecutionerEscort(e);G.graveArmyAt=G.t+32;}return e;
 }
 return spawnEnemy(kind);
}
