  for(const side of [-1,1]){
   const top=[0,-.28,.96],edge=[side*.59,-.25,.73],low=[side*.45,-.70,.68],chin=[0,-.79,.84];
   const color=side<0?[.36,.42,.45]:[.20,.26,.31];tri(top,edge,low,color);tri(top,low,chin,color);
   const back=[side*.74,-.13,.43],backLow=[side*.62,-.67,.43];tri(edge,back,backLow,color);tri(edge,backLow,low,color);
   tri([0,-.11,.98],[side*.62,-.08,.74],[side*.59,-.18,.73],[.42,.46,.47]);tri([0,-.11,.98],[side*.59,-.18,.73],[0,-.18,.96],[.42,.46,.47]);
  }
