  pos:V(),direction:V(),localQ:Q(),worldQ:Q(),frameQ:Q(),frameScale:V(),handQ:Q(),socketQ:Q(),inverseQ:Q(),rotation:Q(),euler:new T.Euler(),target:V(),handTarget:V(),pole:V(),shoulder:V(),elbow:V(),wrist:V(),axis:V(),side:V(),from:V(),to:V(),work:V(),parentQ:Q(),boneQ:Q(),scratchQ:Q(),localPole:V(),gripR:V(),gripL:V(),actual:V(),gripError:0,
