 r.basisX.crossVectors(r.to,r.hinge).normalize();r.basis.makeBasis(r.basisX,r.to,r.hinge);r.rotation.setFromRotationMatrix(r.basis);
 a.upper.parent.getWorldQuaternion(r.parentQ);a.upper.quaternion.copy(r.parentQ.invert().multiply(r.rotation));r.root.updateMatrixWorld(true);
