   if(phase){const h=f.h||24;d.position.y=h*.48;d.scale.set((2+Math.sin(k*Math.PI)*5)*(1-i*.18)*ink,h*.52*(1-i*.18),1);d.rotation.z=(i-1)*.16;}
   else if(summon){const r=(f.r||12)*(.6+i%2*.2);d.position.set(Math.cos(t)*r,-6+Math.sin(k*Math.PI)*8,Math.sin(t)*r);d.rotation.y=-t;d.rotation.z=.18;d.scale.setScalar((.5+i%3*.12)*ink);}
   else if(shade){const r=(f.r||22)*(.15+k*.85);d.position.set(Math.cos(t)*r,Math.sin(t)*r*.5+7+Math.sin(k*Math.PI)*4,front);d.rotation.z=t;d.scale.set((.7+k*.6)*ink,(1-k)*ink,1);}
   else if(requiem){d.position.set((i-1)*7,5+i*3+k*9,front);d.rotation.z=Math.sin(i+k*3)*.2;d.scale.setScalar((6+i)*ink);}
