function tinkerSurfaceMaterial(original,name,id){
 const m=plagueSurfaceMaterial({vertexColors:!!original.vertexColors},'regalia');
 m.map=original.map||null;m.skinning=!!original.skinning;
 const base=m.onBeforeCompile;
 m.onBeforeCompile=shader=>{
  base(shader);
  if(name==='gun'){shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#include <map_fragment>
float warmth=smoothstep(.04,.20,diffuseColor.r-diffuseColor.b);float v=max(diffuseColor.r,max(diffuseColor.g,diffuseColor.b));diffuseColor.rgb=mix(mix(vec3(.025,.04,.04),vec3(.27,.35,.33),v),mix(vec3(.07,.038,.018),vec3(.48,.27,.085),v),warmth);`);}else if(/Engineer_/.test(name)){
   const coat=id==='k_trap'?'vec3(.19,.25,.12)':id==='k_bomb'?'vec3(.33,.075,.048)':'vec3(.065,.16,.20)';
   const code=/Head/.test(name)?'diffuseColor.rgb=mix(diffuseColor.rgb,diffuseColor.rgb*vec3(.69,.61,.49),.45);':
    /Leg/.test(name)?'diffuseColor.rgb=mix(vec3(.025,.031,.029),vec3(.15,.17,.14),value);':
    `vec3 uniformColor=mix(vec3(.022,.026,.022),${coat},value);float skin=smoothstep(.12,.30,texelPaint.r-texelPaint.b);diffuseColor.rgb=mix(uniformColor,texelPaint*vec3(.83,.75,.61),skin);`;
   shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#include <map_fragment>\nvec3 texelPaint=diffuseColor.rgb;float value=smoothstep(.01,.82,max(texelPaint.r,max(texelPaint.g,texelPaint.b)));${code}`);
  }
 };
 m.customProgramCacheKey=()=> 'tinker-cel-v1-'+id+'-'+name;return m;
}
