 for(const name of ['hips','spine','chest'])p.mesh.getObjectByName(name).quaternion.copy(r.holdRest[name]);
 const age=G.t-(p.bardStrumAt??-99),active=age>=0&&age<.46,fade=active?Math.sin(Math.PI*age/.46):0,stroke=active?Math.sin(age/.46*Math.PI*3)*fade:0;
