 for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2];let mask=kind==='fire'?clamp((r-Math.max(g,b)*1.05-20)/110,0,1):kind==='plague'?clamp((g-Math.max(r,b)*1.3-20)/100,0,1):kind==='bone'?clamp((b-g*1.2-25)/100,0,1):clamp((Math.min(g,b)-r*1.3-25)/100,0,1);d[i]=r*mask;d[i+1]=g*mask;d[i+2]=b*mask;}
