    const at=s=>{const f=s/12*2,k=Math.min(1,Math.floor(f)),v=pts[k].clone().lerp(pts[k+1],f-k);v.x+=Math.sin(s*6.7+tick*2.3)*.035;v.z+=.025;return v;};
