// the feet keep stepping, including retreating and strafing under auto-aim.
function restoreHeroLocomotion(p){const r=p.mesh.userData.locomotion;if(!r||!r.saved)return;for(const s of r.saved){s.node.position.copy(s.p);s.node.quaternion.copy(s.q);}r.saved=null;}
function updateHeroLocomotion(p){
 const u=p.mesh.userData,dt=Math.min(.05,Math.max(0,G.dt||0));let r=u.locomotion;
 if(!r){const clip=u.act.Running_A&&u.act.Running_A.getClip(),idle=u.act.Idle&&u.act.Idle.getClip();if(!clip||!idle)return;
  const nodes=[];for(const name of ['hips','spine','chest','upperlegl','lowerlegl','footl','toesl','upperlegr','lowerlegr','footr','toesr']){const node=p.mesh.getObjectByName(name);if(node)nodes.push({node,p:node.position.clone(),q:node.quaternion.clone()});}
  const tracks=[];for(const track of clip.tracks){const [name,prop]=track.name.split('.');if(!/^(upperleg|lowerleg|foot|toes)[lr]$/.test(name)&&!(name==='hips'&&prop==='position'))continue;if(prop!=='position'&&prop!=='quaternion')continue;const node=p.mesh.getObjectByName(name),stand=idle.tracks.find(t=>t.name===track.name);if(node&&stand)tracks.push({node,prop,run:track.createInterpolant(),idle:stand.createInterpolant()});}
  r=u.locomotion={nodes,tracks,x:p.x,z:p.z,phase:0,weight:0,turn:0,duration:clip.duration,q:new T.Quaternion(),q2:new T.Quaternion(),chestQ:new T.Quaternion(),axis:new T.Vector3(),parentQ:new T.Quaternion(),v:new T.Vector3(),v2:new T.Vector3(),saved:null};
 }
 const dx=p.x-r.x,dz=p.z-r.z,d=Math.hypot(dx,dz);r.x=p.x;r.z=p.z;
 const special=p.dying||p.dash>0||p.leap>0||p.landT>0||p.whirl||p.halCharge||p.shieldPush||p.shieldShoveUntil>G.t||p.mobileBastion||p.showtime||p.poly>0;
 if(special||!dt||G.state!=='play'){r.weight=0;r.turn=0;return;}
 const travelling=d>.015&&d<12&&p.moving,velocity=travelling?d/dt:0;
 r.weight+=(travelling?1-r.weight:-r.weight)*Math.min(1,dt*18);
 if(!travelling&&r.weight<.001){r.weight=0;r.turn=0;return;}
 // One full cycle per 30 world units; no phase advance while pressed into a wall.
 let angle=travelling?Math.atan2(dx,dz)-p.mesh.rotation.y:r.turn;angle=Math.atan2(Math.sin(angle),Math.cos(angle));
 const reverse=u.archerBody?(r.reverse?Math.abs(angle)>1.30:Math.abs(angle)>1.85):Math.abs(angle)>Math.PI/2;if(reverse)angle=Math.atan2(Math.sin(angle+Math.PI),Math.cos(angle+Math.PI));
 angle=clamp(angle,-1.15,1.15);r.turn+=u.archerBody?clamp(angle-r.turn,-3.5*dt,3.5*dt):(angle-r.turn)*Math.min(1,dt*12);
 if(travelling)r.phase=(r.phase+(reverse?-1:1)*d/30+1)%1;
 r.saved=r.nodes;for(const s of r.nodes){s.p.copy(s.node.position);s.q.copy(s.node.quaternion);}
 for(const t of r.tracks){const run=t.run.evaluate(r.phase*r.duration),idle=t.idle.evaluate(0);if(t.prop==='quaternion'){r.q.fromArray(idle);r.q2.fromArray(run);t.node.quaternion.copy(r.q).slerp(r.q2,r.weight);}else{r.v.fromArray(idle);t.node.position.copy(r.v).lerp(r.v2.fromArray(run),r.weight);}}
 // Turn the pelvis toward the step, then counter-rotate the chest so aiming,
 // weapon grips and bard instrument poses remain stable.
 const hips=p.mesh.getObjectByName('hips'),chest=p.mesh.getObjectByName('chest');
 if(hips&&chest){p.mesh.updateMatrixWorld(true);chest.getWorldQuaternion(r.chestQ);p.mesh.getWorldQuaternion(r.q);r.axis.set(0,1,0).applyQuaternion(r.q);hips.parent.getWorldQuaternion(r.parentQ);r.axis.applyQuaternion(r.parentQ.invert());r.q.setFromAxisAngle(r.axis,r.turn*r.weight);hips.quaternion.premultiply(r.q);p.mesh.updateMatrixWorld(true);chest.parent.getWorldQuaternion(r.parentQ);chest.quaternion.copy(r.parentQ.invert()).multiply(r.chestQ);}
 r.velocity=velocity;r.reverse=reverse;
}

