 if(IS_TOUCH){p.area*=1.25;p.magnet*=1.3;}
 if(p.stance==='sb'){p.dr=Math.max(p.dr||0,.05);}else if(p.stance==='gs'){p.dmg*=1.2*.8;p.armor-=1;}else if(p.stance==='hal'){p.area*=1.1;p.armor+=1;}else if(p.stance==='d_duel'){p.dmg*=1.15;p.spdMul*=1.1;}else if(p.stance==='t_guard'){p.petHp*=1.25;p.armor+=1;}else if(p.stance==='n_bone'){p.hpMul*=1.15;}
 for(const id in p.ranks){const u=UPG_BY[id];if(u.passive)u.apply(p,p.ranks[id]);}
 p.setB=activeSet(p.cls);for(const it of RELICS)if(it.cls===p.cls&&wornRelic(it.id)&&it.apply)it.apply(p);modsApply(p);
 if(p.setB!=='reaver')p.reaverCharge=0;if(p.setB!=='snare')p.breachCount=0;
 if(p.altar&&p.altarT>0)p.altar.apply(p);
 // Small build-specific damage trim; includes attacks, thorns, turrets and spiders.
