function spawnAltars(){const a0=rnd(0,TAU);for(let i=0;i<2;i++){let x,z;for(let k=0;k<12;k++){const a=a0+i*Math.PI+rnd(-.6,.6),r=rnd(260,620);x=Math.cos(a)*r;z=Math.sin(a)*r;if(!MAP.dungeon&&roadAt(x,z)<.04)continue;break;}const m=new T.Group();const base=new T.Mesh(altarGeo,MAT);base.castShadow=true;m.add(base);const buff=ALTAR_BUFFS[Math.floor(Math.random()*ALTAR_BUFFS.length)];const rune=decal('rune',buff.col,false);rune.scale.set(26,1,26);rune.position.y=.5;m.add(rune);const glow=new T.Sprite(new T.SpriteMaterial({map:glowTex(),color:buff.col,transparent:true,opacity:.7,depthWrite:false,blending:T.AdditiveBlending}));glow.scale.setScalar(26);glow.position.y=14;m.add(glow);m.position.set(x,gAt(x,z),z);scene.add(m);G.altars.push({x,z,m,rune,glow,buff,used:false});DECOR.push({x,z,r:9});}buildDecorGrid();}
