// Plasma and committed boss attacks. All distances are presentation-only.
const PLASMA={clock:{value:0}};
function plasmaAssets(){
 const A=PLASMA;if(A.sphere)return A;
 A.sphere=new T.SphereGeometry(1,24,16);A.plane=new T.PlaneGeometry(1,1);
 A.shell=new T.ShaderMaterial({uniforms:{clock:A.clock},transparent:true,depthWrite:false,side:T.FrontSide,
 vertexShader:`varying vec3 p;varying vec3 n;varying vec3 eye;void main(){p=position;n=normalize(normalMatrix*normal);vec4 mv=modelViewMatrix*vec4(position,1.);eye=normalize(-mv.xyz);gl_Position=projectionMatrix*mv;}`,
 fragmentShader:`varying vec3 p;varying vec3 n;varying vec3 eye;uniform float clock;
 float hash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}
 float noise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
 void main(){float t=clock;vec3 q=p*4.+vec3(t*.24,-t*.8,t*.35);float flow=noise(q)*.65+noise(q*2.4)*.35;float vein=pow(max(0.,1.-abs(flow-.5)*18.),5.);float rim=pow(1.-abs(dot(normalize(n),normalize(eye))),2.4);float inner=pow(max(0.,dot(normalize(n),normalize(eye))),9.);vec3 col=vec3(.015,.065,.23)+vec3(.03,.17,.48)*flow+vec3(.22,.65,1.)*rim+vec3(.34,.7,1.)*vein+vec3(.3,.7,1.)*inner*.35;gl_FragColor=vec4(col,.72+rim*.23);}`});
 A.arcMat=new T.MeshBasicMaterial({color:'#c5f7ff',transparent:true,opacity:.95,depthWrite:false,side:T.DoubleSide});
 A.haloMat=new T.SpriteMaterial({map:glowTex(),color:'#3d8af6',transparent:true,opacity:.32,depthWrite:false,blending:T.AdditiveBlending});
 A.sparkMat=new T.MeshBasicMaterial({map:glowTex(),color:'#a6e8ff',transparent:true,opacity:.8,depthWrite:false,blending:T.AdditiveBlending});
 return A;
}
function plasmaOrb(pr,g){
 const A=plasmaAssets();g.userData.plasmaOwned=true;
 if(!A.coreMat)A.coreMat=new T.MeshBasicMaterial({color:'#b9edff'});
 const shell=new T.Mesh(A.sphere,A.coreMat);shell.scale.setScalar(2.5);g.add(shell);
 const halo=new T.Sprite(A.haloMat);halo.scale.setScalar(26);g.add(halo);
 const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(new Float32Array(12*20*6*3),3).setUsage(T.DynamicDrawUsage));
 const arcs=new T.Mesh(geo,A.arcMat);arcs.frustumCulled=false;arcs.userData.plasmaOwnGeo=true;g.add(arcs);
 const sparks=new T.InstancedMesh(A.plane,A.sparkMat,12);sparks.frustumCulled=false;g.add(sparks);
 return {ball:true,shell,halo,arcs,sparks,seed:Math.random()*13,frame:-1,previous:new T.Vector3(),q:new T.Quaternion(),v:new T.Vector3(),w:new T.Vector3(),normal:new T.Vector3(),side:new T.Vector3()};
}
function animatePlasma(pr){
 const a=pr.stormArt,t=G.t,A=plasmaAssets();A.clock.value=t;
 a.shell.rotation.y=t*.28;a.shell.scale.setScalar(2.5*(1+Math.sin(t*8+a.seed)*.035));
 a.halo.scale.setScalar(20+Math.sin(t*6));const frame=Math.floor(t*16);
 if(frame!==a.frame){a.frame=frame;const p=a.arcs.geometry.attributes.position;let v=0;
  for(let j=0;j<12;j++){
   const az=j*2.399+Math.sin(frame*.37+j)*.24,tilt=j*.91+a.seed,span=j<8?2.3:.9,start=frame*.19+j;
   for(let i=0;i<=20;i++){
    const u=i/20,theta=start+u*span,r=(j<8?6.8:7+u*4.5)+Math.sin(i*17+j*9+frame*2)*.36;
    const yy=Math.sin(theta)*r,xx=Math.cos(theta)*r;
    a.v.set(xx*Math.cos(az)+yy*Math.sin(tilt)*Math.sin(az),yy*Math.cos(tilt),xx*Math.sin(az)-yy*Math.sin(tilt)*Math.cos(az));
    if(i){a.side.crossVectors(a.v,a.previous).normalize().multiplyScalar(j<8?.12:.075);const b=a.previous,c=a.v,s=a.side;for(const P of [[b.x-s.x,b.y-s.y,b.z-s.z],[b.x+s.x,b.y+s.y,b.z+s.z],[c.x+s.x,c.y+s.y,c.z+s.z],[b.x-s.x,b.y-s.y,b.z-s.z],[c.x+s.x,c.y+s.y,c.z+s.z],[c.x-s.x,c.y-s.y,c.z-s.z]])p.setXYZ(v++,...P);}
    a.previous.copy(a.v);
   }
  }p.needsUpdate=true;
 }
 pr.mesh.getWorldQuaternion(a.q).invert();a.q.multiply(camera.quaternion);
 for(let i=0;i<12;i++){const u=(t*.6+i*.618)%1,ang=i*2.4+t*.7,r=7+u*7;MAGE_TMP.position.set(Math.cos(ang)*r,Math.sin(ang*1.7)*r*.65,Math.sin(ang)*r);MAGE_TMP.quaternion.copy(a.q);MAGE_TMP.scale.setScalar((1-u)*1.8);MAGE_TMP.updateMatrix();a.sparks.setMatrixAt(i,MAGE_TMP.matrix);}a.sparks.instanceMatrix.needsUpdate=true;
}
function actionGroup(f){const g=new T.Group();g.userData.legacyOwned=true;f.mesh=g;scene.add(g);return g;}
function actionMesh(g,geo,mat){const m=new T.Mesh(geo,mat);m.userData.legacyOwnGeo=true;g.add(m);return m;}
