   for(let i=0;i<5;i++){const a=-.75+i*.375;const rail=actionMesh(g,new T.BoxGeometry(.5,e.h*e.sc*.68,.6),actionMat('#c7dce3',.65));rail.position.set(Math.cos(a)*r,e.h*e.sc*.36+2,Math.sin(a)*r);}
