function combatTargetable(e){return !!(e&&!e.dead&&!e.phased&&!e.tavern&&!e.tavernRequired);}
function nearest(x,z,n,maxd){const arr=[];for(const e of G.enemies){const d=Math.hypot(e.x-x,e.z-z);if(combatTargetable(e)&&d<maxd)arr.push({e,d:COMMAND_CAST?Math.hypot(e.x-COMMAND_CAST.x,e.z-COMMAND_CAST.z):d});}arr.sort((a,b)=>a.d-b.d);return arr.slice(0,n).map(a=>a.e);}
function densest(x,z,maxd){const soul=stolenSoulTarget(x,z,maxd);if(soul)return soul;if(COMMAND_CAST)return nearest(x,z,1,maxd)[0];let best=null,bs=0;const cand=nearest(x,z,12,maxd);for(const c of cand){let s=0;for(const e of G.enemies)if(combatTargetable(e)&&Math.hypot(e.x-c.x,e.z-c.z)<40)s++;if(s>bs){bs=s;best=c;}}return best;}
// a melee strike: sector of radius rng, width wide, centred on angle ang (XZ plane). The visual is the same sector.
function slash(x,z,ang,rng,dmg,kb,noText,wide,sonic,itemCtx){if(!sonic&&(!VISUAL_CAST||!UPG_BY[VISUAL_CAST.id]||UPG_BY[VISUAL_CAST.id].cls!=='bard'))sfx(VISUAL_CAST?skillSound(VISUAL_CAST.id):'blade',{x,z,force:true});wide=wide||1.7;for(const e of G.enemies){const dx=e.x-x,dz=e.z-z,d=Math.hypot(dx,dz);if(d>rng+e.r)continue;const a=angDiff(Math.atan2(dz,dx),ang);if(Math.abs(a)<wide/2)hitEnemy(e,dmg,dx/(d||1)*kb*12,dz/(d||1)*kb*12,noText,false,false,false,itemCtx);}hitTrees(x,z,rng,ang,wide);fx(sonic?'v2_sonicArc':'slash',{x,z,a:ang,r:rng,w:wide,dur:.28});}
function explode(x,z,r,dmg,o){SFX.area++;try{return explodeCore(x,z,r,dmg,o);}finally{SFX.area--;}}
