function spawnEnemy(kind,pos){const def=kingsGraveEnemyDef(kind);if(!def||(!def.boss&&!enemyCanSpawn(kind)))return null;let x,z;if(pos){x=pos.x;z=pos.z;}else{const R=(MAP.dungeon?rnd(250,300):rnd(200,240))*(hasMod('fog')?.7:1);for(let k=0;k<8;k++){const ang=rnd(0,TAU);x=G.p.x+Math.cos(ang)*R;z=G.p.z+Math.sin(ang)*R;if(Math.hypot(x,z)<880)break;}const rr=Math.hypot(x,z);if(rr>880){x*=880/rr;z*=880/rr;}if(Math.hypot(x-G.p.x,z-G.p.z)<120){const a=Math.atan2(G.p.z,G.p.x)+Math.PI+rnd(-1,1);x=G.p.x+Math.cos(a)*R;z=G.p.z+Math.sin(a)*R;}if(MAP.dungeon&&combatVisible(x,z,30))fx('ring',{x,z,r:14,dur:.5,col:'#8060a0'});}const hpMul=(def.boss?1+G.t/600:def.elite?1+G.t/300:def.pod?1:1+G.t/MAP.hpT)*(G.tierHp||1)*(!def.boss&&!def.pod?(MAP.mobHp||1):def.boss?(MAP.bossHp||1):1)*(MAP.encounterHp||1)*(MAP.id==='deceit'&&!def.boss&&!def.elite&&!def.pod&&!def.encounterObject?1.1:1)*(def.boss?(BOSS_HEALTH_TUNING[MAP.id]?.[kind]||1):1);
 const e={def,kind,x,z,hp:Math.round(def.hp*hpMul),maxhp:Math.round(def.hp*hpMul),r:def.r,h:def.h,sc:1,yaw:0,spd:def.spd*rnd(.9,1.1)*(IS_TOUCH&&!def.boss?.9:1),kx:0,kz:0,flash:0,slow:0,root:0,vuln:0,pois:0,poisDps:0,hitCd:0,boss:!!def.boss,dead:false,wob:rnd(0,6),hitT:0,atkT:0,hop:rnd(0,6),stun:0,weak:0,weakMul:1,provoT:0,burn:0,burnDps:0,detour:0,detourS:1,bleed:0,bleedDps:0,chill:0,frozen:0,shock:0,shockT:0,mark:0,reso:0,resoT:0,petHitT:0,rot:0,rotDps:0,fear:0,rcd:rnd(1,2.5),bcd:3,ccd:rnd(2,4),scd:4,zcd:3,chg:null,gen:0};spawnEnemyMesh(e);G.enemies.push(e);if(kind==='graveexecutioner')G.graveExecutionerAt=G.t+32;if(def.noAffix||pos&&pos.noAffix)e.noAffix=1;else rollAffix(e);return e;}
