function addPickup(x,z,kind,v){const k={x,z,kind,v:v||0,bob:rnd(0,6),rot:rnd(0,TAU),gy:gAt(x,z)};if(kind!=='coin'){k.mesh=kind==='magnet'?new T.Mesh(magnetGeo,MAT):new T.Mesh(potionGeo,MAT);if(kind==='magnet')outlineClone(k.mesh);k.mesh.position.set(x,gAt(x,z)+1,z);scene.add(k.mesh);}G.pickups.push(k);}
const COIN_IM={};const COIN_CAP=700;
