function legacyProjectile(kind){const A=legacyArt();if(!A.boneMat){A.boneMat=new T.MeshLambertMaterial({color:'#e1d7bd'});A.noteMat=new T.SpriteMaterial({color:'#efcc83',map:A.note,transparent:true,opacity:.95,depthWrite:false});A.shaft=new T.CylinderGeometry(.65,.95,11,5);A.shaft.rotateZ(-Math.PI/2);}const g=new T.Group();if(kind==='dagger'){if(!A.steelMat){A.steelMat=new T.MeshLambertMaterial({color:'#c6d4db'});A.hiltMat=new T.MeshLambertMaterial({color:'#88704b'});A.hilt=new T.BoxGeometry(3,1,1.4);}const blade=new T.Mesh(A.tip,A.steelMat);blade.scale.set(8,.7,2);blade.position.x=2;const hilt=new T.Mesh(A.hilt,A.hiltMat);hilt.position.x=-3.5;g.add(blade,hilt);return g;}if(kind==='bone'){const shaft=new T.Mesh(A.shaft,A.boneMat);g.add(shaft);const tip=new T.Mesh(A.tip,A.boneMat);tip.scale.set(6,2,2);tip.position.x=7;g.add(tip);for(let i=0;i<2;i++){const barb=new T.Mesh(A.tip,A.boneMat);barb.scale.set(3,1.3,1.3);barb.rotation.z=(i?1:-1)*.65;barb.position.set(-2,0,(i?1:-1)*.8);g.add(barb);}}else{const note=new T.Sprite(A.noteMat);note.scale.set(9,9,1);g.add(note);}return g;}

