 for(let band=0;band<3;band++){const base=pos.length/3;for(let i=0;i<=segments;i++)for(let j=0;j<=rows;j++){pos.push(0,0,0);uv.push(i/segments,j/rows);bands.push(band);}for(let i=0;i<segments;i++)for(let j=0;j<rows;j++){const a=base+i*(rows+1)+j,b=a+rows+1;idx.push(a,b,a+1,b,b+1,a+1);}}
