 if(p.dying||(p.dash>0&&!p.showtime)){r.performanceWeight=0;r.performanceWindup=0;r.lute.position.set(.29,.14,.35);r.lute.rotation.set(0,0,-1.05);return;}
 const a=p.showtime||((p.mesh.userData.sonicBody||(p.mesh.userData.kaykitBard&&p.mesh.userData.kaykitBard.enabled))?p.mobileFinale:null);if(a){r.showEnd=a.until;r.lastShowAt=G.t;}
