 const strength=a?Math.min(1,(G.t-a.start)/.18,(a.until-G.t)/.22):release;
 const beat=a?a.beat:bardPerformanceBeat(),time=a?G.t-a.start:G.t-(r.showEnd||G.t),phase=time/beat*TAU;
 const sway=Math.sin(phase*.5),nod=Math.sin(phase-.5),accent=Math.exp(-Math.max(0,G.t-(p.showtimePulseAt||-99))*13);
 // A planted, screen-facing performance stays upright even while controls move the hero.
 const beatPhase=((time/beat)%1+1)%1,windup=beatPhase>.58?Math.pow(Math.sin((beatPhase-.58)/.42*Math.PI),2):0;
 const planted=!!p.showtime||!p.moving;r.performanceWeight=strength;r.performanceWindup=windup;
 // Add a beat-driven upper-body performance over locomotion. Restore before the next mixer tick.
 for(const b of r.poseBones){b.q.copy(b.bone.quaternion);b.pos.copy(b.bone.position);b.saved=true;if(strength<=0)continue;
  if(b.name==='hips'){b.bone.rotation.z+=sway*.045*strength;if(planted)b.bone.position.y-=Math.pow(Math.sin(phase*.5),2)*.025*strength;}
  if(b.name==='spine'){b.bone.rotation.y+=sway*.12*strength;b.bone.rotation.x+=(.05+accent*.07)*strength;}
  if(b.name==='chest'){b.bone.rotation.z+=sway*.08*strength;b.bone.rotation.x+=nod*.065*strength;}
  if(b.name==='head'){b.bone.rotation.x+=(nod*.16-accent*.09-.12)*strength;b.bone.rotation.y-=sway*.10*strength;}
  if(planted&&b.name==='upperlegl')b.bone.rotation.z+=.12*strength;
  if(planted&&b.name==='upperlegr')b.bone.rotation.z-=.12*strength;
  if(planted&&b.name==='lowerlegr')b.bone.rotation.x+=Math.max(0,nod)*.15*strength;
 }
