function updateFrostRain(f){
 // Process launch/landing events in time order, including frames spanning several waves.
 // Each wave snapshots the live aim on launch; its arrows and damage share that target.
 while(true){const launch=f.launched<(f.waves||5)?f.launched*.2:Infinity,land=f.wave<(f.waves||5)?.24+f.wave*.2:Infinity;
  const next=Math.min(launch,land);if(!Number.isFinite(next)||f.t+1e-8<next)break;
  if(launch<land){const target=frostRainTarget();f.targets.push(target);f.launched++;f.x=target.x;f.z=target.z;continue;}
  const target=f.targets[f.wave++];hitTrees(target.x,target.z,f.r);for(const e of G.enemies){if(e.dead||Math.hypot(e.x-target.x,e.z-target.z)>f.r+e.r)continue;status(e,'chill',.35,2);materialHit('icehit',e,f.dmg/3,0,0,true);}
  fx('shock',{x:target.x,z:target.z,r:f.r,col:'#6194ac',dur:.22,softIce:true});iceEmit(target.x,gAt(target.x,target.z)+3,target.z,(IS_TOUCH||IS_MOBILE)?3:6,ICE_VFX.trail);sfx('shatter',{x:target.x,z:target.z});
 }
}
