// Prepare Fire Archer's existing art before combat. Retain a bounded set of
// material owners so removing the only oil pool cannot evict its shader programs.
let FIRE_ART_WARM=null;
function warmFireArt(){
 if(FIRE_ART_WARM||!G||G.p.stance!=='a_fire')return;
 const keep={roots:[]},random=Math.random;let seed=47219;
 Math.random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 try{
  const x=G.p.x,z=G.p.z,oil={x,z,r:72,t:8,kind:'oil',mesh:new T.Group()};
  oil.mesh.position.set(x,gAt(x,z)+.4,z);oil.mesh.scale.set(72,1,72);makeLiquidPool(oil,true,false);scene.add(oil.mesh);keep.roots.push(oil.mesh);
  const ground={x,z,r:72,t:4,kind:'fire',scorchPoolSeed:oil.poolSeed,mesh:new T.Group()};
  ground.mesh.position.copy(oil.mesh.position);ground.mesh.scale.copy(oil.mesh.scale);
  for(let i=0;i<2;i++)ground.mesh.add(decal('flame','#ff7a10',true));
  decorateScorchedEarth(ground);decorateOilAftermath(ground);scene.add(ground.mesh);keep.roots.push(ground.mesh);
  const burst={x,z,r:86.4,rank:4,dur:.9};renderOilBurst(burst,.2);keep.roots.push(burst.mesh);
  renderer.compile(scene,camera);
  const textures=new Set();for(const root of keep.roots)root.traverse(o=>{for(const m of o.material?(Array.isArray(o.material)?o.material:[o.material]):[])for(const key of ['map','alphaMap','normalMap','emissiveMap'])if(m[key])textures.add(m[key]);});
  for(const v of SCORCHED_ART.variants){textures.add(v.base);textures.add(v.seams);}
  if(renderer.initTexture)for(const t of textures)renderer.initTexture(t);
  // Some mobile drivers finalize a shader only on its first draw. Exercise it
  // offscreen now, before the first oil cast or ignition during combat.
  const previous=renderer.getRenderTarget(),target=new T.WebGLRenderTarget(64,64);
  try{renderer.setRenderTarget(target);renderer.render(scene,camera);renderer.getContext().finish();}
  finally{renderer.setRenderTarget(previous);target.dispose();}
  FIRE_ART_WARM=keep;
 }finally{
  Math.random=random;
  for(const root of keep.roots)scene.remove(root);
 }
}

