   for(let k=0;k<corners.length;k++){const a=corners[k],b=corners[(k+1)%corners.length];edge.push(a);for(let j=1;j<4;j++){const t=j/4,inset=random()*.085;edge.push({x:(a.x+(b.x-a.x)*t)*(1-inset)+cx*inset,y:(a.y+(b.y-a.y)*t)*(1-inset)+cy*inset});}}
