   ctx.save();ctx.clip(p);const gr=ctx.createLinearGradient(cx-30,cy-35,cx+30,cy+35);gr.addColorStop(0,'#65615b');gr.addColorStop(.13,'#49454a');gr.addColorStop(.45,'#29272e');gr.addColorStop(1,'#14171c');ctx.fillStyle=gr;ctx.fillRect(cx-140,cy-140,280,280);
