   for(let k=0;k<3;k++){const an=random()*TAU;let xx=cx+Math.cos(an)*18,yy=cy+Math.sin(an)*18;ctx.beginPath();ctx.moveTo(xx,yy);for(let j=0;j<4;j++){xx+=Math.cos(an+(random()-.5))*(3+random()*7);yy+=Math.sin(an+(random()-.5))*(3+random()*7);ctx.lineTo(xx,yy);}ctx.strokeStyle='rgba(9,8,14,.85)';ctx.lineWidth=2;ctx.stroke();ctx.strokeStyle='rgba(128,73,44,.45)';ctx.lineWidth=.65;ctx.stroke();}
   ctx.restore();ctx.lineJoin='round';ctx.lineWidth=2.5;ctx.strokeStyle='#100f16';ctx.stroke(p);
   for(let k=0;k<edge.length;k++){const a=edge[k],b=edge[(k+1)%edge.length];ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=b.x>a.x?'rgba(207,119,48,.66)':'rgba(154,143,124,.52)';ctx.lineWidth=2;ctx.stroke();}
