 z.scorchUniforms.lavaTime.value=age+z.scorchAngle*3;z.scorchUniforms.lavaHeat.value=heat;
 for(const m of z.mesh.children){m.material.opacity=grow*fade*(m.userData.emberSeams?(.74+z.scorchRank*.055)*(z.oilAftermath?1.02:1):.94);m.material.depthWrite=!m.userData.emberSeams&&grow*fade>.5;}
