   const swell=inflation*inflation*(3-2*inflation),radius=sz*(.48+swell*1.12),height=sz*(.18+swell*(1.85+z.scorchRank*.18))*heat;
   const skin=cycle<.72?1:Math.max(0,1-burst*8),wobble=1+Math.sin(age*4.2+site.phase)*.045;
   o.rotation.set(0,site.phase+age*.1,0);o.position.set(x,base,zz);o.scale.set(radius*wobble*skin,height*skin,radius/wobble*skin);o.updateMatrix();a.ember.setMatrixAt(count,o.matrix);
   a.color.setRGB(.65+.35*heat,.35+.65*heat,.2+.8*heat);a.ember.setColorAt(count,a.color);
   if(burst>0&&burst<1){
    const settle=Math.pow(1-burst,1.3),spread=sz*(.8+burst*1.8)*Math.sqrt(settle);
    o.position.set(x,base+.1,zz);o.rotation.set(0,site.phase,0);o.scale.set(spread,sz*1.8*settle*heat,spread);o.updateMatrix();a.crown.setMatrixAt(a.crown.count,o.matrix);a.crown.setColorAt(a.crown.count++,a.color);
    for(let d=0;d<3&&a.drops.count<a.cap*3;d++){
     const angle=site.phase+d*TAU/3+.24*Math.sin(i+d),distance=sz*(.45+burst*(2.1+d*.35)),dx=x+Math.cos(angle)*distance,dz=zz+Math.sin(angle)*distance;
     const rise=height*(1-burst)+sz*(1.2+d*.22)*Math.sin(Math.PI*burst),size=sz*(.23+d*.035)*Math.pow(1-burst,.6);
     o.position.set(dx,Math.max(gAt(dx,dz)+.65,base+rise),dz);o.rotation.set(burst*4+site.phase,angle,burst*3);o.scale.set(size,size*(1.25+Math.sin(Math.PI*burst)*.7),size);o.updateMatrix();a.drops.setMatrixAt(a.drops.count,o.matrix);a.drops.setColorAt(a.drops.count++,a.color);
    }
   }
   if(i%5===0&&a.flames.count<Math.floor(a.cap/3)){const flick=.86+.14*Math.sin(G.t*5+site.phase),flameHeight=sz*(2.3+.3*z.scorchRank)*flick*heat;o.position.set(x,base+flameHeight*.46,zz);o.quaternion.copy(camera.quaternion);o.scale.set(sz*1.4*flick,flameHeight,1);o.updateMatrix();a.flames.setMatrixAt(a.flames.count++,o.matrix);}
