// Charred deaths from the oil/dragon combination and active friendly lava.
let SCORCHED_ASH_ART=null;
function scorchedAshGeometry(){const g=new T.DodecahedronGeometry(1,0),n=g.attributes.normal,c=[];for(let i=0;i<n.count;i++){const shade=.45+.5*Math.max(0,n.getY(i)*.8-n.getX(i)*.35+n.getZ(i)*.25);c.push(shade,shade,shade);}g.setAttribute('color',new T.Float32BufferAttribute(c,3));return g;}
