 const origin=gAt(e.x,e.z),height=Math.max(8,top-origin),record={x:e.x,z:e.z,born:G.t,height,parts:[],puff:false};
 e.scorchCorpseUniforms.scorchScale.value=1/height;
 for(let i=0;i<points.length;i++){
  const p=points[i],angle=Math.atan2(p.z-e.z,p.x-e.x)+Math.sin(i*3.1)*.45,speed=(3+i%4*1.4)*Math.min(2,height/18),vx=Math.cos(angle)*speed,vz=Math.sin(angle)*speed;
  const floor=scorchedAshFloor(p.x+vx*.75,p.z+vz*.75),y=Math.max(p.y,floor+.4),vy=3+i%3*2,gravity=55,flight=(vy+Math.sqrt(vy*vy+2*gravity*Math.max(0,y-floor)))/gravity;
  const landing={},landFloor=scorchedAshFloor(p.x+vx*flight,p.z+vz*flight,landing);
  record.parts.push({x:p.x,y,z:p.z,vx,vz,vy,gravity,flight,floor:landFloor,pool:landing.pool,delay:.30+(1-Math.max(0,Math.min(1,(p.y-origin)/height)))*.70+(i%3)*.018,size:(.95+i%4*.26)*Math.max(.8,Math.min(2.4,height/18)),spin:i*2.399});
 }
