 for(let i=0;i<6;i++){const a=(i-2.5)*.18;add(new T.CylinderGeometry(.052,.07,.17,5).translate(Math.sin(a)*.8,-.57,Math.cos(a)*.24+.17),'#d1bbdf',true);}
