 halo.addColorStop(0,'rgba(18,2,35,.96)');halo.addColorStop(.25,'rgba(24,3,44,.92)');halo.addColorStop(.4,'rgba(82,15,137,.85)');halo.addColorStop(.5,'rgba(139,39,210,.52)');halo.addColorStop(.73,'rgba(102,13,186,.13)');halo.addColorStop(1,'rgba(76,6,137,0)');m.fillStyle=halo;m.fillRect(0,0,64,64);
