 const cloudCanvas=mk(128,128),cc=cloudCanvas.getContext('2d'),pixels=cc.createImageData(128,128),clamp01=v=>Math.max(0,Math.min(1,v));
 const n=(x,y)=>{const ix=Math.floor(x),iy=Math.floor(y);let u=x-ix,v=y-iy;u=u*u*(3-2*u);v=v*v*(3-2*v);const at=(a,b)=>data.data[(((b&127)*128+(a&127))*4)]/255;return (at(ix,iy)*(1-u)+at(ix+1,iy)*u)*(1-v)+(at(ix,iy+1)*(1-u)+at(ix+1,iy+1)*u)*v;};
