  const u=x/127,v=y/127,q=n(u*5+6,v*5+13)*.52+n(u*11+23,v*11+6)*.29+n(u*23+8,v*23+17)*.13+n(u*47,v*47)*.06;
  const dx=(u-.5)*2,dy=(v-.5)*2,edge=clamp01((1-Math.hypot(dx,dy)+(q-.5)*.42)*2),alpha=edge*edge*clamp01((q-.22)*1.5),i=(y*128+x)*4;
