  f.fogUniforms={fogNoise:{value:A.noise},fogTime:{value:G.t},fogStrength:{value:0}};
  const ground=new T.PlaneGeometry(2.16,2.16,mobile?14:20,mobile?14:20);ground.rotateX(-Math.PI/2);
