   for(let i=0;i<p.count;i++){const x=u[i*3]*f.r,z=u[i*3+2]*f.r,wx=f.x+x*cs+z*sn,wz=f.z-x*sn+z*cs;p.setXYZ(i,x,gAt(wx,wz)+.7+u[i*3+1]*height,z);}p.needsUpdate=true;mesh.position.set(f.x,0,f.z);mesh.rotation.y=turn;
