 if(!WITHER_AURA){const f={x:p.x,z:p.z,r,rank:l,born:G.t,persistent:true};renderWitherPulse(f,0);WITHER_AURA=f.mesh;WITHER_AURA.userData.field=f;WITHER_AURA.userData.owner=p;}
