 add('poison',e.pois,e.poisonStacks||1,(e.poisonStacks||0)>=5);
 add('rot',e.rot,'');add('bleed',e.bleed,Math.max(1,Math.min(4,Math.ceil((e.bleedDps||0)/(e.bleedVisualBase||e.bleedDps||1)-1e-6))));add('burn',e.burn,e.burnStacks||1,(e.burnStacks||0)>=5);
 add('frozen',e.frozen);add('brittle',e.brittle);
 const icy=e.chill>0,slow=Math.max(0,Math.min(1,e.slowPct||0));
 add('chill',icy?e.chill:0,'−'+Math.round(100*Math.min(1,e.frostSlow||.25))+'%');
