 c.fillStyle='#13141c';c.fillRect(0,0,size,size);c.drawImage(art,2,2,size-4,size-4);
 const shade=c.createLinearGradient(0,0,0,size);shade.addColorStop(0,'rgba(255,255,255,.08)');shade.addColorStop(.55,'rgba(0,0,0,0)');shade.addColorStop(1,'rgba(0,0,0,.50)');c.fillStyle=shade;c.fillRect(1,1,size-2,size-2);
 c.strokeStyle=style.color;c.globalAlpha=.85;c.lineWidth=1;c.strokeRect(.5,.5,size-1,size-1);c.globalAlpha=1;
