 u.coat.material.color.set(fire?'#ed621c':ice?'#70cde8':'#87bbf4');u.coat.material.opacity=fire?.55:ice?.65:.4;
 u.string.material.color.set(fire?'#ffc17c':ice?'#d2f5ff':'#b5dbff');u.flames.visible=fire&&!u.pyreBow;u.frostCrystals.visible=false;u.arc.visible=storm;
 for(let i=0;i<8;i++){const y=(i<4?-1:1)*(.19+(i%4)*.18),phase=(t*(fire?1.9:.65)+i*.618)%1;
  if(fire){mageStamp(u.flames,i,0,y+.1,.10,(.22+.05*Math.sin(t*12+i))*power,(.36+.12*Math.sin(t*9+i*2))*power,1,u.billboard);}
  mageStamp(u.motes,i,Math.sin(i*7+t)*.07,y+phase*.3,.15+Math.cos(i*2+t)*.06,(1-phase)*.06*power,(1-phase)*.09*power,1,u.billboard);
 }
 u.motes.material.color.set(fire?'#ffbe59':ice?'#ccefff':'#b0ceff');u.motes.instanceMatrix.needsUpdate=true;u.flames.instanceMatrix.needsUpdate=true;
 for(let i=0;i<12;i++){const y=(i<6?-1:1)*(.16+(i%6)*.12),d=MAGE_TMP;d.position.set((i%2?1:-1)*.035,y,.10);d.rotation.set((i%2?1:-1)*.6,0,(i<6?1:-1)*.45);d.scale.set(.055*power,(.10+(i%3)*.04)*power,.065*power);d.updateMatrix();u.frostCrystals.setMatrixAt(i,d.matrix);}u.frostCrystals.instanceMatrix.needsUpdate=true;
 if(storm){const a=u.arc.geometry.attributes.position;let v=0;for(let cross=0;cross<2;cross++)for(let i=0;i<24;i++){const y=-.83+i/24*1.66,y2=y+1.66/24,j=Math.floor(t*18),x=Math.sin(i*7+j)*.065,x2=Math.sin((i+1)*7+j)*.065,w=.009*power;for(const P of [[x-w,y,.16],[x+w,y,.16],[x2+w,y2,.16],[x-w,y,.16],[x2+w,y2,.16],[x2-w,y2,.16]])a.setXYZ(v++,cross?.02:P[0],P[1],cross?P[0]+.16:P[2]);}a.needsUpdate=true;}
