 for(let i=0;i<f.haze.count;i++){const a=i*2.399,rr=f.r*(.2+k*.6),x=f.x+Math.cos(a)*rr,z=f.z+Math.sin(a)*rr;mageStamp(f.haze,i,x,gAt(x,z)+2+k*(fire?14:3),z,f.r*.5,f.r*(fire?.35:.14),1);}
