 const dragonOilVictims=new Set();for(const e of G.enemies){if(e.dead||f.hit.has(e))continue;const dx=e.x-f.x,dz=e.z-f.z,along=dx*cx+dz*cz;if(along>=start-e.r&&along<=end+e.r&&Math.abs(-dx*cz+dz*cx)<=f.w+e.r&&enemyInOil(e))dragonOilVictims.add(e);}
