 for(const e of G.enemies){if(e.dead||f.hit.has(e))continue;const dx=e.x-f.x,dz=e.z-f.z,along=dx*cx+dz*cz,perp=Math.abs(-dx*cz+dz*cx);if(along<start-e.r||along>end+e.r||perp>f.w+e.r)continue;f.hit.add(e);const previous=e.hitElement;e.hitElement='fire';(dragonOilVictims.has(e)||scorchedGroundAt(e)?scorchedHit:hitEnemy)(e,f.dmg,cx*40,cz*40);e.hitElement=previous;if(!e.dead)status(e,'burn',f.burn,5);}
