function renderEnemyOrb(pr){const g=pr.mesh,t=G.t;g.children[0].scale.setScalar(.94+Math.sin(t*13+pr.x)*.06);g.children[1].rotation.z=t*3;g.children[2].rotation.y=-t*2.4;}

// One continuous formation for the whole Shield Wall buff, independent of damage ticks.
