 quad([-.65,3,-1.15],[.65,3,-1.15],[.65,2.5,-2.7],[-.65,2.5,-2.7],'#80603d');quad([-.65,2.5,-2.7],[.65,2.5,-2.7],[.65,-1.1,-2.7],[-.65,-1.1,-2.7],'#483326');quad([-.65,-1.1,-2.7],[.65,-1.1,-2.7],[.65,-1.5,-1.15],[-.65,-1.5,-1.15],'#6c5035');
