const DGRID={cell:48,map:new Map()};
function buildDecorGrid(){DGRID.map=new Map();for(const d of DECOR){const c=DGRID.cell,x0=Math.floor((d.x-d.r)/c),x1=Math.floor((d.x+d.r)/c),z0=Math.floor((d.z-d.r)/c),z1=Math.floor((d.z+d.r)/c);for(let gx=x0;gx<=x1;gx++)for(let gz=z0;gz<=z1;gz++){const k=gx*100000+gz;let a=DGRID.map.get(k);if(!a){a=[];DGRID.map.set(k,a);}a.push(d);}}}
function keepInBounds(o,rad){const lim=GROUND_SIZE/2-30;o.x=clamp(o.x,-lim,lim);o.z=clamp(o.z,-lim,lim);let edge=false;{const WR=900-(rad||5),rr=Math.hypot(o.x,o.z);if(rr>WR){o.x*=WR/rr;o.z*=WR/rr;edge=true;}}const R=rad||5;const c=DGRID.cell,gx=Math.floor(o.x/c),gz=Math.floor(o.z/c);let pushed=false;for(let ox=-1;ox<=1;ox++)for(let oz=-1;oz<=1;oz++){const a=DGRID.map.get((gx+ox)*100000+(gz+oz));if(!a)continue;for(const d of a){const dx=o.x-d.x,dz=o.z-d.z,dd=Math.hypot(dx,dz),min=d.r+R;if(dd<min&&dd>0){o.x+=dx/dd*(min-dd);o.z+=dz/dd*(min-dd);pushed=true;}}}return pushed||edge;}
function addZone(z){const K=z.kind;if(K==='caltrops')sfx('trap',{x:z.x,z:z.z});const look={fire:['flame',z.hostile?'#ff3010':'#ff7a10',true,1.2],gas:['cloud','#4fa52a',false,.6],curse:['rune','#9a50ff',false,.5],rain:['ring','#e8e0c0',false,0],caltrops:['spikes','#c0c4cc',false,0],ice:['disc','#bfe8ff',false,.3],shock:['rune','#9ad0ff',false,2],bone:['rune','#e8e2cc',false,.4],lull:['rune','#a0c8ff',false,.3]}[K]||['disc','#b0b8c0',false,0];z.mesh=new T.Group();const d=decal(look[0],look[1],look[2]);d.userData.spin=look[3];z.mesh.add(d);if(K==='fire'||K==='gas'){const d2=decal(look[0],look[1],look[2]);d2.userData.spin=-look[3]*.7;d2.rotation.y=1.3;d2.scale.setScalar(.8);z.mesh.add(d2);}z.mesh.position.set(z.x,gAt(z.x,z.z)+.4,z.z);z.mesh.scale.set(z.r,1,z.r);if(z.hostile&&z.warm!==0){z.warm=.7;z.t+=.7;enemyWarn('circle',{x:z.x,z:z.z,r:z.r,dur:.7});z.mesh.visible=false;}if(K==='caltrops'&&G.p.stance==='k_trap')decorateTrapperCaltrops(z);else if(z.boneBrittle||['bone','lull','caltrops'].includes(K))decorateLegacyZone(z);if(K==='oil')decorateOilSlick(z);if(K==='gas')decorateAcidPool(z);if(K==='fire'&&!z.hostile&&(G.p.cls==='archer'||G.p.cls==='mage'||z.leapFire))decorateScorchedEarth(z);if(K==='ice'&&!z.hostile&&G.p.cls==='mage')decorateMageIceGround(z);scene.add(z.mesh);G.zones.push(z);return z;}
function upgradeChoiceDeferred(p=G.p){return !!(p.showtime||p.shieldPush||p.shieldShoveUntil>G.t);}
function gainXp(v){const p=G.p;p.xp+=v;if(upgradeChoiceDeferred(p)||G.state!=='play'||p.dying)return;if(G.deferredChoices?.length){const next=G.deferredChoices.shift();offerPicks(next.picks,next.sub);return;}while(p.xp>=p.xpNeed){p.xp-=p.xpNeed;p.lvl++;p.xpNeed=Math.round(10+p.lvl*7+p.lvl*p.lvl*.9);fx('ring',{x:p.x,z:p.z,r:30,dur:.7,col:'#ffd040'});levelUp();if((!G||G.state!=='play'))break;}}
function levelUp(){const p=G.p;p.hp=Math.min(p.maxhp,p.hp+Math.round(p.maxhp*.1));sfx('level');
 if(STANCES[p.cls]&&!p.stance){offerPicks(STANCES[p.cls],`${CLASSES[p.cls].name}, level ${p.lvl}. Choose your ${p.cls==='tank'?'weapon':'path'} — it decides what you will be offered from here on.`);return;}
 const pool=UPG.filter(u=>!(p.stance==='b_provo'&&u.cls&&u.build!=='b_provo')&&(!u.cls||u.cls.split(',').includes(p.cls))&&(!u.stance||u.stance===p.stance)&&!(p.stance==='n_bone'&&u.id==='wither')&&!(['k_bomb','k_clock'].includes(p.stance)&&u.id==='shotgun')&&(p.ranks[u.id]||0)<u.max);const weaponCount=Object.keys(p.weapons).length;
 const aff={};let anyAff=false;for(const id in p.ranks){const b=UPG_BY[id]&&UPG_BY[id].build;if(b){aff[b]=(aff[b]||0)+p.ranks[id];anyAff=true;}}
 const w=pool.map(u=>{let wt=1;if(u.cls&&!p.ranks[u.id])wt=weaponCount>=4?.6:1.6;if(p.ranks[u.id])wt*=1.2;const affinity=u.build||(['shotgun','bow'].includes(u.id)?p.stance:null);if(affinity){const a=aff[affinity]||0;wt*=1+Math.min(4,a)*1.1;if(anyAff&&a===0)wt*=.55;}return {u,wt};});
 const picks=itemPrerequisiteOffers(w,p);if(p.lvl<=3&&picks.length<3){const j=w.findIndex(a=>a.u.cls&&!p.ranks[a.u.id]);if(j>=0){picks.push(w[j].u);w.splice(j,1);}}for(let i=picks.length;i<3&&w.length;i++){let tot=w.reduce((s,a)=>s+a.wt,0),r=Math.random()*tot,j=0;for(;j<w.length;j++){r-=w[j].wt;if(r<=0)break;}j=Math.min(j,w.length-1);picks.push(w[j].u);w.splice(j,1);}
 if(!picks.length){p.hp=Math.min(p.maxhp,p.hp+30);return;}
 offerPicks(picks,`${CLASSES[p.cls].name}, level ${p.lvl}. Choose your training.`);}
function offerPicks(picks,sub){const p=G.p;if(upgradeChoiceDeferred(p)){(G.deferredChoices||(G.deferredChoices=[])).push({picks,sub});return;}G.state='levelup';mobileResetInput();releaseStorm();stopStormSound();$('lvsub').textContent=sub;const box=$('picks');box.innerHTML='';
 picks.forEach((u,i)=>{const lv=(p.ranks[u.id]||0)+1,b=document.createElement('button');b.type='button';b.className='pick'+(lv===1&&!u.stanceId?' new':'')+(u.stanceId?' wep':'');
  const head=document.createElement('div');head.className='head';const med=document.createElement('div');med.className='med';const ic=iconFor(u),c=mk(ic.width,ic.height);c.getContext('2d').drawImage(ic,0,0);if(ic.width>12)c.className='hd';med.appendChild(c);head.appendChild(med);
  const ttl=document.createElement('div');ttl.className='ttl';const t=document.createElement('b');t.textContent=u.name;ttl.appendChild(t);const l=document.createElement('span');l.className='lv';
  if(u.stanceId)l.textContent='Weapon';else if(lv===1)l.textContent=u.passive?'New':'New skill';else{l.textContent='Rank '+lv+' of '+u.max;const pips=document.createElement('span');pips.className='pips';for(let k=1;k<=u.max;k++){const q=document.createElement('i');if(k<lv)q.className='on';else if(k===lv)q.className='nx';pips.appendChild(q);}l.appendChild(pips);}
  ttl.appendChild(l);head.appendChild(ttl);b.appendChild(head);
  let rankTxt='',baseTxt='';try{rankTxt=u.desc(lv);if(lv>1)baseTxt=u.desc(1);}catch(e){rankTxt=u.desc(lv);}
  const copy=document.createElement('div');copy.className='pick-copy';b.appendChild(copy);
  if(baseTxt){const bs=document.createElement('div');bs.className='base';bs.textContent=baseTxt;copy.appendChild(bs);const r=document.createElement('div');r.className='rank';r.textContent=rankTxt;copy.appendChild(r);}else{const s2=document.createElement('small');s2.textContent=rankTxt;copy.appendChild(s2);}
  const foot=document.createElement('div');foot.className='foot';let meta='';if(u.cd){try{const c0=u.cd(lv);meta='Cooldown '+(Math.round(c0*10)/10)+'s';if(lv>1){const cp=u.cd(lv-1);if(Math.abs(cp-c0)>.05)meta='Cooldown '+(Math.round(cp*10)/10)+'s → '+(Math.round(c0*10)/10)+'s';}}catch(e){}}else if(u.passive)meta='Passive';else if(u.stanceId)meta='Choose once';
  const mt=document.createElement('span');mt.className='tag';mt.textContent=meta||(lv===1?'Skill':'Upgrade');foot.appendChild(mt);const key=document.createElement('span');key.className='key';key.textContent=String(i+1);foot.appendChild(key);b.appendChild(foot);
  b.addEventListener('click',()=>{if(!G||G.state!=='levelup'||!b.isConnected||b.disabled)return;b.disabled=true;if(u.stanceId)applyStance(u.stanceId);else addUpgrade(u.id);G.state='play';gainXp(0);if(G.state==='play'){$('levelup').hidden=true;last=performance.now();}hud();});box.appendChild(b);if(i===0)setTimeout(()=>{if(b.isConnected&&G&&G.state==='levelup')b.focus();},30);});
 $('levelup').hidden=false;}
window.addEventListener('keydown',e=>{if(!G||G.state!=='levelup'||$('levelup').hidden)return;const n=parseInt(e.key,10);if(n>=1&&n<=3){if(e.repeat){e.preventDefault();return;}const b=$('picks').children[n-1];if(b){e.preventDefault();b.click();}}});
function applyStance(id){const p=G.p;if(id==='b_sonic'){stopBardMusic();p.bardTrackOffsets=p.bardTrackOffsets||{};p.bardTrackOffsets.tab_lute=0;p.bardTrackOffsets.two_routes=0;}restoreShotgunPose(p);p.stance=id;if(p.cls==='archer'){const kind=id==='a_fire'?'fire':id==='a_ice'?'ice':'light';if(p.mesh.userData.archerBody!==kind){disposeArcherBow(p);scene.remove(p.mesh);p.mesh=buildHero('archer',kind);scene.add(p.mesh);}}if(p.cls==='bard')setComicBard(p.mesh,id==='b_sonic');if(p.cls==='trapper'){const kind=id==='k_bomb'?'bomb':id==='k_clock'?'clock':'trap';if(p.mesh.userData.tinkerBody!==kind){disposeImportedTinker(p.mesh);scene.remove(p.mesh);p.mesh=buildHero('trapper',kind);scene.add(p.mesh);p.bastionBones=null;}setTinkerRegalia(p.mesh,id);}if(p.cls==='necro'){const kind=id==='n_bone'?'bone':'plague';if(p.mesh.userData.necroBody!==kind){disposeImportedNecro(p.mesh);p.mesh.userData.mixer.stopAllAction();scene.remove(p.mesh);p.mesh=buildHero('necro',kind);scene.add(p.mesh);}}if(id==='b_provo')equipBrawler(p);else if(p.mesh.userData.brawler){disposePeacekeeper(p.mesh);p.mesh.userData.mixer.stopAllAction();scene.remove(p.mesh);p.mesh=buildHero(p.cls);scene.add(p.mesh);p.brawlAttack=p.brawlQueued=null;p.ranks.dirge=Math.max(1,p.ranks.dirge||0);p.weapons.dirge={t:.2};}if(p.cls==='bard'&&id!=='b_provo'&&(id==='b_peace'?!p.mesh.userData.peaceBody:!!p.mesh.userData.sonicBody!==(id==='b_sonic'&&SONIC_TRIPO_BODY)||!!p.mesh.userData.peaceBody)){disposePeacekeeper(p.mesh);p.mesh.userData.mixer.stopAllAction();scene.remove(p.mesh);p.mesh=buildHero('bard',id==='b_sonic'&&SONIC_TRIPO_BODY?'sonic':id==='b_peace'?'peace':undefined);scene.add(p.mesh);}syncBardSolo();if(id==='b_sonic'){p.ranks.finale=Math.max(1,p.ranks.finale||0);p.weapons.finale={t:0};p.actionCd=0;p.bardCrowd=p.bardCrowd||0;p.bardListenT=1;}else{p.showtime=null;p.bardCrowd=0;}if(id==='k_bomb'){const r=p.ranks.shotgun||1;delete p.ranks.shotgun;delete p.weapons.shotgun;p.ranks.grenade=Math.max(p.ranks.grenade||0,r);p.weapons.grenade={t:.25};p.ranks.keg=Math.max(1,p.ranks.keg||0);p.weapons.keg={t:0};p.actionCd=0;equipDemolitions(p);}if(id==='k_trap'){p.ranks.bear=Math.max(1,p.ranks.bear||0);p.weapons.bear={t:0};p.actionCd=0;}if(id==='n_bone'){const r=p.ranks.wither||1;delete p.ranks.wither;delete p.weapons.wither;p.ranks.spear=Math.max(p.ranks.spear||0,r);p.weapons.spear={t:.2};p.ranks.prison=Math.max(1,p.ranks.prison||0);p.weapons.prison={t:0};p.ranks.serratedbones=Math.max(1,p.ranks.serratedbones||0);p.actionCd=0;}if(p.cls!=='tank'){const st=(STANCES[p.cls]||[]).find(s=>s.stanceId===id);if(st)banner(st.name+'.');}if(p.cls==='tank'){if(id==='gs'){const r=p.ranks.sword||1;delete p.ranks.sword;delete p.weapons.sword;p.ranks.cleave=r;p.weapons.cleave={t:.2};setHeroGear(p.mesh,['2H_Sword','Knight_Helmet','Knight_Cape']);banner('Greatsword. No shield, no mercy.');}else if(id==='hal'){const r=p.ranks.sword||1;delete p.ranks.sword;delete p.weapons.sword;p.ranks.thrust=r;p.weapons.thrust={t:.2};setHeroGear(p.mesh,['2H_Sword','Knight_Helmet','Knight_Cape']);const sw=p.mesh.getObjectByName('2H_Sword');if(sw){sw.visible=false;let h=sw.parent.getObjectByName('HalberdMesh');if(!h){h=halberdMesh();h.name='HalberdMesh';const ws=new T.Vector3();sw.parent.getWorldScale(ws);h.scale.setScalar(.42/(ws.x||10));h.position.set(0,0,0);sw.parent.add(h);}h.visible=true;}p.ranks.hook=Math.max(1,p.ranks.hook||0);p.weapons.hook={t:0};p.halAttack=null;p.halCharge=null;p.halChargeCd=0;p.halBlood=0;p.phalanxT=0;p.actionCd=0;banner('Halberd. Hook gathers foes while you move. Impale follows your movement; when standing still, aim it.');}else{setHeroGear(p.mesh,['1H_Sword','Round_Shield','Knight_Helmet','Knight_Cape']);banner('Sword and board. Hold the line.');}}recompute();if(id==='n_bone')bsInit(p);refreshSlots();sfx('level');}
