function bossScreenPosition(e,W,H){
 const ground=gAt(e.x,e.z),height=e.h*e.sc;
 _P.set(e.x,ground+height*.45,e.z).project(camera);
 const off=!Number.isFinite(_P.x+_P.y+_P.z)||_P.z < -1||_P.z>1||Math.abs(_P.x)>1||Math.abs(_P.y)>1||(!e.tavern&&!e.mesh.visible);
 _P.set(e.x,ground+height+8,e.z).project(camera);
 return {off,sx:(_P.x+1)*W/2,sy:(1-_P.y)*H/2};
}
const WHIRL={mesh:null};const FLASH_MAT=new T.MeshBasicMaterial({color:'#a8a8a8'});const GHOST_MAT=new T.MeshLambertMaterial({vertexColors:true,transparent:true,opacity:.45});const BLOOD_MAT=new T.MeshBasicMaterial({map:bloodTexture(),color:new T.Color('#9e1021').convertSRGBToLinear(),transparent:true,opacity:.94,depthWrite:false,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:-1});let bloodMeshes=[],BLOOD_IM=null,animFrame=0;

// ============================================================ HUD
function hud(){updateActionHud();updateSkillReadouts();const p=G.p;const m=Math.floor(G.t/60),s=Math.floor(G.t%60);$('timer').textContent=m+':'+(s<10?'0':'')+s;$('kills').textContent=G.kills;$('gold').textContent=G.gold;$('plevel').textContent='Level '+p.lvl;$('hpbar').style.width=(100*p.hp/p.maxhp)+'%';$('hptext').textContent=Math.ceil(p.hp)+' / '+p.maxhp;$('xpbar').style.width=Math.min(100,100*p.xp/p.xpNeed)+'%';$('dashcd').textContent=p.dashCd>0?'Dash '+p.dashCd.toFixed(1)+'s':(IS_TOUCH?'Dash ready':'Dash ready (Space)');$('dashcd').classList.toggle('cd',p.dashCd>0);
 $('pyrefocus').hidden=true;$('pyrefocus').textContent=p.dashCd>0?'Dragon Dash · '+p.dashCd.toFixed(1)+'s':'Dragon Dash · ready';const cb=$('combo');if(G.combo>=5){cb.textContent=G.combo+' slain!';cb.classList.add('show');cb.style.transform='scale('+(1+Math.min(.6,G.comboT*.3))+')';}else cb.classList.remove('show');
 const bb=$('bossbar');if(G.boss&&!G.boss.dead){bb.style.display='block';$('bossname').textContent=G.boss.def.name;$('bosshp').style.width=(100*G.boss.hp/G.boss.maxhp)+'%';}else bb.style.display='none';layoutCombatHud();}

// ============================================================ loop & flow
let last=0;
let mobileFrameAt=0;function loop(now){requestAnimationFrame(loop);if(!G)return;if(now-mobileFrameAt<15.5)return;mobileFrameAt=now;mobileMeasureFrame(now);try{loop2(now);}catch(e){if(!window.__loopErr){window.__loopErr=1;showErr('loop: '+(e&&e.message||e)+' '+(e&&e.stack||'').split('\n')[1]);}}}
let fpsAcc=0,fpsN=0,quality=2;
// quality governor: only the render resolution moves (cheap); shadows are decided once at start. Drops fast, climbs slowly (hysteresis) so it never oscillates.
let qGood=0;function autoQuality(dt){if(dt>.25)return;fpsAcc+=dt;fpsN++;if(fpsAcc<2)return;const avg=fpsAcc/fpsN;fpsAcc=0;fpsN=0;if(avg>1/30&&quality>0){quality--;qGood=0;applyQuality();}else if(avg<1/55&&quality<2){qGood++;if(qGood>=4){qGood=0;quality++;applyQuality();}}else qGood=0;}
function applyQuality(){renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,quality===2?1.25:quality===1?1:.8));for(const e of (G?G.enemies:[]))e.mesh.traverse(c=>{if(c.material===OUTLINE_SKIN||c.userData.celOutline)c.visible=quality>=1;});}
// Preserve elapsed gameplay time across ordinary dropped frames.
// Bound each simulation step for collision/attack stability; render once.
function loop2(now){
 let elapsed=Math.max(0,(now-last)/1000);last=now;
 if(renderer.getContext().isContextLost()||window.BriarfordOrientation?.blocked){G.dt=0;return;}
 if(G.state==='play')autoQuality(elapsed);
 // Long browser suspensions are not played back as an instant attack burst.
 const dt=Math.min(elapsed,.25);G.hitstop=0;G.shake=0;G.dt=dt;
 if(G.classBoss){if(!window.__freeze)tickClassBoss(dt);if(G.classBoss)drawClassBoss();return;}
 if(G.boneWorkshop){bsDraw();return;}
 if(G.graveWar){if(!window.__freeze)tickGraveWar(dt);if(G.graveWar)renderGraveWar();return;}
 if(G.tavernDuel){if(!window.__freeze)tickTavernDuel(dt);if(G.tavernDuel)renderTavernDuel();return;}
 syncBardSolo();
 if(G.state!=='play'){hideShowtimeHud();releaseStorm();stopStormSound();if(G.p.bardMusic)stopBardMusic();}
 if(window.__freeze){G.dt=0;render();return;}
 if(G.state==='dying'){partUpdate(dt);G.p.at+=dt;render();return;}
 if(G.state!=='play')return;
 // Catch-up is capped at two steps: when a frame is slow the simulation must not do more work per frame, or lag feeds itself.
 let remaining=Math.min(dt,2/30);
 while(remaining>1e-8&&G.state==='play'){
  const step=Math.min(remaining,1/30);G.dt=step;partUpdate(step);update(step);remaining-=step;
  if(G.classBoss){drawClassBoss();return;}
  if(G.graveWar){renderGraveWar();return;}
  checkTavernDoor();if(G.tavernDuel){renderTavernDuel();return;}
 }
 G.dt=dt;
 if(G.state==='play'||G.state==='levelup'){render();hud();}
}
function clearScene(){endMobileBastion();disposeHalHorse();if(G&&G.classBoss)finishClassBoss("leave",true);bsCleanup();if(G&&G.graveWar)finishGraveWar('leave',true);if(G&&G.tavernDuel)finishTavernDuel('leave',true);if($('tavernEntryHint'))$('tavernEntryHint').style.display='none';hideShowtimeHud();clearShowtimeStage();if($('halchargebtn'))$('halchargebtn').hidden=true;clearMageWard();clearWitherAura();releaseShieldWall();releaseStorm();stopSfx();if(!G)return;disposeComicBard(G.p.mesh);disposeArcherBow(G.p);setTinkerRegalia(G.p.mesh,null);setBoneNecro(G.p.mesh,false);setPlagueDoctor(G.p.mesh,false);clearStatusBodies();clearScorchedDetails();clearAscensionSupport();if(COMMAND_PREVIEW)COMMAND_PREVIEW.visible=false;if(HAL_PREVIEW)HAL_PREVIEW.visible=false;if(WHIRL.mesh)WHIRL.mesh.visible=false;if(G.p.mesh.userData.halberdRig){const rig=G.p.mesh.userData.halberdRig;for(const m of [...(rig.bloodPaint||[]),...(rig.bloodGlowMaterials||[])])m.dispose();}scene.remove(G.p.mesh);for(const e of G.enemies){affixDispose(e);disposeEnemyRig(e);scene.remove(e.mesh);if(e.mv&&e.mv.rock){scene.remove(e.mv.rock);e.mv.rock.geometry.dispose();e.mv.rock=null;}}for(const c of G.corpses){disposeEnemyRig(c);scene.remove(c.mesh);}for(const pt of G.pets){scene.remove(pt.mesh);if(pt.custom&&pt.mesh.userData.dispose)pt.mesh.userData.dispose();if(pt.risen)disposeEnemyRig(pt);}for(const a of [G.projs,G.pickups,G.traps,G.sentries,G.zones])for(const o of a)if(o.mesh){disposeClockworkGait(o.mesh);releaseIceInstances(o.mesh);scene.remove(o.mesh);}for(const f of G.fx)if(f.mesh){releaseIceInstances(f.mesh);scene.remove(f.mesh);if(f.archerOwnMaterials)f.mesh.traverse(o=>{if(o.material)o.material.dispose();if(o.userData.legacyOwnGeo&&o.geometry)o.geometry.dispose();});}for(const m of (G.marks||[]))scene.remove(m.mesh);for(const c of G.chests)scene.remove(c.m);for(const al of G.altars)scene.remove(al.m);if(BLOOD_IM)BLOOD_IM.count=0;for(const n in COIN_IM)COIN_IM[n].count=0;for(const bm of bladeMeshes)scene.remove(bm);bladeMeshes=[];}
function endRun(won){endMobileBastion();if(G&&G.tavernPractice){showMenu();return;}releaseStorm();stopStormSound();if(G.state==='end')return;G.state='end';musicVol(.35);render();hud();const p=G.p;G.gold=Math.round(G.gold*(G.tierGold||1));vault.gold+=G.gold;vault.best=Math.max(vault.best,Math.floor(G.t));if(won){recordVictory();if(MAP.town)vault.winsDusk=(vault.winsDusk||0)+1;else if(MAP.dungeon)vault.winsDeceit=(vault.winsDeceit||0)+1;else vault.wins++;if(ASC_MAPS[MAP.id]){const nt=(G.tier||0)+1;if(nt<=ASC_MAX&&earnedAscTier(p.cls,MAP.id)<nt){ascUnlock(p.cls,MAP.id,nt);if(campaignComplete()){G.ascMsg=' Ascension '+ASC_ROMAN[nt]+' of '+MAP.name+' is open to the '+CLASSES[p.cls].name+'.';menuTier[MAP.id]=nt;}}}sfx('win');}saveVault();
 $('endtitle').textContent=won?MAP.winTitle:'You have fallen';$('endsub').textContent=won?MAP.winSub+(G.ascMsg||'')+(!MAP.dungeon&&!MAP.town&&vault.wins===1?' The crypts of Kings Grave are now open.':MAP.dungeon&&vault.winsDeceit===1?' The road to Duskmoor and your fourth relic slot are open.':''):`The ${CLASSES[p.cls].name} fell at ${$('timer').textContent}. Your journey ends here, but your gold is kept.`;
 const m=Math.floor(G.t/60),s=Math.floor(G.t%60);$('results').innerHTML=[['Survived',m+':'+(s<10?'0':'')+s],['Slain',G.kills],['Level',p.lvl],['Damage',Math.round(G.damageDealt).toLocaleString()],['Gold earned',G.gold]].map(a=>`<div>${a[0]}<b>${a[1]}</b></div>`).join('');
 for(const el of document.querySelectorAll('.vaultgold'))el.textContent=vault.gold;$('endrelich').textContent='Relics of the '+CLASSES[p.cls].name;renderRelics($('endrelics'),p.cls);
 setTimeout(()=>{$('endEquipment').open=false;$('end').hidden=false;$('end').querySelector('.gump').scrollTop=0;$('againbtn').focus({preventScroll:true});},won?1200:600);}
