function loadVaultCode(code){try{code=(code||'').trim();if(!code.startsWith('BS1-'))return false;const v=JSON.parse(decodeURIComponent(escape(atob(code.slice(4)))));if(!v||typeof v!=='object')return false;vault.gold=Math.max(vault.gold,v.gold|0);vault.best=Math.max(vault.best,v.best|0);vault.wins=Math.max(vault.wins,v.wins|0);vault.winsDeceit=Math.max(vault.winsDeceit||0,v.winsDeceit|0);vault.winsDusk=Math.max(vault.winsDusk||0,v.winsDusk|0);vault.items=vault.items||{};for(const k in (v.items||{}))vault.items[k]=1;if(v.loadout)vault.loadout=Object.assign(vault.loadout||{},v.loadout);mergeClearRecords(v);if(v.tier)for(const c in v.tier)for(const m in v.tier[c])ascUnlock(c,m,v.tier[c][m]|0);reconcileAscensionRecords();migrateRelics();for(const k in (v.ranks||{}))vault.ranks[k]=Math.max(vault.ranks[k]||0,v.ranks[k]|0);saveVault();return true;}catch(e){return false;}}
