function startRun2(cls,worldSeed=0,stance=null){if(stance&&!(STANCES[cls]||[]).some(s=>s.stanceId===stance))throw new Error('Invalid build for class');mobileResetInput();migrateRelics();ascMigrate();$('menu').hidden=true;$('status').style.visibility='visible';$('pausebtn').style.visibility='visible';$('xptop').style.visibility='visible';camYaw=0;relicCls=cls;buildWorld(menuMap,worldSeed);resetBreakables();musicVol(1);music(menuMap);newGame(cls);const want=ascTierFor(menuMap),tier=Math.min(want,ascTierMax(cls,menuMap));const mods=tier?modsFor(menuMap,tier):[];modsStart(mods);ascScale(tier);G.waves=wavesFor(menuMap,tier,mods);recompute();if(stance){applyStance(stance);G.p.hp=G.p.maxhp;}if(G.p.stance==='k_clock'){const r=G.p.ranks.sentry||1;G.p.ranks.sentry=r;G.p.weapons.sentry=G.p.weapons.sentry||{t:0};recompute();deployStarterSentry(r);G.p.weapons.sentry.t=UPG_BY.sentry.cd(r)*G.p.cdMul;}warmRoster();warmFireArt();syncHeroInk(G.p.mesh,G.p.stance==='sb');if(hasMod('fog')){scene.fog.near=MAP.fog[0]*.55;scene.fog.far=MAP.fog[1]*.6;}else{scene.fog.near=MAP.fog[0];scene.fog.far=MAP.fog[1];}joy.active=false;last=performance.now();banner(tier?'Ascension '+ASC_ROMAN[tier]+(tier<want?' (this class has not climbed higher)':'')+'. Survive.':MAP.dungeon?'The crypt wakes. Survive.':'The dead stir. Survive.');}
