stage.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||!G||(!G||G.state!=='play'))return;if(e.target.closest('button,.gump'))return;const r=stage.getBoundingClientRect();const left=TOUCH_SIMPLE||(e.clientX-r.left)<r.width/2;const J=left?joy:aimJoy;if(J.active)return;J.active=true;J.id=e.pointerId;J.ox=e.clientX;J.oy=e.clientY;J.dx=J.dy=0;J.t0=performance.now();$(left?'mobileMoveHint':'mobileAimHint').classList.add('engaged');const ring=$(left?'joyring':'aimring');ring.style.display='block';ring.style.left=(e.clientX-r.left)+'px';ring.style.top=(e.clientY-r.top)+'px';$(left?'joyknob':'aimknob').style.transform='translate(-50%,-50%)';});
