// Lyric-directed performance. Every animation samples the shared song clock.
// New mouth/gesture sprites were generated from the game's existing performers.
function bpSection(d,t){
 if(d.chart.sections)return d.chart.sections[Math.min(d.chart.sections.length-1,bdPhraseAt(d,t))];
 const i=bdPhraseAt(d,t);return {start:d.chart.bounds[i],end:d.chart.bounds[i+1],singer:i%2?'player':'boss',play:i%2?'lead':'listen',label:i%2?'YOUR ANSWER':'THE KING PLAYS'};
}
function bpCue(d,type,t){return (d.chart.cues||[]).find(q=>q.type===type&&t>=q.t&&t<q.t+q.dur);}
function bpEnvelope(d,key,t){const a=d.chart[key];if(!a)return .35;const i=Math.floor(Math.max(0,t)/(d.chart.envelopeStep||.04));return a[Math.min(a.length-1,i)]||0;}
function bpBeat(d,t){const beats=d.chart.beats;if(!beats||!beats.length)return {pulse:Math.max(0,Math.cos(t*8)),index:Math.floor(t*2),phase:(t*2)%1};let lo=0,hi=beats.length;while(lo<hi){const m=(lo+hi)>>1;if(beats[m]<=t)lo=m+1;else hi=m;}const i=Math.max(0,lo-1),gap=Math.max(.2,(beats[i+1]||beats[i]+.5)-beats[i]),age=t-beats[i];return {pulse:age<0?0:Math.exp(-age*9),index:i,phase:clamp(age/gap,0,1)};}
function bpFocus(d,t){
 // Keep the King's whole verse theatrical, including his last lyric. Focus
 // starts with the player's turn, not with the early preview of their notes.
 const sections=d.chart.sections||d.chart.bounds.slice(0,-1).map((start,i)=>({start,end:d.chart.bounds[i+1],play:i%2?'lead':'listen'}));
 const spans=[];for(const q of sections){if(q.play==='listen')continue;const last=spans[spans.length-1];if(last&&q.start<=last.end+.001)last.end=q.end;else spans.push({start:q.start,end:q.end});}
 let focus=0;for(const q of spans){const enter=clamp((t-q.start)/.65,0,1),leave=clamp((q.end+.7-t)/.7,0,1);const u=Math.min(enter,leave);focus=Math.max(focus,u*u*(3-2*u));}return focus;
}
function bpStageShake(t,s){
 const impact=s.roof?Math.sin((t-s.roof.t)*46)*3.5*Math.max(0,1-(t-s.roof.t)/s.roof.dur):s.floor?Math.sin(t*25)*1.5:0;
 // Earned crowd impacts remain physical during player turns. Short beat-locked
 // jolts settle between stomps instead of continuously wobbling the room.
 const phase=s.beat.phase,house=bpHouseActive(s)?Math.sin(phase*TAU*3)*4.2*Math.pow(Math.max(0,1-phase/.48),2):0;
 return clamp(impact*(1-s.focus)+house,-4.2,4.2);
}
function bpCrowdFavor(d){
 // The room must hear actual judged playing before it can choose a singer.
 const judged=d.judged||0,ready=judged>=10;
 const recent=d.recent.length?d.recent.reduce((a,b)=>a+b,0)/d.recent.length:0;
 const overall=clamp((d.points-d.penalty)/Math.max(1,d.weightTotal),0,1);
 const quality=recent*.65+overall*.35,target=[.70,.76,.82][Math.min(2,d.round)];
 const side=!ready?'neutral':quality>=target+.04?'bard':quality<=target-.06?'king':'contested';
 const margin=(quality-target)/(quality>=target?1-target:target),confidence=ready?Math.min(1,judged/40):0;
 const bardPercent=Math.round(clamp(.5+.5*confidence*margin,0,1)*100),kingPercent=100-bardPercent;
 const stomping=ready&&Math.max(bardPercent,kingPercent)>=80;
 const heat=ready?clamp(.18+Math.min(1,judged/40)*.82*clamp((quality-.35)/.65,0,1),0,1):.18;
 return {ready,side,quality,heat,bardPercent,kingPercent,stomping};
}
function bpState(d,t){
 const section=bpSection(d,t),line=(d.chart.lyrics||[]).filter(l=>t>=l.start&&t<=l.end+.12).pop(),voice=bpEnvelope(d,'voiceEnvelope',t),beat=bpBeat(d,t),progress=clamp(t/d.chart.duration,0,1),skill=d.recent.length?d.recent.reduce((a,b)=>a+b,0)/d.recent.length:.55;
 const crowd=bpCrowdFavor(d),heat=crowd.heat,roof=bpCue(d,'roof',t),floor=bpCue(d,'floor',t),hush=!!(bpCue(d,'hush',t)||bpCue(d,'command',t)),bow=!!bpCue(d,'bow',t);
 const sing=line?line.singer:d.trackKey==='original'?section.singer:'none';
 return {section,line,voice,beat,progress,skill,crowd,heat,roof,floor,hush,bow,sing,open:!!(line&&voice>.075),backing:false,listening:section.play==='listen',focus:bpFocus(d,t),arrival:clamp((t-10)/190,0,1)};
}
function bpFrame(c,x,y,w,h,col='#ba9254',fill='#171827'){
 cbRect(c,x+5,y,w-10,h,fill);cbRect(c,x,y+5,w,h-10,fill);cbRect(c,x+5,y,w-10,2,col);cbRect(c,x+5,y+h-2,w-10,2,col);cbRect(c,x,y+5,2,h-10,col);cbRect(c,x+w-2,y+5,2,h-10,col);
 for(const [a,b] of [[x,y],[x+w-9,y],[x,y+h-9],[x+w-9,y+h-9]]){cbRect(c,a+2,b+2,7,7,'#59402f');cbRect(c,a+3,b+3,4,4,col);}
}
