// Small, diegetic reactions on a separate SFX bus; never duck/restart the song.
const BP_CROWD_BUFFERS={};
function bpCrowdBuffer(kind){
 if(BP_CROWD_BUFFERS[kind])return BP_CROWD_BUFFERS[kind];
 const recorded=recordedSoundBuffer('crowd_'+kind);if(recorded)return BP_CROWD_BUFFERS[kind]=recorded;
 const sr=AC.sampleRate,len=kind==='applause'?1.05:kind==='clap'?.26:.32,b=AC.createBuffer(1,Math.ceil(sr*len),sr),a=b.getChannelData(0);let seed=17391,low=0;
 const rnd=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/4294967296*2-1;};
 if(kind==='applause'){
  // Hand claps, boots and tables: material sounds rather than synthesized singing.
  const hits=[0,.027,.084,.13,.21,.24,.33,.38,.49,.56,.65,.78];
  for(let j=0;j<hits.length;j++)for(let i=Math.floor(hits[j]*sr);i<a.length;i++){
   const t=i/sr-hits[j];if(t>.2)break;low+=.22*(rnd()-low);
   const env=Math.min(1,t/.0015)*Math.exp(-t*(j%4===0?26:48));
   a[i]+=(j%4===0?low*.5+Math.sin(TAU*95*t)*.16:(rnd()-low)*.27)*env*(1-hits[j]*.5);
  }
 }else{
  for(let i=0;i<a.length;i++){const t=i/sr;low+=.18*(rnd()-low);let z=0;
   if(kind==='clap'){for(const delay of [0,.018,.047]){const age=t-delay;if(age>=0)z+=(rnd()-low)*.26*Math.exp(-age*45);}}
   else if(kind==='stomp')z=(Math.sin(TAU*79*t)*.36+low*.7)*Math.exp(-t*24);
   else if(kind==='coin')z=(Math.sin(TAU*1234*t)*.25+Math.sin(TAU*2117*t)*.12+Math.sin(TAU*2949*t)*.06)*Math.exp(-t*27)+low*.16*Math.exp(-t*60);
   else z=low*.8*Math.exp(-t*35)+Math.sin(TAU*185*t)*.29*Math.exp(-t*24)+Math.sin(TAU*720*t)*.10*Math.exp(-t*37)+Math.sin(TAU*1183*t)*.06*Math.exp(-t*42);
   a[i]=z*Math.min(1,t/.002)*Math.min(1,(len-t)/.025);
  }
 }
 return BP_CROWD_BUFFERS[kind]=b;
}
function bpCrowdStop(d){
 for(const n of d.crowdNodes||[]){try{n.source.stop();}catch(e){}n.source.disconnect();n.gain.disconnect();n.pan.disconnect();}
 d.crowdNodes=new Set();if(d.crowdBus)d.crowdBus.disconnect();d.crowdBus=null;
}
function bpCrowdSound(d,kind,volume,pan=0){
 if(!AC||muted||!SFX.on||SFX.user<=0||d.paused||d.phase!=='active'||AC.currentTime<d.startAt)return false;
 if(!d.crowdBus){d.crowdBus=AC.createGain();d.crowdBus.connect(AC.destination);d.crowdNodes=new Set();}
 d.crowdBus.gain.value=SFX.user;
 const source=AC.createBufferSource(),gain=AC.createGain(),p=AC.createStereoPanner(),node={source,gain,pan:p};source.buffer=bpCrowdBuffer(kind);gain.gain.value=volume;p.pan.value=pan;source.connect(gain);gain.connect(p);p.connect(d.crowdBus);d.crowdNodes.add(node);
 source.onended=()=>{source.disconnect();gain.disconnect();p.disconnect();d.crowdNodes.delete(node);};source.start();return true;
}
function bpCrowdTick(d,t){
 const prev=d.crowdLastT;d.crowdLastT=t;
 if(d.crowdBus)d.crowdBus.gain.setTargetAtTime(muted||!SFX.on?0:SFX.user,AC.currentTime,.025);
 if(prev===undefined||t<=prev||t-prev>.5)return; // Never replay a backlog after a seek.
 const s=bpState(d,t);if(s.hush||s.bow)return;
 const event=d.streakEvent;
 if(event&&event!==d.streakCheeredEvent&&t>=event.t){
  d.streakCheeredEvent=event;
  if(t-event.t<.4)bpCrowdSound(d,event.tier>=3?'applause':'clap',event.tier>=3?.18:.12,0);
 }
 const bet=bpBettingState(d,t,s);if(bet.active)for(const offset of bet.pay?[1.3,1.48,1.66]:[1.3])if(prev<bet.start+offset&&t>=bet.start+offset)bpCrowdSound(d,'coin',.22,-.65);
 const cue=(d.chart.cues||[]).find(q=>q.t>prev&&q.t<=t&&['barrel','cook','guard','chorus','uprising','encore','chair','boot','roof'].includes(q.type));
 if(cue){bpCrowdSound(d,['barrel','cook','chair','boot'].includes(cue.type)?'mug':'applause',cue.type==='uprising'?.25:.19,cue.type==='cook'?-.6:.4);}
 const beat=s.beat.index,oldBeat=bpBeat(d,prev).index;
 if(bpStompActive(s)&&beat!==oldBeat){
  bpCrowdSound(d,'stomp',bpHouseActive(s)?.36:.32,beat%2?-.35:.35);
  if(bpHouseActive(s)&&beat%2===0)bpCrowdSound(d,'mug',.12,beat%4?-.6:.6);
 }
 if(d.tableHype)for(const offset of [.55,.73,.91])if(prev<d.tableHype.t+offset&&t>=d.tableHype.t+offset)bpCrowdSound(d,'coin',.16,-.45);
 if(beat!==oldBeat&&s.progress>.38){
  if(beat%(s.heat>.75?2:8)===0)bpCrowdSound(d,'clap',.10+s.heat*.10,beat%3===0?-.55:.55);
  if(beat%13===5)bpCrowdSound(d,'mug',.17,beat%2?-.7:.7);
 }
}
function bpStompActive(s){return !s.hush&&!s.bow&&!!(s.floor||s.crowd&&s.crowd.stomping);}
function bpHouseActive(s){return !s.hush&&!s.bow&&!!(s.crowd&&s.crowd.stomping);}
function bpChandelierSwing(s){
 const base=Math.sin((s.beat.index+s.beat.phase)*Math.PI*.5);
 return base*Math.max((s.roof?.16:.055+s.heat*.09)*(1-.92*s.focus),bpHouseActive(s)?.15:0);
}
function bpHouseDebris(c,s){
 if(!bpHouseActive(s))return;
 // Deterministic plaster/splinters stay above the performers and note board.
 // Each beat shakes a different beam; no full-screen flash or UI transform.
 c.save();c.beginPath();c.rect(15,56,930,150);c.clip();
 const phase=s.beat.phase,beat=s.beat.index;
 for(let i=0;i<18;i++){
  const u=phase-i%3*.065;if(u<0)continue;
  const x=45+(i*137+beat*73)%870+Math.sin(i*2.1+u*4)*8;
  const y=61+i%4*7+u*u*(105+i%5*17);
  c.globalAlpha=Math.max(0,1-u)*.85;
  cbPoly(c,[{x:x-2,y},{x:x+3+i%3,y:y+1},{x:x+1,y:y+5},{x:x-3,y:y+3}],i%3?'#bca383':'#785335');
 }
 c.globalAlpha=.55;
 for(let i=0;i<5;i++){const x=140+i*163;c.strokeStyle='#38271e';c.lineWidth=2;c.beginPath();c.moveTo(x,57);c.lineTo(x+8,64);c.lineTo(x+3,70);c.lineTo(x+12,75);c.stroke();}
 c.restore();
}
function bpFloorStomp(s,i){
 if(!bpStompActive(s)||!(bpHouseActive(s)?i>=13&&i<30&&![13,14,21,22].includes(i):[17,19,20,23,25,29].includes(i)))return null;
 const phase=s.beat.phase,hop=phase>.55?Math.sin((phase-.55)/.45*Math.PI)*(bpHouseActive(s)?10:7):0;
 return {hop,frame:hop>2?2:0,impact:phase<.22?1-phase/.22:0,face:s.crowd&&s.crowd.stomping?(s.crowd.bardPercent>=80?-1:1):0};
}
function bpStompDust(c,x,y,impact){
 if(impact<=0)return;c.save();c.globalAlpha=impact*.85;
 for(const side of [-1,1]){
  const spread=(1-impact)*13;
  for(let k=0;k<3;k++){
   const xx=x+side*(9+k*5+spread),yy=y-1-k%2*3;
   cbPoly(c,[{x:xx-3,y:yy},{x:xx,y:yy-3-k%2},{x:xx+5,y:yy+1},{x:xx+1,y:yy+3}],'#b18d5b');
  }
  cbRect(c,x+side*16-11,y+3,22,2,'#be8d53');
 }
 c.restore();
}

