 function batch(parent){const groups=new Map();for(const child of parent.children.slice()){if(!child.isMesh||cloth.some(q=>q.mesh===child))continue;child.updateMatrix();const geo=child.geometry.clone();geo.applyMatrix4(child.matrix);if(!groups.has(child.material))groups.set(child.material,[]);groups.get(child.material).push(geo);parent.remove(child);child.geometry.dispose();}for(const [mat,list] of groups){const geo=T.BufferGeometryUtils.mergeBufferGeometries(list,false);list.forEach(g=>g.dispose());const m=new T.Mesh(geo,mat);m.castShadow=true;parent.add(m);}}
 batch(horse);batch(tail);for(const l of legs){batch(l.leg);batch(l.lower);}
