function renderMountedHalberd(p){if(p.halHorse)p.halHorse.root.visible=false;return;/* horse retired on mobile: Impaling Charge is back */if(p.stance!=='hal'){if(p.halHorse)p.halHorse.root.visible=false;return;}const h=ensureHalHorse(p),c=p.halCharge&&p.halCharge.mounted?p.halCharge:null,exit=p.halMountExit,leaving=exit&&G.t-exit.born<.6;h.root.visible=true;h.horse.visible=!!c||!!leaving;const a=c?c.a:p.yaw,lift=c?13*clamp(c.t/.35,0,1):0;// Place the authored shield against the animated torso with its face outward.
 p.mesh.updateMatrixWorld(true);const chest=p.mesh.getObjectByName('chest')||p.mesh.getObjectByName('spine');
 const anchor=chest?chest.getWorldPosition(new T.Vector3()):new T.Vector3(p.x,gAt(p.x,p.z)+13,p.z);
 h.shield.position.copy(anchor).add(new T.Vector3(-Math.cos(p.yaw)*6.4,1.1+lift,-Math.sin(p.yaw)*6.4));
 h.shield.rotation.set(.10,-Math.PI/2-p.yaw,-.10);h.shield.visible=!p.dying&&!(p.poly>0);

 if(!c&&!leaving)return;const t=c?c.t:G.t-exit.born,approach=c?Math.max(0,1-c.t/.35)*34:-(G.t-exit.born)*95,x=(c?p.x:exit.x)-Math.cos(a)*approach,z=(c?p.z:exit.z)-Math.sin(a)*approach;h.horse.position.set(x,gAt(x,z)+Math.abs(Math.sin(t*16))*.5,z);h.horse.rotation.y=-(c?c.a:exit.a);for(const q of h.legs){q.leg.rotation.z=Math.sin(t*16+q.phase)*.7;q.lower.rotation.z=Math.max(0,Math.sin(t*16+q.phase+1))*.9;}h.tail.rotation.z=Math.sin(t*9)*.16;h.tail.rotation.x=Math.sin(t*7)*.12;
 for(const q of h.cloth){const pos=q.mesh.geometry.attributes.position;for(let i=0;i<pos.count;i++){const x=q.base[i*3],y=q.base[i*3+1],z=q.base[i*3+2],weight=clamp((16-y)/9,0,1);pos.setXYZ(i,x-Math.sin(t*14+x*.45)*weight*.32,y+Math.sin(t*14+x*.45)*weight*.16,z+Math.sign(z)*Math.sin(t*14+x*.45)*weight*.30);}pos.needsUpdate=true;}

 if(c){p.mesh.position.y+=lift+Math.sin(t*16)*.35;for(const side of ['r','l']){const upper=p.mesh.getObjectByName('upperleg'+side),lower=p.mesh.getObjectByName('lowerleg'+side);if(upper){upper.rotation.x-=1;upper.rotation.z+=(side==='r'?-1:1)*.28;}if(lower)lower.rotation.x+=1.2;}}}
