  const center=box.getCenter(new T.Vector3()),cam=new T.OrthographicCamera(-20,20,20,-20,.1,300);cam.position.copy(center).add(new T.Vector3(.35,.16,1).normalize().multiplyScalar(100));cam.lookAt(center);cam.updateMatrixWorld(true);const projected=new T.Box3();for(const point of points)projected.expandByPoint(point.applyMatrix4(cam.matrixWorldInverse));const size=projected.getSize(new T.Vector3()),half=Math.max(size.x,size.y)*.55;cam.left=cam.bottom=-half;cam.right=cam.top=half;cam.updateProjectionMatrix();
  if(!thumbR){thumbR=new T.WebGLRenderer({antialias:true,alpha:true});thumbR.setPixelRatio(1);thumbR.outputEncoding=T.sRGBEncoding;}thumbR.setSize(400,400,false);thumbR.render(sc,cam);c.getContext('2d').drawImage(thumbR.domElement,0,0);BUILD_THUMBS.set(key,c);
