// Sword & Board: brief, fully protected pushing; vulnerable during fixed recovery.
const SHIELD_PUSH={duration:5,cooldown:12,capacity:8,tapGain:.28,tapGap:.16,effortDecay:.10};
function shieldPushFront(e,s=G.p.shieldPush){
 if(!s||!e||e.dead||e.phased||e.tavern)return false;
 const p=G.p,dx=e.x-p.x,dz=e.z-p.z,f=dx*Math.cos(s.a)+dz*Math.sin(s.a),side=-dx*Math.sin(s.a)+dz*Math.cos(s.a);
 return f>0&&f<42+e.r&&Math.abs(side)<23+e.r;
}
function shieldPushReady(s=G.p.shieldPush){return !!(s&&s.struggling&&s.pressure>0&&G.t>=s.nextShove);}
function shieldPushPress(){
 if(!G||G.state!=='play')return false;const p=G.p;if(p.stance!=='sb'||p.dying||p.dash>0||p.leap>0)return false;
 if(p.shieldPush){const s=p.shieldPush;
  if(G.t>=s.until){endShieldPush();return false;}
  // Each fresh press contributes once. Holding, idle taps and simultaneous fingers cannot auto-heave.
  if(!shieldPushReady(s)||G.t-s.lastTap<SHIELD_PUSH.tapGap)return false;
  s.lastTap=G.t;s.tapAt=G.t;s.effort=Math.min(1,s.effort+SHIELD_PUSH.tapGain);
  if(s.effort>=1){shieldPushShove(true,false);s.nextShove=G.t+.8;}
  else sfx('shield',{force:true});
  mobileHud();return true;
 }
 if(p.actionCd>0)return false;
 const a=joy.active&&Math.hypot(joy.dx,joy.dy)>.15?Math.atan2(joy.dy,joy.dx)+camYaw:p.aim;
 p.counterUntil=0;p.shieldPush={a,born:G.t,until:G.t+SHIELD_PUSH.duration,nextShove:G.t+.8,pressure:0,targets:[],tick:0,step:0,effort:0,struggling:false,lastTap:-10,tapAt:-10};
 p.atkT=0;p.actionUsed=(p.actionUsed||0)+1;sfx('shield',{force:true});return true;
}
function shieldPushRelease(cancel=false){
 // A tap activates the complete brace. Only explicit cancellation (dash, pause, blur) ends it early.
 if(cancel)endShieldPush();
}
function endShieldPush(){
 const p=G&&G.p;if(!p||!p.shieldPush)return;
 p.shieldPush=null;p.actionCd=SHIELD_PUSH.cooldown;p.actionMax=p.actionCd;
 restoreShieldPushPose(p);for(const e of G.enemies)e.shieldHeldUntil=0;
}
function shieldPushMove(o,dx,dz){
 const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/3));let moved=0;
 for(let i=0;i<steps;i++){const x=o.x,z=o.z,nx=x+dx/steps,nz=z+dz/steps;
  if(hAt(nx,nz)<WATER_Y+2)break;
  o.x=nx;o.z=nz;const blocked=keepInBounds(o,o.r||7);
  // Preserve collision sliding for the hero. Reverting both axes made a braced hero stick to scenery.
  if((blocked&&o!==G.p)||hAt(o.x,o.z)<WATER_Y+2){o.x=x;o.z=z;break;}
  moved+=Math.hypot(o.x-x,o.z-z);
 }return moved;
}
function shieldPushShove(strong,finish){
 const p=G.p,s=p.shieldPush;if(!s)return;const c=Math.cos(s.a),sn=Math.sin(s.a),dmg=(12+(p.ranks.shield||0)*5+p.armor*.5)*p.dmg*(strong?1.65:1);
 for(const e of G.enemies){if(!shieldPushFront(e,s))continue;
  e.shieldHeldUntil=0;e.shieldReleasedUntil=G.t+.6;
  hitEnemy(e,dmg,c*(strong?230:125),sn*(strong?230:125),true);
  if(e.boss||e.affix==='juggernaut'){shieldPushMove(e,c*(strong?4:1.5),sn*(strong?4:1.5));}
  else if(!e.dead){e.shieldLaunch={until:G.t+.55,damage:dmg*.45,seen:new Set(),a:s.a};applyEnemyStun(e,strong?.45:.2);}
 }
 if(strong){if(p.rm.shoveSword)p.shoveSwordUntil=G.t+4;if(p.setB==='bulwark'&&p.wallT>0&&(p.wallExtension||0)<3){p.wallT+=1;p.wallExtension=(p.wallExtension||0)+1;}}
 s.heaveAt=G.t;s.targets=[];s.pressure=0;s.effort=0;s.struggling=false;
 if(strong)shieldPushMove(p,c*7,sn*7);
 p.shieldShoveUntil=G.t+.32;p.shieldShoveAim=s.a;
 fx('shieldheave',{x:p.x,z:p.z,a:s.a,r:45,dur:.32,strong:!!strong});
 dust(p.x+c*12,p.z+sn*12,strong?6:3,16);sfx(strong?'heavy':'shield',{force:true});G.shake=Math.max(G.shake,strong?2:1);
 commandFeedback(strong?'HEAVE!':'SHOVE');if(finish)endShieldPush();
}
function tickShieldPush(dt,mx,mz){
 const p=G.p,s=p.shieldPush;if(!s)return;
 if(p.stance!=='sb'||p.dying||p.dash>0){endShieldPush();return;}
 if(G.t>=s.until){shieldPushShove(false,true);return;}
 const input=Math.hypot(mx,mz);let aim=s.a;
 if(aimJoy.active&&Math.hypot(aimJoy.dx,aimJoy.dy)>.16)aim=Math.atan2(aimJoy.dy,aimJoy.dx)+camYaw;
 else if(input>.15)aim=Math.atan2(mz,mx);
 s.a+=clamp(angDiff(aim,s.a),-1.65*dt,1.65*dt);p.aim=s.a;
 const foes=G.enemies.filter(e=>shieldPushFront(e,s)&&!(e.shieldReleasedUntil>G.t));
 foes.sort((a,b)=>{const ai=s.targets.indexOf(a),bi=s.targets.indexOf(b);if(ai>=0||bi>=0)return (ai<0?99:ai)-(bi<0?99:bi);return Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z);});
 s.targets=foes.slice(0,SHIELD_PUSH.capacity);s.pressure=s.targets.reduce((n,e)=>n+(e.boss?5:e.affix==='juggernaut'?3:e.def.elite?2:1),0);
 const c=Math.cos(s.a),sn=Math.sin(s.a),strength=input>.1?Math.min(input,1):0;
 const vx=strength?mx/input*23*strength:0,vz=strength?mz/input*23*strength:0;
 const baseSpeed=vx*c+vz*sn-s.pressure*4.2;
 // The struggle begins with real crowd pressure, not a timed gold cue.
 if(!s.pressure){s.struggling=false;s.effort=0;}
 else if(baseSpeed<0&&G.t>=s.nextShove)s.struggling=true;
 s.effort=Math.max(0,s.effort-SHIELD_PUSH.effortDecay*dt);
 const resist=s.struggling?s.effort*24:0,speed=baseSpeed+resist;
 // Feet follow the stick immediately; shield facing can turn with weight without locking movement.
 const dx=(vx+c*(resist-s.pressure*4.2))*dt,dz=(vz+sn*(resist-s.pressure*4.2))*dt;
 const moved=shieldPushMove(p,dx,dz);s.pushSpeed=speed;p.moving=moved>dt;if(p.moving)p.moveAng=Math.atan2(dz,dx);
 s.step+=moved*.25;
 let slot=0;for(const e of s.targets){if(e.boss||e.affix==='juggernaut')continue;
  const row=Math.floor(slot/3),side=[0,-13,13][slot%3],front=p.r+e.r+2+row*13;
  e.shieldHeldUntil=G.t+.08;e.shieldSlot={x:p.x+c*front-sn*side,z:p.z+sn*front+c*side};slot++;
 }
 s.tick-=dt;if(s.tick<=0){s.tick=.65;for(const e of s.targets){const power=(5+(p.thornsBase||0)*3+p.armor*.35)*p.dmg;
   hitEnemy(e,power,0,0,true);if(!e.dead&&p.thornsBase)status(e,'bleed',power*.18,2);
  }if(s.pressure){dust(p.x-c*5,p.z-sn*5,2,9);sfx('shield',{x:p.x,z:p.z});}}
}
function constrainShieldEnemy(e,dt){
 if(e.shieldHeldUntil>G.t&&G.p.shieldPush&&e.shieldSlot&&!e.dead){
  const dx=e.shieldSlot.x-e.x,dz=e.shieldSlot.z-e.z,d=Math.hypot(dx,dz),step=Math.min(d,90*dt);
  if(d>0)shieldPushMove(e,dx/d*step,dz/d*step);e.kx=e.kz=0;
 }
 const launch=e.shieldLaunch;if(!launch)return;if(G.t>=launch.until||e.dead){e.shieldLaunch=null;return;}
 for(const o of G.enemies){if(o===e||o.dead||o.boss||o.phased||o.tavern||launch.seen.has(o)||launch.seen.size>=3)continue;
  if(Math.hypot(o.x-e.x,o.z-e.z)<o.r+e.r+2){launch.seen.add(o);hitEnemy(o,launch.damage,Math.cos(launch.a)*75,Math.sin(launch.a)*75,true);}}
}
function shieldPushProtected(p=G.p){const s=p.shieldPush;return !!(p.stance==='sb'&&s&&!p.dying&&p.dash<=0&&G.t<s.until);}
function restoreShieldPushPose(p){const r=p.mesh&&p.mesh.userData.shieldPushRig;if(!r||!r.saved)return;for(const a of r.nodes){a.node.position.copy(a.pos);a.node.quaternion.copy(a.q);a.node.scale.copy(a.scale);a.node.visible=a.visible;}r.saved=false;}
function renderShieldPush(p){
 const s=p.shieldPush,heave=p.shieldShoveUntil>G.t;if(p.stance!=='sb'||p.dying||(!s&&!heave))return;
 let r=p.mesh.userData.shieldPushRig;if(!r){const names=['hips','spine','chest','head','upperarml','lowerarml','wristl','handl','upperarmr','lowerarmr','wristr','handr','1H_Sword','upperlegl','upperlegr','lowerlegl','lowerlegr','Round_Shield'];r={nodes:[],bones:{},root:p.mesh,frame:p.mesh.getObjectByName('root'),basis:new T.Matrix4()};for(const k of ['shoulder','elbow','wrist','axis','side','work','to','from','hinge','basisX','target','pole'])r[k]=new T.Vector3();for(const k of ['rotation','parentQ','handQ','frameQ'])r[k]=new T.Quaternion();
  for(const name of names){const node=p.mesh.getObjectByName(name);if(node){r.bones[name]=node;r.nodes.push({node,pos:node.position.clone(),q:node.quaternion.clone(),scale:node.scale.clone(),visible:node.visible});}}r.arms=['l','r'].map(side=>({side,upper:r.bones['upperarm'+side],lower:r.bones['lowerarm'+side],wrist:r.bones['wrist'+side],hand:r.bones['hand'+side]}));p.mesh.userData.shieldPushRig=r;}
 for(const a of r.nodes){a.pos.copy(a.node.position);a.q.copy(a.node.quaternion);a.scale.copy(a.node.scale);a.visible=a.node.visible;}r.saved=true;
 const b=r.bones,pressure=s?Math.min(1,s.pressure/8):0,step=s?Math.sin(s.step*3):0,pulse=heave?Math.sin((p.shieldShoveUntil-G.t)/.32*Math.PI):0,strain=Math.sin(G.t*25)*pressure*.025;
 b.hips.position.y-=.035+pressure*.02;b.spine.rotation.x+=.20+pressure*.12-pulse*.14;b.chest.rotation.x+=.10+strain;b.head.rotation.x-=.16;
 b.upperlegl.rotation.x+=.22+step*.14;b.upperlegr.rotation.x+=.22-step*.14;b.lowerlegl.rotation.x-=.30+Math.max(0,step)*.12;b.lowerlegr.rotation.x-=.30+Math.max(0,-step)*.12;
 p.mesh.rotation.y=-(s?s.a:p.shieldShoveAim)+Math.PI/2;
 r.root.updateMatrixWorld(true);r.frame.getWorldQuaternion(r.frameQ);
 for(const arm of r.arms){const sign=arm.side==='l'?1:-1;
  r.target.set(sign*.17,.91,.43+pulse*.10-pressure*.025).applyMatrix4(r.frame.matrixWorld);
  r.pole.set(sign*.48,.68,.18).applyMatrix4(r.frame.matrixWorld);
  r.handQ.copy(r.frameQ);greatswordArm(r,arm,r.target,r.handQ,r.pole);
 }
 if(b['1H_Sword'])b['1H_Sword'].visible=false;
 const sh=b.Round_Shield;if(sh){sh.scale.multiplyScalar(1.14);r.root.updateMatrixWorld(true);
  r.target.set(.02,.94,(p.mesh.userData.sharedWarrior?1.10:.64)+pulse*.13-pressure*.035).applyMatrix4(r.frame.matrixWorld);sh.position.copy(sh.parent.worldToLocal(r.target));
  r.handQ.setFromEuler(new T.Euler(-pressure*.12+strain,0,0));r.handQ.premultiply(r.frameQ);sh.parent.getWorldQuaternion(r.parentQ);sh.quaternion.copy(r.parentQ.invert().multiply(r.handQ));
 }

}
function shieldPushHud(){
 const el=$('shieldPushHud'),button=$('mobilePrimary');if(!el||!G)return;const p=G.p,s=p.shieldPush,active=G.state==='play'&&!!s;
 el.hidden=!active;if(button){button.dataset.struggle=active&&s.struggling?'yes':'no';button.dataset.shieldTap=active&&G.t-s.tapAt<.12?'yes':'no';}if(!active)return;
 const struggle=s.struggling,heave=s.heaveAt!==undefined&&G.t-s.heaveAt<.5;
 el.dataset.cue=struggle?'yes':'no';el.dataset.mode=heave?'heave':struggle?'struggle':'brace';
 el.querySelector('b').textContent=heave?'LINE BROKEN':struggle?'PUSH BACK':'SHIELD BRACED';
 el.querySelector('.shieldPushHint').textContent=heave?'Heave! Keep steering':struggle?'Tap Push repeatedly to heave':'Steer into the crowd';
 el.querySelector('.shieldPushTime').textContent=Math.max(0,s.until-G.t).toFixed(1)+'s protected';
 el.querySelector('.shieldPushProgress').hidden=!struggle;
 const meter=el.querySelector('[role="progressbar"]'),pct=Math.round(s.effort*100);meter.setAttribute('aria-valuenow',pct);meter.querySelector('i').style.width=pct+'%';
 el.querySelector('.shieldPushValue').textContent=pct+'%';
}

// Mobile Bastion: a moving turret escort with a mounted central cannon.
const CLOCKWORK_COVER={radius:42,slow:.3};
const BASTION_CANNON={speed:250,range:200,radius:4.5,blast:30,splash:.5,cooldown:1.05};
function clockworkCoverSlow(e){
 const p=G.p;
 if(p.stance!=='k_clock'||!p.rm.turretCover||e.dead||e.boss||e.def.elite||e.def.encounterObject||e.hunter||e.affix==='juggernaut'||e.phased||e.tavern||e.tavernRequired)return 0;
 return G.sentries.some(s=>s.t>0&&Math.hypot(e.x-s.x,e.z-s.z)<CLOCKWORK_COVER.radius+e.r*.5)?CLOCKWORK_COVER.slow:0;
}
function bastionCannonDamage(p){return (60+12*(p.ranks.sentry||1))*p.dmg;}
function fireBastionCannon(target){
 const p=G.p,a=Math.atan2(target.z-p.z,target.x-p.x),art=bastionModel();
 art.root.position.set(p.x,gAt(p.x,p.z),p.z);
 const muzzle=clockworkFire(art.root,a,false);
 const pr=shootDir(p.x,p.z,a,BASTION_CANNON.speed,bastionCannonDamage(p),'cannonball',0,BASTION_CANNON.range/BASTION_CANNON.speed);
 if(p.setB==='clockwork'&&p.mobileBastion?.siegeShots>0){p.mobileBastion.siegeShots--;pr.dmg*=2;pr.siegeShot=true;itemCount('siegeCannonShots');}
 pr.bastionCannon=true;pr.bastionShot=true;pr.r=BASTION_CANNON.radius;pr.area=p.area;
 clockworkProjectile(pr,muzzle);
 cannonFx('muzzle',muzzle.x,muzzle.z,muzzle.y,a,16);if(pr.siegeShot)fx('reavercue',{x:muzzle.x,z:muzzle.z,y:muzzle.y,a,r:20,dur:.3,siege:true});
 sfx('cannonfire',{x:p.x,z:p.z,force:true});itemCount('cannonShots');
 p.aim=a;G.shake=Math.max(G.shake,.8);return pr;
}
function cannonSegmentEntry(pr,e,dx,dz){
 const ox=pr.x-e.x,oz=pr.z-e.z,r=e.r+pr.r,c=ox*ox+oz*oz-r*r;
 if(c<=0)return 0;
 const a=dx*dx+dz*dz;if(a<=0)return null;
 const b=ox*dx+oz*dz,disc=b*b-a*c;if(disc<0)return null;
 const t=(-b-Math.sqrt(disc))/a;return t>=0&&t<=1?t:null;
}
function cannonImpact(pr,primary){
 if(pr.cannonImpacted)return;pr.cannonImpacted=true;
 const radius=BASTION_CANNON.blast*pr.area,targets=G.enemies.filter(e=>!e.dead&&!e.phased&&!e.tavern&&!e.tavernRequired&&(e===primary||Math.hypot(e.x-pr.x,e.z-pr.z)<radius+e.r));
 SFX.area++;
 try{for(const e of targets){
  const heavy=e.boss||e.def.elite||e.hunter||e.affix==='juggernaut'||e.def.encounterObject;
  const a=e===primary?pr.a:Math.atan2(e.z-pr.z,e.x-pr.x),force=heavy?0:(e===primary?125:80);
  const hp=Math.max(0,e.hp),damage=pr.dmg*(e===primary?1:BASTION_CANNON.splash);
  // The primary hit is not also charged splash damage. No fragment chains.
  hitEnemy(e,damage,Math.cos(a)*force,Math.sin(a)*force,true,false,false,false,{kind:'bastion',originX:pr.x-Math.cos(pr.a)*8,originZ:pr.z-Math.sin(pr.a)*8,siege:!!pr.siegeShot});
  itemCount('cannonDamage',Math.max(0,hp-Math.max(0,e.hp)));
  itemCount(e===primary?'cannonDirectHits':'cannonSplashHits');
  if(!e.dead){e.machineMarkUntil=G.t+3;status(e,'mark',0,3);}
 }}finally{SFX.area--;}
 hitTrees(pr.x,pr.z,radius);
 cannonFx('impact',pr.x,pr.z,gAt(pr.x,pr.z)+Math.min(12,pr.y),pr.a,radius);
 sfx('cannonhit',{x:pr.x,z:pr.z,force:true});
}
function tickBastionCannon(pr,dt){
 const step=Math.min(dt,Math.max(0,pr.life)),dx=pr.vx*step,dz=pr.vz*step;
 let target=null,entry=Infinity;
 for(const e of G.enemies){
  if(e.dead||e.phased||e.tavern||e.tavernRequired)continue;
  const t=cannonSegmentEntry(pr,e,dx,dz);if(t!==null&&t<entry){entry=t;target=e;}
 }
 const move=target?entry:1,fromX=pr.x,fromZ=pr.z;pr.x+=dx*move;pr.z+=dz*move;pr.life-=dt;
 if(TREES.length)hitTreesLine(fromX,fromZ,pr.a,Math.hypot(pr.x-fromX,pr.z-fromZ),pr.r);
 if(target){cannonImpact(pr,target);return true;}
 if(pr.life<=0)return true;
 pr.cannonTrail=(pr.cannonTrail||0)-dt;
 if(pr.cannonTrail<=0&&skillVfxVisible(pr.x,pr.z)){pr.cannonTrail=.075;emit(pr.x,gAt(pr.x,pr.z)+pr.y,pr.z,1,{kind:'smoke',col:'#807768',colEnd:'#454446',spd:3,up:.1,life:.2,size:3.2,grav:0});}
 return false;
}

let CANNON_ART=null;
function cannonArt(){
 if(CANNON_ART)return CANNON_ART;
 const ball=new T.IcosahedronGeometry(4.5,2),small=new T.IcosahedronGeometry(1,1);
 const band=new T.TorusGeometry(4.48,.17,4,24);
 const iron=new T.MeshLambertMaterial({color:'#49525b',flatShading:true});
 const ink=new T.MeshBasicMaterial({color:'#171b22',side:T.BackSide});
 const brass=new T.MeshLambertMaterial({color:'#ae9663',flatShading:true});
 const highlight=new T.MeshLambertMaterial({color:'#a3a8a8',flatShading:true});
 const arcs=[];for(let i=0;i<4;i++)arcs.push(new T.RingGeometry(40.8,42,12,1,i*Math.PI/2+.18,1.12));
 const cover=T.BufferGeometryUtils.mergeBufferGeometries(arcs,false);arcs.forEach(g=>g.dispose());cover.rotateX(-Math.PI/2);
 const coverMat=new T.MeshBasicMaterial({color:'#b7a16a',transparent:true,opacity:.22,depthWrite:false,side:T.DoubleSide});
 const spike=new T.ConeGeometry(1,1,3);spike.translate(0,.5,0);
 return CANNON_ART={ball,small,band,iron,ink,brass,highlight,cover,coverMat,spike};
}
function cannonballMesh(){
 const A=cannonArt(),g=new T.Group(),ball=new T.Mesh(A.ball,A.iron),outline=new T.Mesh(A.ball,A.ink);outline.scale.setScalar(1.075);g.add(outline,ball);
 const seam=new T.Mesh(A.band,A.brass);seam.rotation.y=Math.PI/2;g.add(seam);
 const light=new T.Mesh(A.small,A.highlight);light.position.set(-1.2,2.8,2.7);light.scale.set(1.2,.5,.8);g.add(light);
 return g;
}
function renderClockworkCover(s){
 const enabled=G.p.stance==='k_clock'&&G.p.rm.turretCover&&s.t>0;
 if(!enabled){if(s.coverArt)s.coverArt.visible=false;return;}
 if(!s.coverArt){const A=cannonArt();s.coverArt=new T.Mesh(A.cover,A.coverMat);s.coverArt.position.y=.22;s.mesh.add(s.coverArt);}
 s.coverArt.visible=skillVfxVisible(s.x,s.z);
}
function cannonFx(kind,x,z,y,a,r){
 if(!skillVfxVisible(x,z))return;
 // Keep effects bounded even if other systems trigger a burst of impacts.
 if(G.fx.filter(f=>f.type==='cannonfx').length>=12)return;
 G.fx.push({type:'cannonfx',kind,x,z,y,a,r,t:0,dur:kind==='muzzle'?.32:.48,archerOwnMaterials:true});
}
function renderCannonFx(f,k){
 const A=cannonArt(),muzzle=f.kind==='muzzle';
 if(!f.mesh){
  const g=new T.Group();f.mesh=g;g.position.set(f.x,f.y,f.z);scene.add(g);
  for(let i=0;i<7;i++){
   const mat=new T.MeshBasicMaterial({color:i%2?'#d1b38a':'#f4ddb0',transparent:true,depthWrite:false});
   const spike=new T.Mesh(A.spike,mat),a=i/7*TAU+.2;spike.userData.angle=a;spike.userData.ray=1;spike.rotation.z=-a;g.add(spike);
  }
  for(let i=0;i<6;i++){
   const mat=new T.MeshLambertMaterial({color:i%2?'#827e72':'#b9ad94',transparent:true,depthWrite:false,flatShading:true});
   const cloud=new T.Mesh(A.small,mat);cloud.userData.smoke=i+1;g.add(cloud);
  }
  for(let i=0;i<5;i++){
   const mat=new T.MeshLambertMaterial({color:'#625c50',transparent:true,flatShading:true});
   const chip=new T.Mesh(A.small,mat);chip.userData.chip=i+1;g.add(chip);
  }
 }
 const g=f.mesh,early=Math.max(0,1-k*3.5),spread=(muzzle?8:f.r)*Math.sin(k*Math.PI/2);
 // Burst faces the camera, while dust and fragments remain in world space.
 for(const m of g.children){const U=m.userData;
  if(U.ray){m.visible=early>0;m.quaternion.copy(camera.quaternion);m.rotateZ(-U.angle);m.scale.set((muzzle?2:3)*early,(muzzle?12:18)*(1-early*.4),1);m.material.opacity=early*.85;}
  else if(U.smoke){const i=U.smoke,a=i*2.399+f.a,d=spread*(.35+(i%3)*.2);m.position.set(Math.cos(a)*d,2+k*9-(muzzle?0:4),Math.sin(a)*d);const size=(muzzle?2:3)+k*(muzzle?4:7);m.scale.set(size,size*.65,size);m.material.opacity=(1-k)*.42;}
  else {const i=U.chip,a=f.a+i*2.399,d=spread*(.6+i*.07);m.position.set(Math.cos(a)*d,Math.sin(k*Math.PI)*(muzzle?5:12)-k*4,Math.sin(a)*d);m.scale.setScalar((muzzle?.55:.85)*(1-k));m.rotation.set(k*8+i,k*11,k*5);m.material.opacity=1-k;}
 }
}

const MOBILE_BASTION={duration:10,cooldown:30,radius:34,blockRadius:11};
let bastionArt=null;
function bastionModel(){
 if(bastionArt){if(bastionArt.root.parent!==scene)scene.add(bastionArt.root);return bastionArt;}
 const root=clockworkMachine('bastion'),gun=root.userData.head;
 bastionArt={root,gun};root.visible=false;scene.add(root);return bastionArt;
}
function endMobileBastion(grantGuard=false){
 const p=G&&G.p;if(p){if(grantGuard&&p.mobileBastion&&p.stance==='k_clock'&&!p.dying&&p.hp>0){p.bastionCoverUntil=G.t+1.5;G.bastionCovers=(G.bastionCovers||0)+1;G.texts.push({x:p.x,z:p.z,y:22,t:.7,t0:.7,s:'COVERED',col:'#b9dce8'});sfx('shield',{x:p.x,z:p.z});}restoreBastionPose(p);p.mobileBastion=null;}
 if(bastionArt)bastionArt.root.visible=false;
 if(G)for(const s of G.sentries){s.bastionSlot=undefined;s.bastionGuard=false;s.siegeShots=0;}
}
function startMobileBastion(){
 if(!G||G.state!=='play')return false;const p=G.p;
 if(p.stance!=='k_clock'||p.mobileBastion||(p.mobileBastionCd||0)>0)return false;
 if(!G.sentries.length){const rank=p.ranks.sentry||0;if(!rank){commandFeedback('Learn Sentry first');return false;}deployStarterSentry(rank);p.weapons.sentry.t=UPG_BY.sentry.cd(rank)*p.cdMul;}
 p.mobileBastionCd=MOBILE_BASTION.cooldown;p.mobileBastion={until:G.t+MOBILE_BASTION.duration,shot:0,blocked:0,shots:0};
 loadSiegeSalvo(p);bastionModel().root.visible=true;positionMobileBastion();sfx('gear',{force:true});commandFeedback(p.setB==='clockwork'?'Siege Salvo!':'Bastion!');p.actionUsed=(p.actionUsed||0)+1;return true;
}
function positionMobileBastion(){
 const p=G.p;if(!p.mobileBastion)return;const n=G.sentries.length;
 G.sentries.forEach((s,i)=>{delete s.regroup;const a=i/Math.max(1,n)*TAU;s.x=p.x+Math.cos(a)*MOBILE_BASTION.radius;s.z=p.z+Math.sin(a)*MOBILE_BASTION.radius;keepInBounds(s,8);s.bastionGuard=Math.hypot(s.x-p.x,s.z-p.z)>20;s.mesh.position.set(s.x,gAt(s.x,s.z),s.z);});
}
function tickMobileBastion(dt){
 const p=G.p;p.mobileBastionCd=Math.max(0,(p.mobileBastionCd||0)-dt);const b=p.mobileBastion;if(!b)return;
 if(p.stance!=='k_clock'||p.dying||p.hp<=0||G.t>=b.until){endMobileBastion(p.stance==='k_clock'&&!p.dying&&p.hp>0&&G.t>=b.until);return;}
 positionMobileBastion();b.shot-=dt;
 if(b.shot<=0){const target=machineTarget({x:p.x,z:p.z,kind:'bastion'});if(target){fireBastionCannon(target);b.shot=BASTION_CANNON.cooldown*(p.overclockT>0?.65:1);b.shots++;}}
}
function mobileBastionIntercept(pr,x,z){
 const p=G.p,b=p.mobileBastion;if(!b||pr.life<=0)return false;
 const dx=pr.x-x,dz=pr.z-z,len=dx*dx+dz*dz;
 for(const s of G.sentries){if(!s.bastionGuard)continue;const q=len?clamp(((s.x-x)*dx+(s.z-z)*dz)/len,0,1):0;
  if(Math.hypot(x+dx*q-s.x,z+dz*q-s.z)>MOBILE_BASTION.blockRadius+(pr.r||2))continue;
  b.blocked++;pr.dmg=0;pr.onDie=null;pr.life=0;
  if(!b.sparkAt||G.t>=b.sparkAt){b.sparkAt=G.t+.08;sparks(s.x,gAt(s.x,s.z)+10,s.z,3,PC2.steel,35);sfx('shield',{x:s.x,z:s.z});}return true;
 }return false;
}
