// Device-visible frame measurements so the next phone test has a useful number.
const MOBILE_FRAMES={last:0,samples:[],active:false};
function mobileMeasureFrame(now){const f=MOBILE_FRAMES,active=G&&G.state==='play'&&!document.hidden;if(active&&f.active&&f.last){const dt=now-f.last;if(dt>0&&dt<5000){f.samples.push(dt);if(f.samples.length>180)f.samples.shift();}}f.last=now;f.active=active;}
