pauseInfo=function(){mobileOriginalPauseInfo();};

// PHONE_INVISIBLE_V1
// Preserve gameplay and art while reducing temporary allocations.
const MOBILE_REUSE={rings:[],limit:32,created:0,reused:0,returned:0,disposed:0,grid:new Map(),buckets:[],used:0};
function mobileOwnMaterial(m){m.userData.mobileOwned=true;m.addEventListener('dispose',mobileMaterialDisposed);return m;}
function mobileMaterialDisposed(){this.userData.mobileDisposed=true;}
function mobileRingMesh(col){
 const a=MOBILE_REUSE;let m=a.rings.pop();
 if(m){a.reused++;m.position.set(0,0,0);m.rotation.set(0,0,0);m.scale.set(1,1,1);m.visible=true;m.material.color.set(col||'#fff');m.material.opacity=1;}
 else{m=decal('ring',col||'#fff',true);m.userData.mobileRing=true;a.created++;}
 m.userData.mobilePooled=false;return m;
}
const mobileReleaseOriginal=releaseIceInstances;
releaseIceInstances=function(mesh){
 if(!mesh)return;
 if(mesh.userData.mobileRing){
  if(mesh.userData.mobilePooled)return;
  mesh.userData.mobilePooled=true;MOBILE_REUSE.returned++;
  if(MOBILE_REUSE.rings.length<MOBILE_REUSE.limit)MOBILE_REUSE.rings.push(mesh);
  else{mesh.material.dispose();MOBILE_REUSE.disposed++;}
  return;
 }
 mobileReleaseOriginal(mesh);
 mesh.traverse(o=>{
  if(o.userData.mobileOwnGeometry&&o.geometry){o.geometry.dispose();o.userData.mobileOwnGeometry=false;}
  const dispose=m=>{if(m&&m.userData.mobileOwned&&!m.userData.mobileDisposed){m.dispose();MOBILE_REUSE.disposed++;}};
  if(Array.isArray(o.material))for(const m of o.material)dispose(m);else dispose(o.material);
 });
};
// Select only the requested nearest targets; preserve source order on ties,
// the original range check, and command-origin ranking.
const mobileNearestOriginal=nearest;
nearest=function(x,z,n,maxd){
 if(!Number.isInteger(n)||n<0)return mobileNearestOriginal(x,z,n,maxd);
 const result=[];if(!n||!(maxd>0))return result;
 const cx=COMMAND_CAST?COMMAND_CAST.x:x,cz=COMMAND_CAST?COMMAND_CAST.z:z;const soul=stolenSoulTarget(x,z,maxd);if(soul){if(n===1)return [soul];return [soul,...mobileNearestOriginal(x,z,n,maxd).filter(e=>e!==soul)].slice(0,n);}
 if(n===1){let best=null,score=Infinity;for(const e of G.enemies){if(!combatTargetable(e))continue;const d=Math.hypot(e.x-x,e.z-z);if(!(d<maxd))continue;const s=COMMAND_CAST?Math.hypot(e.x-cx,e.z-cz):d;if(s<score){score=s;best=e;}}if(best)result.push(best);return result;}
 const scores=[];
 for(const e of G.enemies){if(!combatTargetable(e))continue;const d=Math.hypot(e.x-x,e.z-z);if(!(d<maxd))continue;const s=COMMAND_CAST?Math.hypot(e.x-cx,e.z-cz):d;let j=result.length;while(j>0&&s<scores[j-1])j--;if(j>=n)continue;result.splice(j,0,e);scores.splice(j,0,s);if(result.length>n){result.pop();scores.pop();}}
 return result;
};
// The existing separation grid keeps its exact keys/order. Reuse its bucket
// arrays rather than allocating a new array for each occupied cell each step.
function mobileSeparationGrid(){
 const a=MOBILE_REUSE;a.grid.clear();for(let i=0;i<a.used;i++)a.buckets[i].length=0;a.used=0;
 for(const e of G.enemies){if(e.tavern||e.def.encounterObject)continue;const k=((e.x/24)|0)*100000+((e.z/24)|0);let b=a.grid.get(k);if(!b){b=a.buckets[a.used]||(a.buckets[a.used]=[]);a.used++;a.grid.set(k,b);}b.push(e);}
 return a.grid;
}

