const COMIC_IMAGES=new Map(),COMIC_RELICS={};
for(const [sheet,sets]of [['archer',['pyre','rime','storm']],['warrior',['bulwark','reaver','phalanx']],['tinker',['snare','clockwork','powder']],['magic',['plague','ossuary','lullaby','resonance']]])sets.forEach((s,row)=>{for(let i=1;i<=5;i++)COMIC_RELICS[s+'_'+i]=[sheet,row*5+i-1];});
function comicImage(src){let e=COMIC_IMAGES.get(src);if(!e){const image=new Image();e={image,ready:false};e.loaded=new Promise(resolve=>{image.onload=()=>{e.ready=true;resolve(true);};image.onerror=()=>resolve(false);});COMIC_IMAGES.set(src,e);image.src=src;}return e;}
function comicCanvas(src,rect,size=600){const c=mk(size,size);c.className='comicArt';c.setAttribute('aria-hidden','true');const entry=comicImage(src);const draw=()=>{const im=entry.image,r=rect(im),scale=Math.min(size/r[2],size/r[3]),w=r[2]*scale,h=r[3]*scale,x=c.getContext('2d');x.clearRect(0,0,size,size);x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';x.drawImage(im,...r,(size-w)/2,(size-h)/2,w,h);};if(entry.ready)draw();else entry.loaded.then(ok=>{if(ok)draw();});return c;}
function comicPortrait(cls,id){const a=COMIC_ART[id||MENU_BUILDS[cls]];if(a[1]!==0||a[2]!==1)return comicCanvas(a[0],im=>[im.width/a[2]*a[1],0,im.width/a[2],im.height]);const image=new Image();image.className='comicArt comicPortrait';image.width=image.height=600;image.alt='';image.setAttribute('aria-hidden','true');image.decoding='async';image.src=a[0];return image;}
function comicAtlas(sheet,index,size=128){return comicCanvas(COMIC_SHEETS[sheet],im=>{const col=index%5,row=Math.floor(index/5);if(sheet==='archer'){const xs=[0,281,562,842,1123,1402],ys=[0,300,578,844,1122];return [xs[col],ys[row],xs[col+1]-xs[col],ys[row+1]-ys[row]];}return [im.width/5*col,im.height/4*row,im.width/5,im.height/4];},size);}
function comicRelicIcon(id,px=3){const a=COMIC_RELICS[id];if(!a)return null;const c=comicAtlas(...a);c.className='relicicon comicArt';c.style.width=c.style.height=12*px+'px';return c;}
function comicLock(){return '<svg class="comicLock" viewBox="0 0 32 36" aria-hidden="true"><path d="M8 15V10a8 8 0 0116 0v5" fill="none" stroke="#071225" stroke-width="8"/><path d="M8 15V10a8 8 0 0116 0v5" fill="none" stroke="#ffe16b" stroke-width="4"/><rect x="3" y="13" width="26" height="21" rx="4" fill="#ffc629" stroke="#071225" stroke-width="3"/><path d="M16 19v9" stroke="#14213b" stroke-width="5" stroke-linecap="round"/></svg>';}
function buildMapList(){const box=$('maplist');box.replaceChildren();for(const [i,id]of ['britannia','deceit','duskmoor'].entries()){const locked=id==='deceit'&&!deceitOpen()||id==='duskmoor'&&!duskOpen(),sel=id===menuMap,b=document.createElement('button');b.type='button';b.className='mapcard'+(sel?' sel':'')+(locked?' locked':'');b.dataset.map=id;b.setAttribute('aria-pressed',String(sel));b.setAttribute('aria-disabled',String(locked));const req=id==='deceit'?'Beat Briarford to unlock':'Beat Kings Grave to unlock';b.setAttribute('aria-label',MAPS[id].name+(locked?'. Locked. '+req:''));const im=document.createElement('img');im.src=COMIC_MAPS[id];im.alt='';im.className='chapterArt';b.append(im);const info=document.createElement('span');info.className='mapCopy';info.innerHTML='<span class="chapter">Chapter 0'+(i+1)+'</span><b>'+MAPS[id].name+'</b><small>'+(locked?req:sel?'Selected chapter':clearLabel(clearRecord(relicCls,id)))+'</small>';b.append(info);const mark=document.createElement('span');mark.className='mapMark';mark.innerHTML=locked?comicLock():sel?'✓':'›';b.append(mark);b.onclick=()=>{if(locked)return;if(menuMap!==id){menuMap=id;MAP=MAPS[id];music(id);$('menusub').textContent=MAPS[id].sub;}buildMapList();buildClassInfo();sfx('coin');};box.append(b);}buildClassBadges();syncMobileMap();}
