function openHeroRoster(on=true){
 if(on)showPage('play');
 const menu=$('menu'),roster=$('rosterArea');
 roster.classList.toggle('open',on);roster.setAttribute('aria-hidden',String(!on));menu.classList.toggle('rosterOpen',on);
 if(on||menu.dataset.page==='heroes')menu.dataset.page=on?'heroes':'play';
 for(const b of $('menunav').children){const selected=b.dataset.pg===menu.dataset.page;b.classList.toggle('sel',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}
 if(on){roster.scrollTop=0;$('rosterClose').focus({preventScroll:true});}
}
function installMobileLobby(){const menu=$('menu');if(menu.dataset.lobbyReady)return;installChapterMenu();menu.dataset.lobbyReady='true';menu.dataset.page='play';
 const nav=$('menunav');nav.innerHTML='';for(const [id,label,index]of [['play','Play',15],['heroes','Heroes',16],['relics','Gear',17],['vault','Upgrades',18],['settings','Settings',19]]){const b=document.createElement('button');b.type='button';b.className='navbtn'+(id==='play'?' sel':'');b.dataset.pg=id;b.setAttribute('aria-label',label);b.append(comicAtlas('archer',index,96));const t=document.createElement('span');t.textContent=label;b.append(t);nav.append(b);}

}
function showPage(pg){if(pg==='heroes'){openHeroRoster();return;}openHeroRoster(false);$('menu').dataset.page=pg;for(const id of ['play','relics','vault','settings'])$('pg'+id[0].toUpperCase()+id.slice(1)).hidden=id!==pg;for(const b of $('menunav').children){b.classList.toggle('sel',b.dataset.pg===pg);if(b.dataset.pg===pg)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}if(pg==='relics')buildRelicUI();if(pg==='vault')renderShop();if(pg==='play'){buildMapList();buildClassInfo();}}
const COMIC_GEAR={cls:null,set:null,item:null};
function renderRelics(box,cls){if(box.id!=='relics')return classicRenderRelics(box,cls);const sets=RELIC_SETS.filter(s=>s.cls===cls);if(COMIC_GEAR.cls!==cls){COMIC_GEAR.cls=cls;COMIC_GEAR.set=(sets.find(s=>s.build===MENU_BUILDS[cls])||sets[0]).id;COMIC_GEAR.item=null;}const S=sets.find(s=>s.id===COMIC_GEAR.set)||sets[0],items=S.items;COMIC_GEAR.set=S.id;if(!items.some(i=>i.id===COMIC_GEAR.item))COMIC_GEAR.item=items[0].id;const it=RELIC_BY[COMIC_GEAR.item],L=wornList(cls),slots=relicSlots();box.className='comicGear';box.replaceChildren();
 const hero=document.createElement('div');hero.className='gearHero';hero.append(comicPortrait(cls,S.build));const name=document.createElement('b');name.textContent=BUILD_INTRO[S.build][0];hero.append(name);box.append(hero);
 const loadout=document.createElement('div');loadout.className='gearLoadout';for(let i=0;i<5;i++){const b=document.createElement('button');b.type='button';b.className='gearSlot'+(i>=slots?' locked':'');if(L[i]){const r=RELIC_BY[L[i]];b.append(relicIcon(r.id,4));b.title=b.ariaLabel='Unequip '+r.name;b.onclick=()=>toggleWear(r.id,cls,box);}else if(i>=slots){b.innerHTML=comicLock();b.title=b.ariaLabel=i===3?'Beat Kings Grave to unlock this slot':'Beat Duskmoor to unlock this slot';b.onclick=()=>{$('gearNotice').textContent=b.title;};}else{b.textContent='+';b.title=b.ariaLabel='Empty relic slot';b.onclick=()=>{$('gearNotice').textContent='Choose a relic, then equip it here.';};}loadout.append(b);}box.append(loadout);
 const browser=document.createElement('section');browser.className='gearBrowser';const tabs=document.createElement('div');tabs.className='gearTabs';tabs.setAttribute('aria-label','Choose a build’s gear set');tabs.style.setProperty('--gear-set-count',sets.length);for(const s of sets){const b=document.createElement('button');b.type='button';b.dataset.set=s.id;b.style.setProperty('--set-accent',s.col||'#bad8ef');b.setAttribute('aria-pressed',String(COMIC_GEAR.set===s.id));b.append(comicPortrait(cls,s.build));const copy=document.createElement('span'),title=document.createElement('b'),subtitle=document.createElement('small');title.textContent=BUILD_INTRO[s.build][0];subtitle.textContent=s.name+' set';copy.append(title,subtitle);b.append(copy);b.onclick=()=>{COMIC_GEAR.set=s.id;COMIC_GEAR.item=null;renderRelics(box,cls);box.querySelector('[data-set="'+s.id+'"]').focus({preventScroll:true});};tabs.append(b);}box.prepend(tabs);
 const grid=document.createElement('div');grid.className='gearGrid';for(const r of items){const b=document.createElement('button');b.type='button';b.dataset.relic=r.id;b.className='gearItem'+(hasRelic(r.id)?' owned':'')+(wornRelic(r.id,cls)?' equipped':'');b.setAttribute('aria-pressed',String(it.id===r.id));b.setAttribute('aria-label',r.name+', '+(wornRelic(r.id,cls)?'equipped':hasRelic(r.id)?'owned':r.cost+' gold'));b.append(relicIcon(r.id,8));const t=document.createElement('span');t.textContent=wornRelic(r.id,cls)?'✓ Equipped':hasRelic(r.id)?'Owned':r.cost+' G';b.append(t);b.onclick=()=>{COMIC_GEAR.item=r.id;renderRelics(box,cls);};grid.append(b);}browser.append(grid);const bonus=document.createElement('p');bonus.className='gearBonus';const bonusTitle=document.createElement('strong'),bonusCopy=document.createElement('span');bonusTitle.textContent='5-PIECE SET BONUS';bonusCopy.textContent=S.bonus;bonus.append(bonusTitle,bonusCopy);browser.append(bonus);box.append(browser);
 const detail=document.createElement('section');detail.className='gearDetail';detail.setAttribute('aria-live','polite');const h=document.createElement('h3');h.textContent=it.name;const tier=document.createElement('strong');tier.textContent=RELIC_TIER_NAME[it.tier]+' · '+S.name;const p=document.createElement('p');p.textContent=itemDescription(it);const action=document.createElement('button');action.type='button';action.id='gearEquip';const owned=hasRelic(it.id),worn=wornRelic(it.id,cls),full=L.length>=slots;action.className='comicPrimary';action.textContent=worn?'UNEQUIP':owned?full?'SLOTS FULL':'EQUIP':'BUY · '+it.cost+' GOLD';action.disabled=owned?!worn&&full:vault.gold<it.cost;action.onclick=()=>{if(owned)toggleWear(it.id,cls,box);else buyRelic(it,cls,box);};const note=document.createElement('p');note.id='gearNotice';note.setAttribute('role','status');note.textContent=!owned&&vault.gold<it.cost?'Need '+(it.cost-vault.gold)+' more gold.':owned&&!worn&&full?'Remove a relic from your loadout to make space.':L.length+' / '+slots+' relic slots filled';detail.append(h,tier,p,action,note);box.append(detail);
}
function comicVaultDialog(mode){let d=$('vaultDialog');if(d)d.remove();d=document.createElement('dialog');d.id='vaultDialog';d.className='comicDialog';d.innerHTML='<header><h2>'+(mode==='export'?'Back up your vault':'Restore your vault')+'</h2><button type="button" aria-label="Close vault backup">×</button></header><p>'+(mode==='export'?'Keep this code somewhere safe. It carries your progress to another device.':'Paste a saved vault code. Your earned gold, upgrades and clear records will be kept.')+'</p><label for="vaultCodeText">Vault code</label><textarea id="vaultCodeText" spellcheck="false" autocomplete="off"></textarea><p id="vaultDialogStatus" role="status"></p><footer><button type="button" class="comicSecondary">Cancel</button><button type="button" class="comicPrimary" id="vaultDialogApply">'+(mode==='export'?'Copy code':'Restore')+'</button></footer>';document.body.append(d);const text=d.querySelector('textarea'),status=$('vaultDialogStatus');if(mode==='export'){text.value=vaultCode();text.readOnly=true;}d.querySelector('header button').onclick=d.querySelector('.comicSecondary').onclick=()=>d.close();$('vaultDialogApply').onclick=async()=>{if(mode==='export'){try{await navigator.clipboard.writeText(text.value);status.textContent='Copied. Save this code somewhere safe.';}catch(e){text.focus();text.select();status.textContent='Code selected. Use your device’s Copy action.';}}else if(loadVaultCode(text.value)){status.textContent='Vault restored.';$('vaultmsg').textContent='Vault restored.';relicRefreshGold();buildRelicUI();buildMapList();buildClassInfo();sfx('level');d.close();}else status.textContent='That code did not work. Check that the entire BS1- code was pasted.';};d.showModal();text.focus();if(mode==='export')text.select();}
// Mobile build stories: flavor, playstyle, and the actual command in the selected control mode.
const BUILD_STORIES={
 sb:['The horde breaks here.','Hold the front line. Punish blows with Thorns, then shove a path through the crowd.','Shield Push','shield','Tap to brace. When the crowd pushes you back, keep tapping to heave them away.'],
 gs:['One blade. A very bad crowd.','Cut through packs with heavy cleaves. Leap into position and spend Fury on Bladestorm.','Bladestorm Boost','whirl','Once Bladestorm is learned, hold Spin to accelerate it. Release to recover Fury.'],
 hal:['Drag them close. Leave them bleeding.','Fight at the blade’s edge. Hook enemies together, break their guard, and leave deep wounds.','Impale','impale','Charge in your movement direction and pass through enemies. WASD or thumbstick sets direction; aim when standing still. Walls and unsafe terrain stop the charge.'],
 k_trap:['The bait is free. The lesson isn’t.','Lead pursuers into traps. Catches trigger Locked N’ Loaded: rapid gunfire that shreds the crowd.','Baited Trap','bear','Automatic in one-thumb mode. Catches grant 4s of faster gunfire, longer range and explosive pellets.'],
 k_clock:['Some assembly. Much destruction.','Deployments rally your machines around you. At your turret cap (8, or 10 with the full set), reload a matching machine for 3 stronger attacks. Sentries defend, long flames sweep packs, and heavy bolts focus priority targets. Your backup shotgun gains 5% damage per level after level 1, up to +100% at level 21, without upgrade picks.','Bastion','sentry','Rally a moving turret guard and fire heavy cannonballs with impact splash. Sentry ranks strengthen the cannon. Escort turrets intercept enemy shots. Dash with your turret guard without dismounting. After Bastion: 20% less damage for 1.5s. 10s · 30s cooldown from activation.'],
 k_bomb:['A short fuse solves most problems.','Lob grenades into packed crowds. Place powder kegs automatically, then choose the moment to blow them.','Detonate','keg','Tap to ignite your placed keg for its empowered explosion. Grenades can still ignite it. A new keg waits until the old one is used.'],
 b_peace:['Hush now. This is the last verse.','Lull enemies to sleep, weaken them with Discordance, and let your lingering songs wear them down.','Requiem','lullaby','After learning Lullaby, tap to damage every sleeping foe as if inside its circle. 6s · 30s cooldown.'],
 b_sonic:['Every horde needs a headliner.','Send piercing notes through the crowd. Stack resonance, win over listeners, and turn their ranks into your audience.','Showtime','finale','Win over 30 foes to unleash 6s of musical damage pulses. Triggers automatically in one-thumb mode.'],
 n_rot:['A cure was never the plan.','Wade close to spread decay, then keep moving. Poison and rot pass through the crowd and finish your work.','Virulence','pestilence','Tap to increase damage over time by 30% for 6s. Infect the crowd first, then let it wither. 30s cooldown.'],
 n_bone:['The grave still has a few sharp ideas.','Line up piercing bone spears through your Rib Cage. Returning ribs and crushing bones punish trapped packs.','Quicken','spear','Tap for 30% faster attacks for 6s. More spear volleys trigger more cage attacks. 30s cooldown.'],
 a_fire:['Leave the horde in ashes.','Keep your distance, spread fire, and ignite oil with Dragon Shot to turn crowded paths into a furnace.','Quicken','firearrows','Tap for 30% faster attacks for 6s. Pour arrows into the crowd before the flames fade. 30s cooldown.'],
 a_ice:['Winter does not negotiate.','Slow the advance, freeze packed enemies, then shatter them with direct hits. Keep your distance while the ice holds.','Quicken','icearrows','Tap for 30% faster attacks for 6s. Build chill quickly and strike frozen targets. 30s cooldown.'],
 a_light:['Thunder has found its mark.','Keep moving while shocked enemies become lightning rods. Chaining arcs and critical strikes tear through clustered foes.','Ball Lightning','balllightning','A learned automatic attack: a slow orb lashes nearby enemies with lightning as it travels. No extra command button.']
};
function buildCommandInfo(id){const v=BUILD_STORIES[id],out={name:v[2],icon:v[3],text:v[4],type:['k_trap','b_sonic','a_light'].includes(id)?'Signature ability':'Command'};
 if(!TOUCH_SIMPLE){const manual={a_fire:['Dragon Dash','dragonshot','After learning Dragon Shot, dash to unleash a free flame dragon along your aim.'],a_ice:['Frost Trap','icetrap','Aim and place a frost trap. Its five waves build chill and freeze the crowd. Learn Frost Trap first.'],n_bone:['Rib Cage','prison','Aim and place a cage. Spear volleys call returning ribs and charge Rib Crush. Learn Rib Cage first.'],k_bomb:['Powder Keg + Candle','keg','Place a keg and ignite it with grenades. Hold Candle to spend Powder on rockets.'],hal:['Hook & Hew + Impale','hook','Hook the pack into your blade, then hew. Use Impale to charge along your movement direction.'],k_trap:['Baited Trap','bear','Aim and place a baited trap. A catch grants 4s of Locked N’ Loaded.'],b_sonic:['Showtime','finale','Win over 30 foes, then tap Showtime for 6s of musical pulses. Keep moving while you perform.']};if(manual[id]){[out.name,out.icon,out.text]=manual[id];out.type='Command';}}
 return out;
}
function buildCommandBlock(id){const info=buildCommandInfo(id),row=document.createElement('div');row.className='buildCommandBlock';const icon=mk(64,64);icon.setAttribute('aria-hidden','true');icon.getContext('2d').drawImage(iconFor({id:info.icon,icon:info.icon,name:info.name}),0,0,64,64);const copy=document.createElement('div'),name=document.createElement('strong'),text=document.createElement('p');name.textContent=info.name;text.textContent=info.text;copy.append(name,text);row.append(icon,copy);row.setAttribute('aria-label',info.type+': '+info.name);return row;}
for(const [id,v]of Object.entries(BUILD_STORIES)){BUILD_INTRO[id][1]=v[0];BUILD_INTRO[id][2]=v[1];BUILD_INTRO[id][3]=v[4];}
